[Theorem 3 of arXiv:2607.13273, 'Asymptotics of transition densities for L\'evy processes with stochastic resetting'] Let $\alpha\in (0,2), m>0$ and $\boldsymbol{Y}$ be the relativistic stable process.
    Then the density $p_\lambda$ of the corresponding process $\boldsymbol{X}$ with resetting exists for all $\lambda>0, t>0$ and,  for any $x\in\Rd$,:
    \begin{enumerate}
        \item If $\lambda > m $ then
        \begin{align*}
          p_\lambda(t,x,y) 
          &\sim  \frac{\lambda\alpha m^{\frac{d+\alpha-1}{2\alpha}}}{2^{\frac{d-\alpha+1}{2}}\pi^{\frac{d-1}{2}}\Gamma(1-\frac{\alpha}{2})(\lambda-m)^2} \frac{e^{-m^{1/\alpha}|y|}}{|y|^{\frac{d+\alpha+1}{2}}} .
    \end{align*}
    \item If $\lambda = m$  then
        \begin{equation*}
        p_\lambda(t,x,y) \sim \frac{m^{\frac{d+\alpha-1}{2\alpha}}e^{-m^{1/\alpha}|y|}}{2^{\frac{d+\alpha-1}{2}}\pi^{\frac{d-1}{2}} |y|^{\frac{d-\alpha+1}{2}}}
        \int_0^{\frac{\sqrt{2^\alpha m}}{|y|^{\alpha/2}}t}\eta(s,1)\, \dx[s].
    \end{equation*}

    \item If $\lambda < m$ and $\frac{t}{|x|^{\alpha/2}}<M$ for some constant $M>0$ then
       \begin{equation*}
        \begin{split}
            p_\lambda(t,x,y) & \sim 
            \left(\lambda + e^{m^{1/\alpha}\langle \frac{y}{|y|},x\rangle }\frac{\eta\left(\frac{t}{|y-x|^{\alpha/2}}\sqrt{2^\alpha m},1\right) (m-\lambda)}{\eta\left(\frac{t}{|y|^{\alpha/2}}\sqrt{2^\alpha m},1\right)}\right) \\
            &\times \frac{ m^{\frac{d-\alpha-1}{2\alpha}}e^{-m^{1/\alpha}|y|}}{2^{\frac{d+\alpha-1}{2}}\pi^{\frac{d-1}{2}}|y|^{\frac{d-\alpha+1}{2}}}
        \int_0^{\frac{\sqrt{2^\alpha m}}{|y|^{\alpha/2}} t} e^{(m-\lambda)\frac{|y|^{\alpha/2}}{\sqrt{2^\alpha m}}s} \eta(s,1)\, \dx[s].
        \end{split}
    \end{equation*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:limit MC of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Fix $q\in(0,1)$ and $c\in[0,1)$.  Then
    \begin{equation}
        \begin{split}
            \overline{\mathsf{p}}_0\left(\lambda\right)& = (1-c)^2c^{\lambda_1-\lambda_2}\left(\lambda_1-\lambda_2+1\right){\bf 1}_{\{\lambda_2=0\}},\\
            \overline{\mathsf{p}}\left(\mu,\lambda\right)&=(1-q)^2s_{\lambda/\mu}(q)\frac{\lambda_1-\lambda_2+1}{\mu_1-\mu_2+1}\quad\mbox{ for }x \in \mathbb{Z}_{\geq0},
        \end{split}
    \end{equation}
are the initial and transitional laws of a time-homogeneous Markov chain $\{\lambda^j\}_{j=0}^{\infty}$ on state space $\mathsf{Sign}_2$.

[Defn 24 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Given integers $N\geq1$ and $M\geq0$ such that $N+M$ is even, and given an ordered set of coordinates $y=(y_1,\dots,y_M)$ satisfying $y_M>N-M+1$ ($y=\emptyset$ if $M=0$), we define a measure on $\Lambda_N$ corresponding to half-space TASEP with initial condition $y$ as follows:
    \begin{equation}

        \mathcal{W}_{N,M}(\bm{z}| y) = \prod_{k=1}^{N} \det[\begin{array}{c}
            \phi_k\!\left(z_i^{k-1},z_j^{k}\right)_{1\leq i\leq k-1\atop1\leq j\leq k} \\[8pt]
            \phi_k\!\left(\vir_{k},z_j^{k}\right)_{1\leq j\leq k} 
        \end{array}]\pf\left[\begin{array}{cc}
        \Psi(z_i^N,z_j^N)_{1\leq i,j\leq N} & \Xi_{N-k}(z_i^N)_{1\leq i\leq N\atop 1\leq k\leq M} \\[8pt]
        -\Xi_{N-k}(z_j^N)_{1\leq k\leq M\atop 1\leq j\leq N} & 0
    \end{array}\right].
    \end{equation}
    Due to \eqref{eq:GT det identity def}, the restriction of this measure to $\Lambda_N(x)$, with $x_1>x_2>\dotsm>x_N$, is supported on Gelfand--Tsetlin patterns.

