[Lemma lem:subgamma of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Let $\tilde\sigma^2 > 0$ and $c > 0$. 
Consider the convex function on $[0, 1/c)$
\begin{align}
\phi(k) = \frac{k^2\tilde\sigma^2}{2(1 - ck)}.
\end{align}
Its Legendre transform $\phi^\ast(a)$ is, for $a > 0$,
\begin{align}
  \phi^\ast(a)
  \equiv \sup_{0 \leq k < 1/c}\left[ka - \frac{\tilde\sigma^2 k^2}{2(1 - ck)}\right]
  = \frac{\tilde\sigma^2}{c^2}h\left(\frac{c a}{\tilde\sigma^2}\right),

\end{align}
with supremum attained at $k^\ast = c^{-1}\bigl(1 - \sqrt{\tilde\sigma^2/(\tilde\sigma^2 + 2ca)}\bigr) > 0$
and we define the auxiliary function $h(u) \equiv 1 + u - \sqrt{1 + 2u}$.
Moreover, we have $h(u) \geq u^2/[2(1+u)]$ for $u \geq 0$, i.e.,
\begin{align}
  \phi^\ast(a) \geq \frac{a^2}{2(\tilde\sigma^2 + ca)}.

\end{align}

[Definition of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] Let $\{\mu_N\}_{N\in\mathbb N}$ be a sequence of probability measures in $\Omega_N$ and let $v_0$ and $e_0$ be measurable real-valued functions defined on $\mathbb T$.
We say the sequence $\{\mu_N\}_{N\in\mathbb N}$ is associated to $(v_0,e_0)$ if for every real-valued continuous function $G$ on $\mathbb T$ and for every $\delta>0$ we have that 
\begin{equation*}
\lim_{N\to\infty}\mu_N\bigg( \eta\in\Omega_N \,;\,  
\Big| \frac{1}{N} \sum_{x\in\mathbb T_N} \eta(x) G\Big(\frac xN\Big) - \int_{\mathbb{T}}G(u)v_0(u)du \Big| > \delta\bigg) =0
\end{equation*}
and 
\begin{equation*}
\lim_{N\to\infty}\mu_N\bigg( \eta\in\Omega_N \,;\,  
\Big| \frac{1}{N} \sum_{x\in\mathbb T_N} \eta(x)^2 G\Big(\frac xN \Big) - \int_{\mathbb{T}}G(u)e_0(u)du \Big| > \delta\bigg) =0.
\end{equation*}

