\begin{align}
K_b<\min\left\{\frac{2\beta^4}{\text{\rm{e}}^{\frac{2\beta^2}{\delta}r_0}(K_2-K_\sigma)\delta^2},
\frac{2(K_2-K_\sigma)\text{\rm{e}}^{-2(K_2-K_\sigma)r_0}}{6}\right\}
 \end{align}
 for $\delta=\int_0^\infty s\text{\rm{e}}^{\frac{1}{2\beta^2}\int_0^s\{\gamma(v)+K_\sigma v\}\text{\rm{d}} v}\text{\rm{d}} s$.
 Then
