[Proposition 10 of arXiv:2608.28528, 'Strong solutions of SDEs with critical discontinuities in diffusion coefficients'] Let $X_t^x=X_{0,t}^x$ be the strong solution to \eqref{sde0}. Then, 
for every integer $p \geq 2$, there exist constants $K_1$, $K_2$ independent of the smoothness of $\sigma$ such that

\begin{enumerate}[label=\rm(\textit{\roman*})]
\item
\begin{equation}

 \sup_{y \in \mathbb R^d}\|\nabla X_t^x - I\|_{L^{2p}(B_1(y), \, L^p(\Omega))} \leq K_1 t^{\frac{1}{4p}}
\end{equation}
for all $0 \leq t \leq T$;

\item
\begin{equation}

 \sup_{y \in \mathbb R^d} \|D_sX_t^x - \sigma(s, X_s^x)\|_{L^{2p}(B_1(y), \, L^p(\Omega))} \leq K_1|t-s|^{\frac{1}{4p}}
\end{equation}
for a.e. $s \in [0,T]$ and $0 \leq s \leq t \leq T$;

\item
\begin{equation}

 \sup_{y \in \mathbb R^d} \|D_s X_t^x - D_{s'}X_t^x\|_{L^{2p}(B_1(y), \, L^p(\Omega))} \leq K_2 \big(|s'-s|^{\frac{1}{8p}} +  |s'-s|^{\frac{\gamma}{2p}}\big)
\end{equation}
for a.e. $s,s' \in [0,T]$ and $0 \leq s,s' \leq t \leq T$.
\end{enumerate}

