body:
[Theorem 18 (Threshold phenomenon) of arXiv:2604.25877, 'Asymptotic height of Plancherel random trees'] Let $h=h(n)\ge0$ and $r_n=(n-1)/(n-1+\theta)$.
\begin{enumerate}
\item If $\Phi_{h(n)-1}(r_n)\to0$, then $q_n(h(n))\to1$.
\item If $\Phi_{h(n)-1}(r_n)\to\infty$, then $q_n(h(n))\to0$.
\end{enumerate}

[Lemma 17 of arXiv:2607.16479, 'The Site Frequency Spectrum in an Exponentially-Growing Population with Selection'] Define:
  \begin{align}
      I_t(n)=\int_{ne^{-\lambda_1t}}^{n}\frac{\lambda_1u^{\frac{\lambda_0}{\lambda_1}}}{((a+b)-d(u/n))^2}\left(\frac{(a+b)n-(a+b)u}{(a+b)n-du}\right)^{n-1}\,du
  \end{align}
  Then for $j(t):\mathbb{R}_{\geq 0}\to\mathbb{N}$:
  \begin{align}
    \mathbb{E}[S_{j(t)}(t)]=(av+\mu)e^{\lambda_0 t}j(t)^{-\frac{\lambda_1+\lambda_0}{\lambda_1}}I_t(j(t))
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2609.01166, 'Nonparametric inference for density-dependent McKean--Vlasov diffusions'] For any bounded interval $J$ and $\beta>0$ fixed, there exists a constant $C_{\beta,J}$ such that, for all $F\in L^2(J)\cap\mathcal H^{\beta+1}(J)$,
\begin{equation}
 \norm{F'}_{L^2(J)} \leq C_{\beta,J} \norm{F}_{L^2(J)}^{\beta/(\beta+1)} \norm{F}_{\mathcal H^{\beta+1}(J)}^{1/(\beta+1)}.
\end{equation}

[Lem typT poly LB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exists a constant $a_1 \in (0, \infty)$ such that, for all sufficiently large $\ell \in \mathbb{N}$,
  \begin{equation}
    \inf_{\bm{x} \in \hat{B}_*(x_0,c_2 \delta_\ell^{1/d^{\mathrm{min}}_\mathrm{w}})}
    \hat{P}_{\bm{x}}\bigl( C_{\delta_\ell} \geq a_1 \Psi_{\mathrm{ct}}(\delta_\ell) \bigr) 
    \geq 
    \tilde{c}\, \ell^{-1/2},
    \qquad 
    \forall x_0 \in M,
  \end{equation}
  where the constant $c_2$ is recalled from Lemma~(lem:CT LB of the paper).

