[Corollary 36 (Algebra representations) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Let $\pi:\cA\to\cL(H)$ be an algebra representation, and let
$1\le r,r_1,r_2\le\infty$ satisfy $1/r=1/r_1+1/r_2$.  Then
\begin{equation}

 b_r(\pi(ab);L,Q)
 \le\sum_R b_{r_1}(\pi(a);L,R)b_{r_2}(\pi(b);R,Q).
\end{equation}
If $\pi$ is a $*$-representation, then
\begin{equation}

 b_r(\pi(a^*);L,Q)=b_r(\pi(a);Q,L).
\end{equation}

[Defi def:cPI of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] The (classical) \emph{Poincar\'e inequality (PI)} is satisfied if there exists a constant $\alpha>0$ such that
\begin{equation}
    \forall f\in \ensuremath{\mathbb{R}}^{|\ensuremath{\mathbb{Z}}|}: \ \ \operatorname{var}_\pi(f)\leq \frac{1}{\alpha}\mathscr{E}_\pi(f).
\end{equation}
The supremum over all possible choices of  $\alpha$ is called the \emph{Poincar\'e constant}. We denote it by
\begin{equation}
    \alpha_{\PI}(M) \coloneqq \inf_{\substack{f\in\ensuremath{\mathbb{R}}^{|\ensuremath{\mathbb{Z}}|} \\ f\notin \langle\1\rangle}} \frac{\mathscr{E}_\pi(f,M)}{\operatorname{var}_\pi(f)}.
\end{equation}

[Theorem thm:two.point.barycenter.filtered.gaussian of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] One has
\begin{equation}

\inf_{\mathbb{Z}\in\mathcal{FG}}
\left\{(1-u)\mathcal{AW}_2^2(\mathbb{X}_0,\mathbb{Z})+u\mathcal{AW}_2^2(\mathbb{X}_1,\mathbb{Z})\right\}
=u(1-u)\mathcal{AW}_2^2(\mathbb{X}_0,\mathbb{X}_1),
\end{equation}
and $\mathbb{G}^{\hat a_u,\hat L_u}$ is a minimizer.  Conversely, if $\mathbb{Z}=\mathbb{G}^{b,M}$ is a minimizer, then $b=\hat a_u$ and there exist $Q\in\mathscr Q(L_0,L_1)$ and $R\in\mathscr O(T,d)$ such that
\begin{equation}

M=((1-u)L_0+uL_1Q)R.
\end{equation}
Thus, the set of two-point barycenters in $\mathrm{FG}$ is the collection of equivalence classes generated by (equation eq:two.point.interpolation of the paper) as $Q$ ranges over $\mathscr Q(L_0,L_1)$.

[Lemma 7 of arXiv:2608.11031, 'A Bayesian Proof of the Bernoulli Theorem'] For any $x\in T$ and almost every $t>0$,
\begin{equation}
  \Phi_x'(t)
  \ge
  \frac{1}{4\pi}
  \E_Z\varphi_t\bigl(x,\widehat x^{\mathrm{loc}}(x+tZ)\bigr).

\end{equation}

[Prop lambda_conv of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $1<p<2$. The space $(X^{a,b}_{p,p'},\mathscr W_p)$ is a complete geodesic metric space. Moreover,  the functional $\mathcal F_{\beta}$ is weakly $\lambda$-geodesically convex on  $(X^{a,b}_{p,p'},\mathscr W_p)$ with $\lambda=\beta a^{-\frac{2-p}{p}}$, i.e., for $\mathsf{P}_0,\mathsf{P}_1\in X^{a,b}_{p,p'}$ there exists a constant speed geodesic $(\mathsf{P}_t)_{0\leq t\leq 1}$ such that for any $0\leq t\leq 1$
    \begin{align*}
        \mathcal F_\beta(\mathsf{P}_t)\leq (1-t) \mathcal F_\beta(\mathsf{P}_0)+t \mathcal F_\beta(\mathsf{P}_1)-\lambda \frac{t(1-t)}{2} \mathscr W_p^2(\mathsf{P}_0,\mathsf{P}_1).
    \end{align*}

[Lem le.finiteLcin of arXiv:2411.13099, 'Long time behavior of killed Feynman-Kac semigroups with singular Schr{ö}dinger potentials'] For all $\mathsf y\in \mathscr R^{2d}_0$,  
\begin{equation}
\mathbb P_{\mathsf y}[\forall t\ge 0, |x_t|>0]=1.
\end{equation}
In particular, for all $\mathsf y\in \mathscr R^{2d}_0$ and $t\ge 0$, $\mathbb P_{\mathsf y}[Y_{[0,t]} \in \mathcal C([0,t], \mathscr R^{2d}_0)]=1$, and,  if   {\rm\textbf{[S1]}} or {\rm\textbf{[S2]}} holds,   $ \int_0^t  \mathbf V_{\mathbf S}(x_s(\mathsf y))ds$ is  a.s.  finite. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:xibi of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] Using the above $\Xi$, $\Xi_1$, $\Xi_2$, $\Xi_3$, $\Xi_4$ notations, we define
\begin{equation} 
\mathbf I_{\beta,\vec\mathbf k}[\vec\mathbf p,\vec\boldsymbol{\upsilon}, \mathbf H]=2^{-\boldsymbol{\delta}-|\{\ell\in\llbracket 1,m\rrbracket: \boldsymbol{\upsilon}_\ell\neq\varnothing\}|}\prod_{(x,y)\in\Xi} \mathbf I_\beta[x,y],
\end{equation}
where
\begin{equation*}
\mathbf I_\beta[x,y]=
\begin{cases}
\exp\big(\beta^{-1}(y-x)(\mathbf H(x)-\mathbf p^0(x))\big)\mathbf I_{0,0}(y-x), & (x,y) \in \Xi_1, \\
\exp\big(\beta^{-1}(y-x)(\mathbf H(x)-\mathbf p^0(x))\big) \mathbf I_0(y-x; \mathbf H(y)-\mathbf H(x)), & (x,y) \in \Xi_2, \\
(-1)^{\mathds 1[\mathbf p^0(x)<\mathbf p^0(x-)]}\mathbf I_0(y-x;\mathbf H(x)-\mathbf H(y)) , & (x,y) \in \Xi_3, \\
(-1)^{\mathds 1[\mathbf p^0(x)<\mathbf p^0(x-)]} \mathbf I(y-x;\mathbf H(x)-\mathbf p^0(x), \mathbf H(y)-\mathbf p^0(y_-) ), & (x,y) \in \Xi_4.
\end{cases}
\end{equation*}

[Proposition expand_class of arXiv:2506.06559, 'Bi-infinite incipient cluster in high dimensions'] Let $G$ be a connected  simple graph with  three labelled vertices $0,u,u'$. Assume that $G$ is 3-connected to $\{0,u,u'\}$, that all vertices in $V(G)\setminus \{0,u,u'\}$ have degree 3 and that $0$, $u$, $u'$ all have degree 2. Then, all the graphs in the generalized diagrammatic graphs $(G\circledast u^+) \uplus G^{(1)}$,  $(G\circledast y) \uplus G^{(2)}$ and $(G\circledast^2 y) \uplus G^{(3)}$ are  3-connected to $\{0,u,u^+\}$ where $y \notin \{0,u,u'\}$ the graphs $G^{(1)}$, $G^{(2)}$ and $G^{(3)}$ are respectively
 \[
\begin{minipage}{0.3\textwidth}
      \includegraphics[width=0.5\linewidth]{add10-eps-converted-to.pdf}
    \end{minipage}
    \begin{minipage}{0.3\textwidth}
      \includegraphics[width=0.6\linewidth]{add20-eps-converted-to.pdf}
    \end{minipage}
        \begin{minipage}{0.3\textwidth}
      \includegraphics[width=0.6\linewidth]{add30-eps-converted-to.pdf}
    \end{minipage}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] We define a time--dependent $\beta$-stochastic operator formally expressed as
    \begin{equation}
        \mathcal{H}_{\beta}(t) := -\frac{d^2}{dx^2}+x+\frac{2}{\sqrt{\beta}}\xi_1(t).
    \end{equation}
    More precisely, for $f \in H^{1,1}_{0}(0,\infty):= \{u \in L^2(0,\infty): u',xu \in L^2(0,\infty), u(0)=0\}$, define $\mathcal{H}_{\beta}(t)f$ as the distribution such that for any $g \in C_0^{\infty}(0,\infty)$,
    \begin{equation}
        \langle \mathcal{H}_{\beta}(t) f,  g \rangle := \int_{0}^{\infty} (f'(x) g'(x)+xf(x)g(x))dx+\frac{2}{\sqrt{\beta}}\int_{0}^{\infty} f(x)g(x) \xi_1(t)[dx],
    \end{equation}
    with $\int_{0}^{\infty} f(x)g(x) \xi_1(t)[dx] = \langle \xi_1(t), f(x)g(x) \rangle$.

[Defn of arXiv:2411.09988, 'A Study in Markov Chains, Loop-Erased Random Walk and Loop Soups'] If $\omega = [\omega_0, \omega_1, \ldots, \omega_n]$ is a path, then its \textit{(chronological) loop erasure}, denoted by $LE(\omega)$, is the SAW $\eta = [\eta_0, \eta_1, \ldots, \eta_k]$ defined as follows.
    \begin{itemize}
        \item Set $\eta_0: = \omega_0$.
        \item If $\omega_n = \omega_0$, we set $k=0$ and terminate; otherwise, let $\eta_1$ be the first vertex in $\omega$ after the last visit to $\omega_0$, that is, $\eta_1: = \omega_{i+1}$, where $i: = max\{j; \omega_j = \omega_0\}$.
        \item If $\omega_n = \eta_1$, then we set $k=1$ and terminate; otherwise, let $\eta_2$ be the first vertex in $\omega$ after the last visit to $\eta_1$, and so on.
    \end{itemize}

[Definition of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] Let $\Omega = \{0, 1\}^E$ with $E$ at most countable. For $\omega \in \Omega$ and $F, G \subset E$ such that $F \cap G = \emptyset$, we denote
  \begin{equation}
    \omega^F_G : e \in E \mapsto \begin{cases}
      1 & \text{ if } e \in F \\
      0 & \text{ if } e \in G \\
      \omega(e) & \text{ otherwise}
    \end{cases}
  \end{equation}
  If $F$ or $G$ is empty, we omit it. If $F$ or $G$ is a singleton $\{e\}$, we write $e$ instead of $\{e\}$\footnote{We always write $\omega(e)$ for the actual value of the $e$-component of $\omega$ in order to avoid confusion.}.
  Consider an increasing event $A \subset \Omega$. We define the event that $e \in E$ is pivotal for $A$ to be
  \begin{equation}
    \{\omega \in \Omega: (\omega_e \notin A) \wedge (\omega^e \in A)\}.
  \end{equation}

[Definition Def_FamilyOfLocalResidueConditions of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Here is how to consider local residue conditions in families:
  \begin{enumerate}
  \item
    \begin{enumerate}
    \item
      The \defined{universal branching locus} is the tame Fréchet submanifold
      \begin{equation*}
        \mathbf{Br}
        \coloneq
        \set[\big]{
          ({\mathbf{p}},[{\mathfrak l}];x) \in \mathbf{Dir} \times \mathbf{Ram} \times X : x \in \mathrm{Br}({\mathfrak l})
        }
        \subseteq
        \mathbf{Dir} \times \mathbf{Ram}\times X.
      \end{equation*}
      The projection map $p \mskip0.5mu\colon\thinspace \mathbf{Br} \to \mathbf{Dir} \times \mathbf{Ram}$ is a fibre bundle.
    \item
      The normal bundle ${\mathbf{N}} \coloneq N\mathbf{Br}$ shall be identified with
      \begin{equation*}
        {\mathbf{N}} = \coprod_{({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir} \times \mathbf{Ram}} N\mathrm{Br}({\mathfrak l}).
      \end{equation*}
      It inherits a Euclidean metric from the metrics on $X$ which are part of ${\mathbf{p}} \in \mathbf{Dir}$.
      This induces an isomorphism $(\Lambda^2 {\mathbf{N}})^{\otimes 2} \cong \mathbb{R}$ and endows
      \begin{equation*}
        \mathbb{A} \coloneq \mathbb{R} \oplus i \Lambda^2 {\mathbf{N}}
      \end{equation*}
      with the structure of a bundle of algebras over $\mathbf{Br}$,
      whose fibres are isomorphic to $\mathbb{C}$, but canonically only up to complex conjugation.
    \item
      The construction from  [BeraWalpuski2025] explained in (Sec_ResidueMap of the paper), parametrised by $({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir} \times \mathbf{Ram}$, assembles into an $\mathbb{A}$--module ${\mathbf{N}}^{-1/2}$.      
    \item
      Clifford multiplication endows $\mathrm{pr}_X^*S$ to $\mathbf{Br}$ with the structure of an $\mathbb{A}$--module.    
      The \defined{universal residue bundle} is the rank $r$ Euclidean bundle over $\mathbf{Br}$ defined by
      \begin{equation*}
        \check {\mathbf{S}} \coloneq
        \mathrm{pr}_X^*S \otimes_\mathbb{A} {\mathbf{N}}^{-1/2}
        =
        \coprod_{({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir} \times \mathbf{Ram}} \check S_{\mathbf{p}}.
      \end{equation*}
    \end{enumerate}
  \item
    A \defined{family of local residue conditions} $({\mathbf{B}},f,{\mathbf{V}})$ consists of:
    \begin{enumerate}
    \item
      a tame Fréchet manifold ${\mathbf{B}}$,
    \item
      a tame smooth map $f \mskip0.5mu\colon\thinspace {\mathbf{B}} \to \mathbf{Dir} \times \mathbf{Ram}$, and
    \item
      a subbundle ${\mathbf{V}} \subseteq (p^*f)^* \check {\mathbf{S}}$.
    \end{enumerate}
    Here $f^*p \mskip0.5mu\colon\thinspace f^*\mathbf{Br} \to {\mathbf{B}}$ is the pullback of the universal branching locus and $p^*f \mskip0.5mu\colon\thinspace f^*\mathbf{Br} \to \mathbf{Br}$ is the projection map;
    see (Fig_FamiliesOfLocalResidueConditions of the paper).
  \item
    A family of local residue conditions $({\mathbf{B}},f,{\mathbf{V}})$ defines a family of residue conditions $({\mathbf{B}},f,{\mathbf{R}})$
    such that for every $b \in {\mathbf{B}}$ 
    \begin{equation*}
      {\mathbf{R}}_b \coloneq \Gamma(Z_b,{\mathbf{V}}|_{Z_b}) \subseteq \Gamma(Z_b,\check S_{{\mathbf{p}}_b})
      \quad\text{with}\quad    
      ({\mathbf{p}}_b;Z_b,[{\mathfrak l}_b]) \coloneq f(b).
      \qedhere
    \end{equation*}
  \end{enumerate}

