[Lemma lem:whitenoiseregularity of arXiv:2607.24640, 'The Yang-Mills measure on surfaces via Morse theory'] For every $\psi\in L^\infty(\Sigma, \mathbb{R} )$, the random series
\begin{equation}
F_\psi^N:=\sum_{n= 1}^N\sum_{\ell=1}^L  X_{n,\ell} \psi e_n \mathfrak{b}_\ell    
\end{equation}
converges almost surely to some limit $F_\psi$ in $L^2(\Omega,H^{-1-\kappa}(\Sigma,\mathfrak{g}))$ for all $\kappa>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 (Chart invariance of first-order criteria) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Let $\psi:(\widetilde\Theta,\widetilde\theta_0)\to(\Theta,\theta_0)$ be a $C^1$ local reparameterization with invertible derivative at $\widetilde\theta_0$, and let $\widetilde q_{\cQ}^{(m)}:=q_{\cQ}^{(m)}\circ\psi$. Identify a tangent block $\widetilde T\subset T_{\widetilde\theta_0}\widetilde\Theta$ with $T:=D\psi(\widetilde\theta_0)\widetilde T\subset T_{\theta_0}\Theta$. Then for every visible depth $m$,
\begin{equation}
D\widetilde q_{\cQ}^{(m)}(\widetilde\theta_0)|_{\widetilde T} = Dq_{\cQ}^{(m)}(\theta_0)|_T\circ
D\psi(\widetilde\theta_0)|_{\widetilde T}.
\end{equation}
Consequently, the rank of the restricted derivative, kernel inclusions between visible depths on corresponding tangent blocks, first-order local sufficiency, and the minimal informative window $m_*(T,\theta_0)$ are invariant under $C^1$ reparameterization.

[Lemma 12 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $1< p<\infty$, $\max\{1,p-1\}\le q<\infty$ and $\la>0$. 
Assume that $|F|\in L^{q}_{\loc}(\Omega_T)$ and that $u\in  L^q_{\loc}(0,T;W^{1,q}_{\loc} (\Om;\mathbb{R}^N))$ satisfies \eqref{p_weak_sol}
 for every $\varphi\in C_0^\infty(\Om_T;\mathbb{R}^N)$. Moreover, assume  that there exists a parabolic cylinder $Q=\Qla \Subset\Omega_T$ and a constant $\gamma\ge 1$ such that
 \begin{equation}
    \gamma^{-1}\lambda \le \biggl( \fiint_Q (|\na u|+|F|)^q\, dz \biggr)^\frac{1}{q} \le \gamma \lambda.
\end{equation}
Then there exists a constant $c=c(n,p,q,L,\gamma)$ such that
	\begin{equation}
    \fiint_{Q}\frac{|u-u_{Q }|^{q}}{\rho^{q}}\,dz \le c\fiint_{Q}  ( |\na u| + |F| )^{q} \,dz.
    \end{equation}

[Proposition 1 (Center accuracy after local calibration) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] Fix smooth localized score tests around a bounded reference offset. If the resulting exact tangent-model least-squares matrix has full column rank, then using the finite-noise score from \cref{thm:expansion} returns a physical center of the form
\begin{equation}
c_\sigma=x_0+\sigma^2b+O(\sigma^{2+\alpha})

\end{equation}
for some bounded $b\in\R^D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 28 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] [\textbf{One-block estimate}] 
	Let $\gamma >0$, $0 \leq t \leq T$, $n \in \mathbb{N}_+$ and $ \widehat{b}_n \in \mathbb{R}$. Then
	\begin{align*}
		\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \widehat{b}_n \int_0^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )    \big[  \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _{x+1}^{\beta}( \eta_r^n ) - \Psi_{x, \ell_n}^{\alpha,\beta}(\eta_r^n) \big]  \Bigg\}^{2} \Bigg] \leq C t  \frac{ n (\widehat{b}_n \ell_n)^2  }{\Theta(n)}  \| \nabla H \|^{2}_{2,n},
	\end{align*}
	where $C$ is a constant independent of $H$, $n$ and $t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $b > 0$ and let $\mathsf{B} \in \tailF{-b}^1$. Let $K_3,K_2 > 0$ and $r \geq 1$ be such that $b \geq (K_3+1)K_2r$ and denote $\Tilde{\Theta}_{r,K_3,K_2}\coloneqq (E^3_{K_2r,K_3} \cup E^2_{r,K_2})^c$. Then 
    \begin{equation} 
        \Tilde{\Theta}_{r,K_3,K_2} \cap \{\varphi: L(\varphi) \in \mathsf{B}\} = \Tilde{\Theta}_{r,K_3,K_2} \cap \{\varphi: L(\varphi \cap ((rB^d)^c \times \R)) \in \mathsf{B}\}.
    \end{equation}

