[Theorem 21 (Dubins' inequality for finite time, $T < \infty$) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] Let $f_0, f_1, \ldots, f_T,$ be a given real valued supermartingale sequence with $f_n \geq c $ where $c$ is a constant. Assume the definitions of $\rho_k, \tau_k$ given by Definition \ref{upcrossing_stopping_times}  with $T < \infty$ (i.e. the finite time case). Furthermore, assume
that $(L)-a.e.$ holds; then,
for any $k\ge 0$ and $c \leq a < b$:
\begin{equation} \nonumber 
\overline{\sigma}({\bf 1}_{\{\tau_{k+1} < T+1\}}) \leq \left(\frac{a-c}{b-c} \right)~~ \overline{\sigma}({\bf 1}_{\{\rho_{k}  < T+1\}}) \leq
\left(\frac{a-c}{b-c}\right)~~ \overline{\sigma}({\bf 1}_{\{\tau_{k}  < T+1\}}),
\end{equation}
and so
\begin{equation} 
\overline{\sigma}({\bf 1}_{\{\tau_{k+1}  < T+1\}}) \leq
\left(\frac{a-c}{b-c} \right)^{k+1} ~\overline{\sigma}({\bf 1}_{\{\rho_{0}  < T+1\}}) \leq
\left(\frac{a-c}{b-c}\right)^{k+1}.
\end{equation}

[Lemma lem:app-distance-stability of arXiv:2609.02710, 'Asymptotic Mean Value Laplacian\\ on equiregular sub-Riemannian manifolds'] Let $C,C' \subset \mathbb{R}^n$ be compact sets such that
$0\in C\subset\operatorname{int}C'\Subset U_0$.  Suppose $Y^\lambda$ is
jointly smooth and uniformly two-generating on $\overline{U_1}$, and that
for some $R<\infty$ and every $\lambda\in\Theta$,
\begin{equation}
 d_{Y^\lambda}(0,q)\le R\quad(q\in C'),
 \qquad
 \gamma_{0,u}^\lambda([0,1])\subset U_0
 \quad\text{if }\|u\|_{L^2}\le R+1.
\end{equation}
Then there is $L$ such that
\begin{equation}
  |d_{Y^\lambda}(0,q)^2-d_{Y^\lambda}(0,q')^2|
  \le L|q-q'|
\end{equation}
for all $q,q'\in C$ and $\lambda\in\Theta$.
Moreover, if $Z^\lambda$ is a second family with the same properties and the same
bound $R$, then there are $\varepsilon_0,L'>0$ such that
\begin{equation}
  \sup_{q\in C}
  |d_{Y^\lambda}(0,q)^2-d_{Z^\lambda}(0,q)^2|
  \le L'\max_i\|Y_i^\lambda-Z_i^\lambda\|_{C^1(\overline{U_1})}
\end{equation}
whenever the norm on the right is at most $\varepsilon_0$.

[Definition 89 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] We say that $X$ is a {\em regular
diffusion process 
\index{$D$@Processes!regular
diffusion process}
corresponding to
$\cL$ or to $a,b$\/} if



(i)  for any $(t,x)\in\bR^{d+1}$
there exists a $d$-dimensional Wiener process $w_{t}$, $t\geq0$,
which is a Wiener process relative to $\bar \cN_{t}$,
where $\bar \cN_{t}$ is the completion of $\cN_{t}$
with respect to all $P_{s,y}$, and such that with    
$P_{t,x}$-probability one, for
all $s\geq 0$, $\sft_{s}=t+s$ and
\begin{equation} 

x_{s}=x+\int_{0}^{s}\sigma(t+u,x_{u})\,dw_{u}
+\int_{0}^{s}b(t+u,x_{u})\,du.
\end{equation}

(ii) there exists $\rho_{b}\in(0,\infty)$ such that
\begin{equation}

  \bar b_{\rho_{b}}=\sup_{r\leq\rho_{b}}r^{-1}
\sup_{(t,x)\in\bR^{d+1}}\sup_{C\in\bC_{r}}
E_{t,x}\int_{0}^{\tau_{C}}|b(\sft_{s},x_{s})|\,ds \leq \sfb_{0},
\end{equation}
where $\tau_{C}$ is the first exit time of 
$(\sft_{s},x_{s})$ from $C$.

[Lemma 62 ({\cite[Lemma 3.4) of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] {Dau23}}]

Fix $\delta>0$. For every $k\in \NN$, there exists a $C_k,c_k$ such that for all $s\in (-n^{1/3}/4,n^{1/3}/4)$, $r\in (0,n^{1/3})$ and $a$ satisfying $n^{2/3}/4>a>c_kr^2$, we have
  \begin{equation}

    \PP(|\cP_k(s)+s^2-\cP_k(s+r)-(s+r)^2|>a)\leq C_k\exp(-\frac{a^2}{(4+\delta)r}).
  \end{equation}

