body:
[Definition 5 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Approximate Tensorization of Entropy}


    A probability measure $\nu$ on a space $\mathcal X^n$ fulfills ATE with constant $\kappa \geq 1$ if for all $f : \mathcal X^n \to [0,\infty)$,
    \begin{align*}
        \ent[\nu]{f}
        \leq \kappa \cdot  \sum_{i=1}^n \E[\ent[\nu(\cdot | X_{-i})]{f}]. 
    \end{align*}

[Proposition prop:factorization-criterion of arXiv:2608.23860, 'Revelation Control'] For finite $\mathcal A$ and integrable utilities,
\begin{equation}
V_B(\mathscr G)=V_B(\mathscr H)
\end{equation}
if and only if the $\mathscr G$-optimal decision factorizes through $\mathscr H$.  Hence strict refinement value occurs exactly when no $\mathscr H$-measurable policy is $\mathscr G$-Bayes optimal almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 19 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $G=(V,E)\subset H=(V',E')$ be two subgraphs of $\mathbb Z^d$. For every $\beta\geq 0$, and every $x,y \in V'$,
\begin{equation}
	\langle \sigma_x\sigma_y\rangle_{H,\beta}-\langle \sigma_x\sigma_y\rangle_{G,\beta}\leq \sum_{u\in \partial V}\langle \sigma_x\sigma_u\rangle_{G,\beta}\langle \sigma_u\sigma_y\rangle_{H,\beta},
\end{equation}
where $\p V:= \{ u\in V : \exists v\in V' \setminus V \text{ with } uv \in E' \}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Expectation Bound of arXiv:2607.17393, 'Optimal Covariance Estimates for Schr\"odinger Semigroups with White Noise in $d=1,2$'] If (equation Equation: V Lower Bound of the paper) and (equation Equation: V Upper Bound of the paper) both hold, then
\[\mathbb E\left[\mathrm{Tr}[e^{-t H}]\right]\asymp t^{-d/2-d/\kappa}
\qquad\text{as }t\to0.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem-first-round-distribution-features of arXiv:2607.22324, 'The conclave process'] Fix $\alpha\geq 1$. Define $A_j = \#\{ 1 \leq i \leq n: \mathbf X^{(i)}_1 = j\}$ for $0 \leq j \leq \aleph + 2$. In addition, define
    \begin{align*}
        \mathtt N = (\log \log n)^2 <\exp(40\alpha \sqrt{\log \log n}), \quad \mathtt N' = \frac{\log n}{(\log \log n)^{30}} \,.
    \end{align*}
    Define $\mathcal E_{(lem-first-round-distribution-features of the paper)}=\mathcal E_{(lem-first-round-distribution-features of the paper),1} \cap \mathcal E_{(lem-first-round-distribution-features of the paper),2} \cap \mathcal E_{(lem-first-round-distribution-features of the paper),3}$, where 
    \begin{align}
        & \mathcal E_{(lem-first-round-distribution-features of the paper),1} = \left\{ |\mathbf M_1-\aleph| \leq 2, n \leq \mathbf Z_1 \leq n\log \log n \right\} \,; \\
        & \mathcal E_{(lem-first-round-distribution-features of the paper),2} = \cap_{j \geq 0} \left\{ A_{\mathbf M_1-j} \leq \exp(\log\log n \cdot \max\{ \mathtt N, j \}) \right\} \,; \\
        & \mathcal E_{(lem-first-round-distribution-features of the paper),3} = \cap_{10 \leq j \leq \mathtt N'} \left\{ A_{\mathbf M_1-j} \geq \exp( (\log\log n)^{-1} \cdot j ) \right\}\,.
    \end{align}
    We then have: 
    \begin{enumerate}
        \item[(1)] $\mathbb P^{\alpha}_n(E_{\mathsf{unique}}), \mathbb P^{\alpha}_n(E^c_{\mathsf{unique}}) \geq \frac{1}{\log n}$.
        \item[(2)] $\mathbb P^{\alpha}_n(\mathcal E_{(lem-first-round-distribution-features of the paper)} \mid E_{\mathsf{unique}}), \mathbb P^{\alpha}_n(\mathcal E_{(lem-first-round-distribution-features of the paper)} \mid E^c_{\mathsf{unique}})=1-o(1)$.
    \end{enumerate}

