[Theorem 2 of arXiv:2506.14145, '\bf Global-in-time optimal control of stochastic third-grade fluids with additive noise'] Assume that $\vb_0\in\Drm(\A^{\frac{3}{2}})$. Then the control problem \eqref{eqn-control-problem} admits, at least, one optimal solution 
    \begin{align}
        (\widetilde{\fb}, \widetilde{\vb})\in \mathcal{F}_{ad}\times  \Lrm^2(\Omega;\mathrm{L}^{\infty}(0,{T}; \Drm(\A^{\frac{3}{2}}))),
    \end{align}
    where $\widetilde{\vb}$ is the unique solution of \eqref{stochastic-third-grade-fluids-equations} with $\fb=\widetilde{\fb}$. Moreover, there exists a unique solution $\pb$ of \eqref{eqn-adjoint-pi} with $\gb=\nabla_{\vb}\mathfrak{L}(\cdot,\widetilde{\fb},\widetilde{\vb}),$ such that if $\widetilde{\mfrk}$ is the solution of \eqref{eqn-linearized-pi} for $\vb=\widetilde{\vb}$ and $\boldsymbol{\psi}=\boldsymbol{\psi}-\widetilde{\fb}$, the following duality property 
    \begin{align}
        \Eb\left[\int_0^{T} (\boldsymbol{\psi}(t) - \widetilde{\fb}(t), \widetilde{\pb}(t))\drm t\right] = \Eb\left[\int_0^{T} (\nabla_{\vb}\mathfrak{L}(t,\widetilde{\fb}(t), \widetilde{\vb}(t)), \widetilde{\mfrk}(t))\drm t\right],
    \end{align}
    and the following optimality condition hold 
    \begin{align}
        \Eb \left[ \int_0^{T} (\boldsymbol{\psi}(t)-\widetilde{\fb}(t), \widetilde{\pb}(t) + \nabla_{\fb}\mathfrak{L}(t,\widetilde{\fb}(t), \widetilde{\vb}(t)) )\drm t\right]  \geq 0.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:spectral_heat1 of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\Omega$ be a bounded, open subset of $\mathbb{G}$. If $\Omega$ has $C^2$ boundary with no characteristic points, then
    \begin{enumerate}[leftmargin=*]
        \item  For $1<\alpha<2$, 
        \begin{align*}
            \lim_{t\to 0}\frac{\operatorname{Vol}(\Omega)-\widetilde{H}^{(\alpha)}_\Omega(t)}{t^{\frac{1}{\alpha}}}= \mathbb{E}\left[\sup_{0\leqslant t\leqslant 1} Y_t\right]\operatorname{Per}_{\mathcal H}(\Omega),
        \end{align*}
        where $(Y_t)_{t\geqslant 0}$ is a one-dimensional symmetric $\alpha$-stable L\'evy process such that $\mathbb{E}[e^{i \xi Y_t}]=e^{-t|\xi|^\alpha}$ for all $t\geqslant 0$ and $\xi\in\mathbb R$.
        \item  When $\alpha=1$, 
        \begin{align*}
            \lim_{t\to 0}\frac{\operatorname{Vol}(\Omega)-\widetilde{H}^{(1)}_\Omega(t)}{t\log(1/t)}= \frac{1}{\pi}\operatorname{Per}_{\mathcal H}(\Omega).
        \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Th3 of arXiv:2411.06245, 'On the longest/shortest negative excursion of a Lévy risk process and related quantities'] For $q,r>0$ and $x\in \mathbb{R}$, we have
\begin{eqnarray}
&&\mathbb{P}_{x}\left( \bar{U}_{\mathrm{e}_q}<r\right)=1 -\mathrm{e}
