q\right) }\left( x,s\right) \mathrm{d} s \nonumber \\
&&\qquad+\frac{\Lambda ^{\left( q\right) }\left( x,r\right) }{
\int_{0}^{\infty }\mathrm{e}^{\Phi _{q}z}z/r\mathbb{P}\left( X_{r}\in
\mathrm{d}z\right) } \left(\mathrm{e}^{-qr}q\int_{0}^{r}
\int_{0}^{\infty }\mathrm{e}^{\Phi _{q}z}\frac{z}{r}\mathbb{P}\left(
X_{r}\in \mathrm{d}z\right) \mathrm{d}s+\frac{q}{\Phi _{q}}\right).
