[Prop Prop n pt cut disks bc continuum of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] Assume that $v = 0$ and $n \geq 1$ or $v \neq 0$ and $n$ is \textbf{even}.
The following equality holds:
\begin{multline*}
\mathbb{P}
\Big(
\nexists C
\text{ cluster of } 
\mathcal{L}_{D_{\varepsilon_1,\ldots,\varepsilon_n}(z_1,\ldots,z_n)}
\cup
\Xi^{v^2/2}_{D, D_{\varepsilon_1,\ldots,\varepsilon_n}(z_1,\ldots,z_n)}
\text{ with a closed path } \gamma\subset C
\text{ s.t. }
\sum_{j=1}^n \indx_{\gamma}(z_j) \text{ odd}
\Big)
\\
=
\exp\Big(
-
\mu^{\rm loop}_{D_{\varepsilon_1,\ldots,\varepsilon_n}(z_1,\ldots,z_n)}
\Big(
\sum_{j=1}^n \indx_{\gamma}(z_j)
\text{ odd}
\Big)
-
v^2
\mu^{\rm exc}_{D}
\Big(\sum_{j=1}^n \indx_{\gamma}(z_j) \text{ odd},
\gamma\subset D_{\varepsilon_1,\ldots,\varepsilon_n}(z_1,\ldots,z_n)
\Big)
\Big)
.
\end{multline*}
In particular, in the case $n=2$,
\begin{multline*}
-\log\mathbb{P}
\Big(
\text{No cluster of } 
\mathcal{L}_{D_{\varepsilon_1,\varepsilon_2}(z_1,z_2)}
\cup
\Xi^{v^2/2}_{D, D_{\varepsilon_1,\varepsilon_2}
(z_1,z_2)}
\text{ disconnects } z_1 \text{ from } z_2
\Big)
=
\\
\mu^{\rm loop}
_{D_{\varepsilon_1,\varepsilon_2}(z_1,z_2)}
\Big(
\indx_{\gamma}(z_1)+\indx_{\gamma}(z_2)
\text{ odd}
\Big)
+
v^2
\mu^{\rm exc}_{D}
\Big(
\indx_{\gamma}(z_1)+\indx_{\gamma}(z_2) \text{ odd},
\gamma\subset 
D_{\varepsilon_1,\varepsilon_2}(z_1,z_2)
\Big)
.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:sigmas-single of arXiv:2603.14906, 'Four Levels of Thermodynamic Convergence of Singularly Perturbed Markov Semigroups'] Let $X$ denote the underlying state space (either $X=E$ or $X=\bar E$), and let $(P_t,\pi,\mathcal L)$ be as in
Eq.~(equation eq:generator-eps of the paper) on $X$.
Fix a nonnegative initial datum $f$ and write $u(t,\zeta)=P_t f$. 
Whenever we specialize to the diffusion form (equation eq:backward-eps1 of the paper), we use the associated coefficients $(A,\gamma)$ via (lem:dict-diffusion of the paper).
For each $t\ge 0$ we define:

\begin{enumerate}
\item \emph{Free energy:}
\[
  \mathcal{F}(t)
  :=\int_X P_t f \log (P_t f)\,d\pi
  =\int_X u(t,\zeta)\,\log u(t,\zeta)\,d\pi(\zeta)\ge 0,
\]
with the convention $0\log0:=0$.

\item \emph{Free energy dissipation rate:}
\begin{equation}

  \mathcal{I}(t) :=4\int_X \Gamma(\sqrt{P_t f})\,d\pi
  =4\int_X \Gamma(\sqrt{u(t,\zeta)})\,d\pi(\zeta) \ge 0.
\end{equation}

\item \emph{Housekeeping (adiabatic) entropy production rate:}
\begin{equation}
  \sigma_{\mathrm{hk}}(t)
  :=\int_X P_t f\,
        (L_a \mathrm{id})^\top \Gamma(\mathrm{id})^{-1}L_a \mathrm{id}\,d\pi
  =\int_X u(t,\zeta)\,\gamma(\zeta)^\top A(\zeta)^{-1}\gamma(\zeta)\,d\pi(\zeta)\ge 0,
\end{equation}
where $L_a:=\tfrac12(\mathcal L-\mathcal L^\dagger)$ and $\mathcal L^\dagger$ is the $\pi$-adjoint of $\mathcal L$ in $L^2(\pi)$.
Let $\mathrm{id}:X\to\mathbb{R}^d$ denote the coordinate embedding $\mathrm{id}(\zeta)=\zeta$, with components $\mathrm{id}_i(\zeta)=\zeta_i$.
Let $\Gamma(\mathrm{id})$ be the $d\times d$ matrix field with entries $\Gamma(\mathrm{id}_i,\mathrm{id}_j)$.
For diffusion generators of the form in Eq.~(equation eq:backward-eps1 of the paper), one has $\Gamma(\mathrm{id})=A$ and $L_a\,\mathrm{id}=-\gamma$.

We also set the steady-state housekeeping entropy production rates by
\begin{equation}
\sigma_{\mathrm{hk,ss}}:= \int_X(L_a \mathrm{id})^\top \Gamma(\mathrm{id})^{-1}L_a \mathrm{id}\,d\pi=\int_X \gamma(\zeta)^\top A(\zeta)^{-1}\gamma(\zeta)\,d\pi(\zeta).

\end{equation}

\item \emph{Excess (nonadiabatic) entropy production rate:}
\begin{equation}
  \sigma_{\mathrm{ex}}(t):= \mathcal{I}(t)\ge 0.
\end{equation}

\item \emph{Total entropy production rate:}
\begin{equation}
  \sigma(t):= \sigma_{\mathrm{hk}}(t) + \sigma_{\mathrm{ex}}(t)\ge 0.
\end{equation}
\end{enumerate}

[Lemma 18 of arXiv:2607.11773, '2607.11773'] Suppose that {\bf (H1)}-{\bf (H4)}, \eqref{31_1}, \eqref{34_1}  and \eqref{dissip1-2} hold.
 Then for every $\tau \in \mathbb{R}$ and and $\theta \in \left(2, \tfrac{2(p-2)}{q-2} \right)$,
 there exists $\varepsilon_0 = \varepsilon(\theta)  \in (0, \varepsilon^*)$ such that for all $\varepsilon \in (0, \varepsilon_0)$, $\rho \in [0,1]$ and $t \ge 3\rho$,
 the solution $u^{\varepsilon} (r; \tau-t, \varphi)$ of \eqref{lmvlds-1} with parameter $\varepsilon$ and the solution $u^0(\tau; \tau - t, \psi)$ of \eqref{lds} satisfy
 \begin{align}
       & \mathbb{E} 
              \left[ \sup_{s \in [-\rho, 0] } 
                            \| u^{\varepsilon}_\tau(s; \tau - t, \varphi) 
                               - u^0_\tau(s; \tau - t, \psi) 
                            \|^\theta 
              \right]  \nonumber\\             
  \le & \mathfrak{C}_{\theta} e^{-\beta t}
                                          \mathbb{E}
                                                 \left[ \| \varphi - \psi \|_\infty^\theta
                                                 \right]  
            + \mathfrak{C}_{\theta} \varepsilon^{\frac{\theta}{2} }   
                      e^{-\beta t}
                             \mathbb{E} \left[ \|\varphi\|_{\infty}^{\theta} \right] 
            + \mathfrak{C}_\theta \varepsilon^{\frac{\theta}{2} } \nonumber\\
       & + \mathfrak{C}_\theta \varepsilon^{\frac{\theta}{2} } 
              \int_{-\infty}^{\tau} e^{\beta (s-\tau)}
                  \left( \|g(s)\|^{\theta} 
                           + \|h(s)\|^{\theta} 
                           + \| \widetilde{h}(s)\|_{L^{\theta}(\mathbb{Y},\nu; \ell^2)}^\theta
                           + \| \widetilde{h}(s)\|_{L^{2}(\mathbb{Y},\nu; \ell^2)}^\theta
                  \right) ds,                                                                    
 \end{align}  
 where $\varphi, \psi \in L^\theta(\Omega, \mathcal{F}_{\tau-t}; D_\rho)$, 
 and $\mathfrak{C}_{\theta} > 0$ is a constant depending on $\theta$.

