[Definition def:lf-insertion of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $(\alpha_i,z_i)\in\mathbb{R}\times\mathbb{H}$ and $(\beta_j,s_j)\in\mathbb{R}\times\partial\mathbb{H}$ for $i=1,...,m$ and $j = 1,...,n$ and the $z_i$'s and $s_j$'s are pairwise distinct. Set 
	\begin{equation*}
	\begin{split}
	&C_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j} =\\ &\prod_{i=1}^m\prod_{j=1}^n(2\mathrm{Im}z_i)^{-\frac{\alpha_i^2}{2}}|z_i|_+^{-2\alpha_i(Q-\alpha_i)}|s_j|_+^{-\beta_i(Q-\frac{\beta_i}{2})}e^{\frac{\alpha_i\beta_j}{2}G_\mathbb{H}(z_i,s_j)+\sum_{i'=i+1}^{m}\alpha_i\alpha_{i'}G_\mathbb{H}(z_i,z_{i'})+\sum_{j'=j+1}^{n}\frac{\beta_j\beta_{j'}}{4}G_\mathbb{H}(s_j,s_{j'}) }.   
	\end{split}
	\end{equation*}
	Let $(h,\mathbf{c})$ be sampled from $C_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j}P_\mathbb{H}\times [e^{(\sum_i\alpha_i+\frac{1}{2}\sum_j\beta_j-Q)c}dc]$, and 
	\begin{equation*}
	    \phi(z) = h(z)-2Q\log|z|_++\sum_{i=1}^m\alpha_iG_\mathbb{H}(z,z_j)+\sum_{j=1}^n\frac{\beta_j}{2}G_\mathbb{H}(z,s_j)+\mathbf{c}.
	\end{equation*}
	We write $\mathrm{LF}_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j}$ for the law of $\phi$ and call a sample from $\mathrm{LF}_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j}$ the Liouville field on $\mathbb{H}$ with insertions $(\alpha_i,z_i)_{1\le i\le m}, (\beta_j,s_j)_{1\le j\le n}$.

[Definition def:finite boxtimes of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $p_n$ and $q_n$ be degree $n$ monic polynomials with corresponding unique polynomials  $P_n$ and $Q_{n}$ such that $p_n(z)=P_n(z\partial_{z})(z-1)^{n}$ and $q_{n}(z)=Q_n(\partial_{z})(z-1)^n$, respectively.

	Then, the finite free multiplicative convolution  of $p_n$ and $q_n$ is the unique degree $n$ polynomial $p_n\boxtimes_{n}q_n$ such that \begin{equation*}
		p_n\boxtimes_{n}q_{n}(z)=Q_n(z\partial_{z})P_n(z\partial_{z})(z-1)^n.
	\end{equation*} Equivalently, if $p_n(z)=\sum_{k=0}^{n}(-1)^{k}e_{k}(p_n)\binom{n}{k}z^{n-k}$ and $q_n(z)=\sum_{k=0}^{n}(-1)^{k}e_{k}(q_n)\binom{n}{k}z^{n-k}$, then \begin{equation*}
	p_n\boxtimes_{n}q_n(z)=\sum_{k=0}^{n}(-1)^{k}e_{k}(p_n)e_{k}(q_n)\binom{n}{k}z^{n-k}. 
	\end{equation*}

[Proposition cov fact 1 of arXiv:2606.02472, 'Correlated uniform attachment trees'] If $X,Y,\widetilde{X},\widetilde{Y}$ are square-integrable and mean-zero random variables such that $(X,\widetilde{X})$ is independent of $(Y,\widetilde{Y})$, then
		\begin{equation}
		\Cov \bclr{ XY,\widetilde{X}\widetilde{Y} } = \Cov \bclr{ X,\widetilde{X} } \Cov\bclr{ Y,\widetilde{Y}}.
	\end{equation}
	If, in addition, $Z$ is a square integrable random variable  such that $Y$ is independent of $(X,Z)$, then
	\begin{equation}
		\Cov(X,YZ)=0 .
	\end{equation}

[Proposition 4 of arXiv:2607.15125, '2607.15125'] For every $a\in [-1,1)\setminus \{0\}$, there exists $r_a(x)>0$ such that for all $x\in \R$, and $z \in (-r_a(x), r_a(x))$, the generating function $L_a(x,z)$ defined in \eqref{eq:generating_function} is equal to
\begin{equation} 
        L_a(x,z) = \sinh^{-\frac{1}a} (x)A\left(k^{-1}\left( k(\sinh(x)) - z\sinh^{-\frac1a}(x)  \right) \right),
\end{equation}
    where $A$ is the algebraic function
\begin{align}
     A(t) &\coloneqq \left( (1-2q)t +\sqrt{1+t^2} \right)t^\frac1a, \\
     \intertext{and $k^{-1}$ is the inverse under composition of the strictly monotone function $k:\R^+ \to \R^+$, defined as}
     k(t) &\coloneqq \left\{ \begin{array}{cc}
          -\frac1{a} \int_0^t \frac{\d s}{s^{\frac{1+a}{a}}\sqrt{1+s^2}}, & a \in [-1,0), \\
          \frac1{a} \int_t^\infty \frac{\d s}{s^{\frac{1+a}{a}}\sqrt{1+s^2}},  & a \in (0,1).
     \end{array} \right. 
 \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem joint_degree_distribution of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix $m\in\mathbb{N}$, $c\in(0,m+1)$ and $k,\ell\in\mathbb{N}_0$ such that $k+\ell\geq 1$. Fix a choice sequence $\mathbf x$ such that Assumption~$\hyperref[ass:A]{\mathbf{x}}$ is satisfied  for some $\varepsilon<1-c/(m+1)$ in  Part~(item:hI of the paper) and some $\eta<1-c/(m+1)$ in Part~(item:Jn of the paper). Let $V_1,\ldots,V_k\in\mathbb A_n$ be distinct active vertices and $W_1,\ldots,W_\ell\in\mathbb F_n$ be distinct frozen vertices selected uniformly at random from $G^{(n)}$. Then, there exists $\alpha\in(0,1)$ such that uniformly over all natural numbers $d_{a_1},\ldots,d_{a_k} < ch_n^+$ and $d_{f_1},\ldots,d_{f_\ell} < c\log F_n$,
\begin{equation}
\begin{aligned}
\P{\deg_n(V_v)\geq d_{a_v},\deg_n(W_w)\geq d_{f_w}\text{ for all }v\in[k],w\in[\ell]}= \theta^{-\sum_{v=1}^k d_{a_v}-\sum_{w=1}^\ell d_{f_w}}(1+o(I_{\hyperref[ass:A]{\mathbf{x}}}^{-\alpha})).
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] Under Assumptions \ref{asmp:state_dynamics}, \ref{asmp:base_penalty:c}, and \ref{asmp:base_penalty:g}, for every fixed admissible stopping time $\tau\in\mathcal{T}$, the map 
    \begin{equation*}
        (t,x)\mapsto \mathbb{E}\left[\int_0^\tau c(t+u)\,du+g(X_\tau^x)\right]
    \end{equation*}
    is continuous on $\overline{\mathcal{S}}$.

