[Definition def: holo functions of arXiv:2411.04238, 'Holomorphic jump-diffusions'] (\textit{Definition 1.2.1 in} [SC:05])
    Let $U\subseteq\mathbb C^d$ be an open set and $m\in \mathbb{N}$.
    \begin{enumerate}
        \item {\textbf{Complex differentiable functions}} 

        A function $f:U\rightarrow\mathbb C^m$ is called \textit{complex differentiable} at $z_0\in U$ if for every $\varepsilon>0$ there exists a $\delta>0$ and a $\mathbb C$-linear map
    \begin{align*}
        Lf(z_0): \mathbb C^d\rightarrow\mathbb C^m
    \end{align*}
    such that  for all $z\in U$ with $\|z-z_0\|\leq \delta$, the inequality 
    \begin{align*}
        \|f(z)-f(z_0)-Lf(z_0)(z-z_0)\|\leq \varepsilon\|z-z_0\|
    \end{align*}
    holds.
     \item {\textbf{Holomorphic functions}}

     A function $f:U\rightarrow\mathbb C^m$ is called \textit{holomorphic} on $U$ if it is complex differentiable at all $z_0\in U$. A holomorphic function on the whole $\mathbb C^d$ is called \textit{entire}.
    \end{enumerate}

[Theorem 10 of arXiv:2609.02385, 'Kinetic Fokker--Planck Equations with Drifts in a Supercritical Range'] Under Assumption {\bf ($\wt{\text{H}}$)}, let $u$ be a weak subsolution of \eqref{kineticpde} in $Q_2$. Then for all $|t|\leq1$,
\begin{align}
\|\bbone_{Q_1}u^+\cI_t\|_{\mL^\infty}+\|\bbone_{Q_1}\nn_vu^+\cI_t\|_{\mL^2}\lesssim_C\|\bbone_{Q_2}u^+\cI_t\|_{\mL^2}+\|\bbone_{Q_2}f\cI_t\|_{\mL_t^{q_0}\mL_z^{\bbp_0}}.
\end{align}
Here $C>0$ depends only on $d,q_1,\bbp_1,q_0,\bbp_0,\b$ and $\|b\|_{\mL_t^{q_1}\mL_z^{\bbp_1}((-4,4)\times\mR^{2d})}$.

