body:
[Proposition of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] The following estimates hold.
\begin{enumerate}
	\item[(i)]\textbf{Paraproduct estimate.} Let $s \in \mathbb R$ and $p,p_1,p_2,q \in [1,\infty]$ be such that $\frac 1p = \frac 1 {p_1} + \frac 1{p_2}$. There exists $C>0$ such that
\begin{equation} 
	\|f \succ g\|_{B^{s}_{p,q}}\leq C\| f \|_{B^s_{p_1,q}} \| g \|_{L^{p_2}}, \qquad \forall f,g \in C^\infty(\mathbb T^d).
\end{equation}
	\item[(ii)] \textbf{Resonant product estimate.} Let $s_1,s_2 \in \mathbb R$ such that $s=s_1 + s_2 > 0$. Let $p,p_1,p_2,q \in [1,\infty]$ satisfy $\frac 1p = \frac 1{p_1} + \frac 1{p_2}$. There exists $C>0$ such that
	\begin{equation}
	\| f \circ g \|_{B^s_{p,q}} \leq C\| f \|_{B^{s_1}_{p_1,\infty}} \| g \|_{B^{s_2}_{p_2,q}}, \qquad \forall f,g \in C^\infty(\mathbb T^d). 	
	\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

