[Defin eq:def_h of arXiv:2605.31054, 'On the empirical spectral distribution of matrix perpetuities'] Let $({\mathbf A}_n)_{n\ge 1}$ be iid copies of ${\mathbf A}$ and set
\[
\Pi_n:={\mathbf A}_n\cdots {\mathbf A}_1,\qquad {\bf M}_n:=\Pi_n \Pi_n^\top\in\mathrm{Sym}_{\geq0}(N).
\]
Fix $k\in\{1,\ldots,N\}$ and define 
\begin{align}
h_k(s):=    \inf_{n\in\mathbb{N}} {\mathbb E}\left[ \prod_{i=1}^k \lambda_i({\bf M}_n)^{s/k}\right]^{1/n}
\end{align}
for nonnegative $s$ such that $ {\mathbb E}\left[ \prod_{i=1}^k \lambda_i({\mathbf A} {\mathbf A}^\top)^{s/k}\right]<\infty$.

[Lemm 8 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] Let $\Tz := (X,Y,Z)$ be the unique solution to the FBSDEs satisfying all the conditions in Lemma~\ref{p-exist}.
    Then, the following a priori estimate holds:
    \begin{align}
        \|\Tz\|^p_{p,*} \leq c_{\eqref{p-estimate}}
        &\E\Biggl[|\xi|^p + |g(0)|^p + \Biggl(\int_t^T |b^0(s)|\,\od s\Biggr)^p \notag\\
        &\quad + \Biggl(\int_t^T |\mu^0(s)|^2\,\od s\Biggr)^{p/2} + \Biggl(\int_t^T |f^0(s)|\,\od s\Biggr)^p\Biggr] < \infty,
    \end{align}
    where the constant $c_{\eqref{p-estimate}}$ depends only on $p$, $\dz$, and all the Lipschitz constants.

    Furthermore, consider another set of coefficients
    $(\wt{\xi},\wt{b},\wt{\mu},\wt{f},\wt{g})$ that satisfies all the conditions in Lemma~\ref{p-exist},
    and shares the same Lipschitz constants as $(\xi,b,\mu,f,g)$.
    Let $\wt{\Tz} = (\wt{X},\wt{Y},\wt{Z})$ be the corresponding solution to the modified FBSDEs.
    Then, the following stability estimate holds:
    \begin{align}
        \|\wt{\Tz} - \Tz\|^p_{p,*}
        \leq c_{\eqref{p-var:equ}} 
        &\E\Biggl[|\xi - \wt{\xi}|^p + |g(X_T) - \wt{g}(X_T)|^p + V_p([t,T])\Biggr],
    \end{align}
    where
    \begin{align*}
        V_p([t,T]) 
        &:= \Biggl(\int_t^T |\Delta b(s,\Tz_s)|\,\od s\Biggr)^p 
        + \Biggl(\int_t^T |\Delta \mu(s,\Tz_s)|^2\,\od s\Biggr)^{p/2}\\
        &\quad\quad + \Biggl(\int_t^T |\Delta f(s,\Tz_s)|\,\od s\Biggr)^p,
    \end{align*}
    with
    \begin{equation*}
        \Delta h := h - \wt{h}, \quad h\in\{b,\mu,f\}.
    \end{equation*}
    The constant $c_{\eqref{p-var:equ}}$ depends only on $p$, $\dz$, and all the Lipschitz constants. (Proof in the paper; no proof environment follows the statement in the TeX.)

