[Proposition prop:condi_prob of arXiv:2604.10214, 'Large deviations for maximum local time of simple random walk in dimensions \texorpdfstrin'] We have
\begin{align}
    \mathbb P\Bigl(
B \,\Big|\, \mathcal N,\ (\mathcal M_j)_{1\le j\le \mathcal N}
\Bigr)
=
\prod_{j=1}^{\mathcal N}\prod_{k=0}^{\mathcal M_j}
\bigl(1-e^{-\eta/2^{k+1}}\bigr).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma-properties-weight of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] Let $\kappa> 2$ and $d_{\partial D}(x) := 1-|x|^2$ denotes the distance from $\partial D$.  We have:
    \begin{enumerate}
       \item For any $\varphi\in H^1_\mathbf{M}, $ we have the following Hardy-type inequality, there exists a constant $C_H$ such that
     \begin{align}
          \int_D \dfrac{1}{d_{\partial D}^2}\left\vert\dfrac{\varphi}{\mathbf{M}}\right\vert^2 \mathbf{M}dr \le C_H \Vert \varphi\Vert^2_{H^1_\mathbf{M}}.
       \end{align}
        \item The following inclusions hold: $L^2_\mathbf{M} \subset L^2(D)$ and $H^1_\mathbf{M}\subset H^1_0(D).$

     \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm informal of arXiv:2607.05097, 'Asymptotics of Lyapunov Exponents and Phase Transitions for Fluids with Degenerate Forcing'] Let $z \in \mathbb{R}^d$, $x \in \mathbb{R}^n \setminus \{0\}$, $A, B_i \in \mathbb{R}^{n \times n}$,
    \begin{equation}
           \begin{aligned}
                dz^\epsilon(t) &= -\epsilon z^\epsilon(t)\,dt + \sqrt{\epsilon}\,dW_t \\
                dx^\epsilon(t) &= \Big(A + \sum_{i=1}^d B_i z_i^\epsilon(t)\Bigr)x^\epsilon(t)\,dt \eqqcolon A(z^\epsilon(t))x^\epsilon(t)\,dt \,,
            \end{aligned}
    \end{equation}
    and $\lambda^\epsilon \coloneqq \lim_{t \to \infty} t^{-1}\ln \|x^\epsilon(t)\|$. Let $Z$ be distributed 
    according to the law of the invariant measure of $z^\epsilon(t)$ (which is independent of $\epsilon$). Then, provided
    that (equation eq:intro-eq of the paper) satisfies a weak non-degeneracy condition on $\mathbb{R}^d \times (\mathbb{R}^n \setminus \{0\})$, we have
    $$\lim_{\epsilon \to 0} \lambda^\epsilon = \mathbb{E}[\lambda(A(Z))] \,.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2507.03552, 'On one-dimensional Cluster cluster model'] \begin{equation}
        \lim_{c \to 0}\lim_{t \to \infty}{\Prob{|\mathfs{C}_0(t)|\ge ct^{\frac{1}{\alpha + 2}}}} = 1
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Def: operations binary trees1 of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Let $\rho\in{\mathcal T}_b$. We define the family of binary trees ${\mathcal R}^-(\rho)\subset{\mathcal T}_b$ obtained from $\rho$ by the following algorithm. For any effective cherry of $\rho$:
		\begin{enumerate}
			\item we contract the effective cherry to its parent vertex;
			\item if the effective cherry contains two leaves, after contraction it becomes a new leaf which inherits the rightmost decoration of the pair;
			\item if, instead, the effective cherry contains only one leaf grafted from the left on the root, after contraction the new vertex is not a leaf and does not require any decoration. 
		\end{enumerate}

[Lem aul of arXiv:2411.14090, '{\bf Exponential Ergodicity in $\W_1$ for SDEs with Distribution Dependent Noise and Parti'] Assume {\bf (H)}. Then it holds
\begin{align}
\mathbb E|X_t^{1}-X_t^{2}|
\nonumber&\leq e^{\frac{K}{2}t}\mathbb E|X_0^{1}-X_0^{2}|\\
&+\sqrt{\int_0^te^{K(t-s)}\kappa\mathbb W_1(\mu_s^1,\mu_s^2)^2\,\text{\rm{d}} s}+\mathbb E\sqrt{\int_0^te^{K(t-s)}\|\sigma^1_s-\sigma^2_s\|_{\mathrm{HS}}^2\,\text{\rm{d}} S_s}.
\end{align}

