[Proposition prop:prn_integral of arXiv:2606.23547, 'The location of the largest exponential spacing and Euler’s generalized pentagonal numbers'] For $1\le r\le n$, the probability $p_{r,n}$ admits the integral representation
\begin{equation}
p_{r,n}
=\int_0^\infty r {\rm e}^{-r t}
\prod_{\substack{1\le k\le n\\k\neq r}}
\bigl(1-{\rm e}^{-k t}\bigr)\,{\rm d}t.
\end{equation}
Equivalently,
\begin{equation}
p_{r,n}
=\int_0^1 r\,u^{r-1}
\prod_{\substack{1\le k\le n\\k\neq r}}
(1-u^k)\,{\rm d}u.
\end{equation}

[Corollary cor-6.4 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Suppose~$b\theta^3<1$. Then, under Assumption~(ass-1 of the paper), for all~$\boldsymbol\lambda_{0}\in\Sigma'$,
\begin{equation}

A_1:=\biggl(\,\sup_{n\ge1}\prod_{i=0}^n\max\{b\theta_i^3,1\}\biggr)\max\biggl\{1,\sup_{q\ge0}\frac{\lambda_{0}(q+1)}{\lambda_{0}(q)}\biggr\}<\infty
\end{equation}
and, for each~$n\ge1$, the iterations~$\{\boldsymbol\lambda_k\}_{k=0}^n$ generated from $\boldsymbol\lambda_{0}$ via (equation E:1.5 of the paper) obey
\begin{equation}

\sup_{n\ge k\ge0}\sup_{q\ge0}\frac{\lambda_k(q+1)}{\lambda_k(q)}\le A_1.
\end{equation}
In particular, $F^{(k)}(\Sigma')\subseteq\Sigma'$ for each~$k\ge0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:gaussian-equivalences of arXiv:2606.25976, 'Gaussian rigidity for infinite exchangeable sequences'] Suppose that \(X_1\sim\mathcal{N}(m,\sigma^2)\).
Set \(a:=2(\sigma^2-c)\), which is nonnegative by Lemma~(lem:scalar-second-moment of the paper), and let \(\gamma_a\) denote the centered Gaussian law \(\mathcal{N}(0,a)\) on \(\mathbb{R}\).  Then the following are equivalent.
\begin{enumerate}
\renewcommand{(\roman{enumi})}{(\roman{enumi})}
\renewcommand{\roman{enumi}}{\roman{enumi}}
\item \((X_i)_{i\ge1}\) is a Gaussian process.
\item \(\eta*\widetilde\eta=\gamma_a\) a.s., where \(\widetilde\eta(B)=\eta(-B)\).
\item \(M_\eta\sim\mathcal{N}(m,c)\) and \(\eta\) is the Gaussian law \(\mathcal{N}(M_\eta,\sigma^2-c)\) a.s.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2608.27374, '\Large \bf Distribution-constrained optimal multiple stopping: the Root-type solution'] For every \(t\in[t_0,r_\xi^\beta)\) and \(x\in\mathbb R\),
\begin{equation}

    u^\beta(t,x)
    =
    \inf_{\rho\in\mathcal T_t^\Gamma}
    \E^x\!\left[
        v^\xi(t-\rho,Y_\rho)
        +
        w^\beta(t-\rho)\mathbf 1_{\{\rho<t\}}
    \right].
\end{equation}

[Proposition 7 of arXiv:2609.02581, '\bfseries Interior Curvature Estimates for the Graphical Scalar Curvature Equation in All '] Let $n\geq3$. Suppose that $u$ satisfies \eqref{eq:intro-equation} and $H\geq2$. Then at a point where $h_i^j$ is diagonal, the following Jacobi-type inequality holds:
\begin{equation}
\Delta_{T_u}b\geq 2H-\frac{4}{H}-T_u^{ij}h_i^kh_{kj}+\sum_{i=1}^n\Theta_iT_u^{ii}b_i^2,
\end{equation}
where
\begin{equation}
\Theta_i:=\frac{H}{H-\kappa_i}
 \left[
 \frac{3\bigl((n+1)H^2-4H\kappa_i+2\kappa_i^2-2\bigr)}
 {(n+1)H^2-4H\kappa_i+2n\kappa_i^2-2(n+2)}-1
 \right]-1.
\end{equation}

