[Definition 6 ({${p}$-ary entropy function and the Johnson radius}) of arXiv:2609.00483, 'On Embedding Hamming Spheres with Applications to Positive Curvature'] Let $\delta \in [0,\frac{p-1}{p}]$.
The \emph{\bf $\mathbf{p}$-ary entropy function} $H_p(x)$ and the \emph{\bf Johnson radius} $J_p(\delta)$ are respectively defined by
\begin{align*}
H_p(x) &= x \log_p(p-1) - x \log_p x - (1 - x) \log_p(1 - x), \,\,\text{and}\\
J_p(\delta) &= \left(1 - \frac{1}{p} \right) \left(1 - \sqrt{1 - \frac{p}{p-1} \delta} \right).
\end{align*}

[Proposition eq:SBBS_R_formula of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] For $j=1,\dots,d-1$, $R_{j}$ in (equation eq:reflection_def of the paper) is given by 
    \begin{align}
    R_{j}  =
    \begin{cases}
    (1-\varepsilon)(0,\dots, 0, \varepsilon,0,\dots, 0)^{\top}\quad &\text{for $c=1$},\\
    (1-\varepsilon)(0,\dots, 0, (1-\varepsilon), 1,0,\dots, 0)^{\top}  \quad &\text{for $c\ge 2$},
\end{cases}
\end{align}
where $\varepsilon$ and $1$ appears in the $j+1$st coordinate, respectively. In particular, $(1-\varepsilon)\hat R^{c,\varepsilon} = [R_1,R_2,\dots, R_{d-1}]$, where $\hat{R}^{c,\varepsilon}$ is in (equation eq:sigma_R of the paper).

[Theo UniformConvergencePotOPerator of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] Let $(\mu_n)_{n\in\mathbb{N}_\infty}\subset\mathscr{K}(X)$ satisfy assumption ((PotentialConvergence of the paper)). Then for all $u\in {C}_0(X)$, it holds
\begin{enumerate} 
\item[\rm(1)] 	$\lim_{n\to\infty}\|G^{\mu_n} u - G^{\mu_\infty} u\|_\infty =0$.
\item[\rm(2)] $\lim_{n\to\infty}\|\check{R}_\alpha^n u - \check{R}_\alpha^\infty  u\|_\infty =0$ for all $\alpha\geq 0$.
\end{enumerate}

[Lemma 14 of arXiv:2604.03548, 'Degree-preserving conservative processes and a unified approach for their hydrodynamics'] Assume $N\ge 4$. 
Then, there exists some $C=C(D,\mathsf{a} )>0$ such that 
\begin{equation*}
\sup_{0\le t\le T} \max_{i\in\mathbb I_N}
\mathcal T^{(1)}_N(t,i)
\le CT/N.  
\end{equation*}

