[Definition eqn:delay_controlled of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume $J = [a,b]$ is a compact interval and $\frac{1}{3} < \beta \leq \gamma$. Let $\mathbf{X}$ be a delayed $\gamma$-rough path. We say that a $\beta$-H\"older path $\zeta \colon J \to W$ is a \emph{delayed controlled path} based on $\mathbf{X}$ over the interval $J$ if there exist $\gamma$-H\"older paths $\zeta^0, \zeta^1 \colon J \to L(\mathbb{R}^d, W)$ such that
		\begin{align}
			\zeta_{s,t} = \zeta^0_s (\delta X)_{s,t} + \zeta^1_s(\delta X)_{s-r,t-r} + \zeta^{\#}_{s,t}
		\end{align}
		for all $s,t \in J$, where $\zeta^{\#} \colon J \times J \to W$ satisfies $\|\zeta^{\#}\|_{2\gamma ; J} < \infty$.



		The paths $\zeta^0$ and $\zeta^1$ are referred to as the \emph{Gubinelli derivatives} of $\zeta$. We denote the space of delayed controlled paths based on $\mathbf{X}$ over the interval $J$ by $\mathcal{D}_{\mathbf{X}}^\beta(J, W)$. A norm on this space is defined as
		\begin{align}
			\|\zeta\|_{\mathcal{D}_{X}^{\beta}(J,W)} := \|(\zeta,\zeta^0,\zeta^1)\|_{\mathcal{D}_{X}^{\beta}(J,W)} := |\zeta_a| + |\zeta^0_a| + |\zeta^1_a| + \|\zeta^0\|_{\beta; J} + \|\zeta^1\|_{\beta; J} + \|\zeta^{\#}\|_{2\beta; J}.
		\end{align}

[Theorem eq:SHF-largeball of arXiv:2511.08479, '\Large From disordered systems to the Critical 2D Stochastic Heat Flow'] There are constants $\delta > 0$ and $0 < c' < c'' < \infty$ such that the following  holds for any $t \ge 0$ and $\vartheta\in\mathbb{R}$:
  \begin{equation} 
    \text{with probability at least $\,1 - \tfrac{1}{\delta} \, e^{-\delta \, t \, e^{\vartheta}}$:} \qquad
    \begin{cases}
      \mathscr{Z}_t^\vartheta\bigl(
    B\bigl(0,e^{c' \, t  \, e^{\vartheta}}
    \sqrt{t \,} \, \bigr)\bigr)
    \le t \, e^{-\delta \, t \, e^{\vartheta}} \,,
    \\
    \rule{0pt}{1.4em}
    \mathscr{Z}_t^\vartheta\bigl(
    B\bigl(0,e^{c'' \, t  \, e^{\vartheta}}
    \sqrt{t \,} \, \bigr))
    \ge t \, e^{\delta \, t \, e^{\vartheta}}  \,.
    \end{cases}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:milne-polyhom-comp of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] The operators in (equation eq:milne-maps-comp of the paper), linear and independent of the tangential parameter, act coefficientwise on finite power-logarithmic expansions. Let $\mathcal I\subset\mathbb R\times\mathbb N_0$ be a finite index set and suppose, in the norms of Proposition~(prop:flat-milne-comp of the paper), that $h(s)=\sum_{(\lambda,b)\in\mathcal I}s^\lambda(\ln s)^bh_{\lambda,b}+\mathcal R_h(s)$ and $F(s)=\sum_{(\lambda,b)\in\mathcal I}s^\lambda(\ln s)^bF_{\lambda,b}+\mathcal R_F(s)$. Suppose further that, for some $q,L\in\mathbb N_0$, $\sigma\in\mathbb R$ and every $0\le a\le q$, the two remainders obey
\begin{align}
 \nm{\partial_s^a\mathcal R_h(s)}_{\mathcal H_+}
 &+\nm{\partial_s^a\mathcal R_F(s)}_{X_{\kappa_{\rm in}}}
 \le C s^{\sigma-a}(1+\abs{\ln s})^L,
 \qquad 0<s<s_0.

\end{align}
Then the end state and the decaying profile have the same expansion,
\begin{align}
 \mathcal E_\mu(h(s),F(s))
 &=\sum_{(\lambda,b)\in\mathcal I}s^\lambda(\ln s)^b
 \mathcal E_\mu(h_{\lambda,b},F_{\lambda,b})
 +\mathcal E_\mu(\mathcal R_h,\mathcal R_F),
 \\
 \mathfrak M_\mu(h(s),F(s))
 &=\sum_{(\lambda,b)\in\mathcal I}s^\lambda(\ln s)^b
 \mathfrak M_\mu(h_{\lambda,b},F_{\lambda,b})
 +\mathfrak M_\mu(\mathcal R_h,\mathcal R_F),

\end{align}
and their remainders obey, for every $0<\kappa_{\rm out}<\kappa_{\rm in}$ and every $0\le a\le q$,
\begin{align}
 \abs{\partial_s^a\mathcal E_\mu(\mathcal R_h,\mathcal R_F)}
 &+\nm{\partial_s^a\mathfrak M_\mu(\mathcal R_h,\mathcal R_F)}_{X_{\kappa_{\rm out}}}
 \le C' s^{\sigma-a}(1+\abs{\ln s})^L.

\end{align}

[Lem construction-of-mn of arXiv:2607.05097, 'Asymptotics of Lyapunov Exponents and Phase Transitions for Fluids with Degenerate Forcing'] There exist open sets $\mathcal{M}_N \subset \mathbb{R}^d \times S^{n-1}$ for $N \in \mathbb{N}$ satisfying
\begin{equation}
    \mathcal{M}_\infty \coloneqq \{(z,v) \in \mathbb{R}^d \times S^{n-1} \mid P_0(z)v = 0\} \subset \bigcup_{K = 1}^\infty \bigcap_{N=K}^\infty \mathcal{M}_N
\end{equation}
and
\begin{equation}
    \lim_{N \to \infty} \limsup_{\epsilon \downarrow 0} \sup_{\mu^\epsilon \in P^\epsilon_{\mathrm{inv}}} \mu^\epsilon(\mathcal{M}_N) = 0\,.
\end{equation}

