[Lemm 5lem22 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] Suppose that $\Phi$ is an $L^{\infty}\text{-Lipschitz}$ functional satisfying condition (equation Lips1 of the paper)\footnote{A similar approximation procedure in the case where $\Phi$ is an $L^{1}\text{-Lipschitz}$ can be found in [MaZhang01]}. Let $\Pi = \{\pi\}$ be a family of partitions of $[0,T]$. Then there is a family of discrete functionals $\{ \varphi^{\pi}: \pi \in \Pi \}$ such that 
				\begin{itemize}
					\item[(i)] for each $\pi \in \Pi$, assuming $\pi:0=t_0<\cdots < t_n=T$ we have that $\varphi^{\pi} \in C_b^{\infty}(\mathbb{R}^{d(n+1)})$ and satisfies 
					\begin{equation}
						\sum_{i=0}^n |\nabla_{x_i}\varphi^{\pi}(x)| \leq S({\varphi}), \quad \forall x=(x_0,\cdots,x_n) \in \mathbb{R}^{d(n+1)},
					\end{equation}
					where the constant $S(\varphi)$ is such that $S(\varphi) < C \Lambda_{\Phi}$ and $\Lambda_{\Phi}$ is given in (equation Lips1 of the paper).
					\item[(ii)] for any $\bold{x} \in \mathbb{D}^d$, it holds that 
					\begin{equation}
						\lim_{|\pi|\rightarrow 0} \left|\varphi^{\pi}(\bold{x}(t_0),\cdots,\bold{x}(t_n)) - \Phi(\bold{x})   \right| = 0.
					\end{equation}
				\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Lebesguept of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] Let $1 \leq p \leq q$, $\Theta$ be a scale function and $(\mathcal{F}_p,\Gamma_p,\Psi)$ be a $p$-energy structure.
    Let $\nu$ be a Borel measure on $X$ for which there are constants $K \geq 1$ and $R > 0$ such that
        \begin{equation}
            \nu(B(x,r))^{\frac{1}{q}} \leq K \Theta(x,r) \left( \frac{\mu(B(x,r))}{\Psi(x,r)} \right)^{\frac{1}{p}}
        \end{equation}
    for all $x \in X$ and $0 < r \leq R$.
    Then for every $f \in \mathcal{F}_p$ the following holds for $\nu$-almost every $x \in X$. Given any pair of sequences $y_i\in X$ and $r_i > 0$ such that $x \in B(y_i,r_i)$ for all $i \in \mathbb{N}$ and $r_i \to 0^+$ as $i \to \infty$, the limit
    \begin{equation}
        \lim_{i \to \infty} \vint_{B(y_i,r_i)} f\, d\mu
    \end{equation}
    exists and is independent of the choices of the sequences.

