[Defn def-sol of arXiv:2512.17736, 'Pathwise uniqueness by noise for singular stochastic PDEs'] Assume (H0 of the paper)--(H4 of the paper).
A weak mild solution to (equation SDE of the paper) is a pair 
$(X,W)$ where $W$ is a $H$-cylindrical Wiener process defined on a filtered probability space 
$(\Omega,\mathcal{F},\{\mathcal{F}_t\}_{t\geq0},\mathbb{P})$ and 
$X$ is a $H$-valued progressively measurable process such that 
\begin{alignat*}{2}
X &\in C^0(\mathbb R_+; H)\cap C^0((0,+\infty); D(A^\alpha))
\quad {\mathbb{P}}\text{-a.s.} \qquad&&\text{if } x\in H\,,\\
X &\in C^0(\mathbb R_+; D(A^\alpha))
\quad {\mathbb{P}}\text{-a.s.} \qquad&&\text{if } x\in D(A^\alpha)\,,
\end{alignat*}
for every $t>0$ it holds $s\mapsto e^{-(t-s)A}B(X(s)) \in L^1(0,t;H)$, ${\mathbb{P}}\text{-a.s.}$, and
\begin{align}
X(t)=e^{-tA}x+\int_0^te^{-(t-s)A}B(X(s))\,{\mathrm d} s+W_A(t)
\quad\forall\,t\geq0\,, \quad \mathbb{P}\text{-a.s.},   
\end{align}
where $W_A$ is the stochastic convolution process given by 
\begin{equation*}
W_A(t):=\int^t_0e^{-(t-s)A}A^{-\delta}\,{\mathrm d} W(s)\,, \quad t\geq0\,.
\end{equation*}

[Lemma lem:irreg3 of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] One has 
\begin{align*} 
&\big| \mathbb{E}\big[ \Delta  X^{\alpha,H}_{(h_1,h_2);(x_1,x_2)}\overline{\Delta   X^{\alpha,H}_{(\ell_1,\ell_2);(y_1,y_2)}}\big]  \big| \\[2ex]
& \quad \quad  \quad   \leq  \int_{\mathbb{R}^2}\frac{\min \{2, |h_1\xi_1| \}   \min \{2, |h_2\xi_2| \}   \min \{2, |\ell_1\xi_1| \}    \min \{2, |\ell_2\xi_2| \} | }{\big(\phi_{\alpha,H}(\xi_1,\xi_2)\big)^2 }d\boldsymbol{\xi}
\end{align*}
for all $(h_1,h_2),(\ell_1, \ell_2),(x_1,x_2),(y_1,y_2)  \in \mathbb{R}^2$.

[Lemma 10 (Exact occupancy mixture) of arXiv:2604.09933, 'Explicit cutoff profiles for colored top-\texorpdfstring{$m$}{m}-to-random shuffles'] For every \(k\ge0\),
\begin{equation}
Q^{*k}
=\sum_{a=0}^{n}\mu_k(a)\,\widetilde Q_{a,p}
=\sum_{u=0}^{n}P_k(u)\,\widetilde Q_{n-u,p},
\end{equation}
where
\begin{equation}
\mu_k(a):=\frac{1}{n^k}\binom{n}{a}\left\{\!\!\begin{matrix}k\\ a\end{matrix}\!\!\right\}a!,
\end{equation}
and \(P_k(u)=\Prob(E=u)\) for the usual balls-into-boxes model with \(k\) i.i.d.\ uniform balls in \(n\) boxes, where \(E\) is the number of empty boxes. Equivalently,
\[
P_k(u)=\mu_k(n-u).
\]

