[Atheorem thm:B of arXiv:2601.21762, 'Navier-Stokes with a fractional transport noise as a limit of multi-scale dynamics'] Assume Assumption (assumption of the paper). Let $\{ u^\epsilon\}$ be a family of rough path solutions to  ((sf of the paper)) with initial data $u_0^\epsilon$ satisfying 
    $\sup_{\epsilon>0}\left\| u^\epsilon_0 \right\|_{H} <\infty$.   Then there exists a subsequence $\{ u^{\epsilon_n}\}$ such that $u^{\epsilon_n} \rightarrow u$ in  $L^{2}([0,T];H) \cap C([0,T],H_{w})$. 

    Furthermore, the limit is a rough path solution to (equation eq:limit-eq of the paper)
   and the convergence holds in the controlled rough path topology: 
        \begin{equs}
         u^{\epsilon_n} & \rightarrow u  \; \text{ in } C^{\frac{1}{\alpha-\delta} \textrm{-var}}([0,T]; H^{-1});\qquad 
         R^{u^{\epsilon_n}} &\rightarrow R^u, \;  \text{ in } C^{\frac{1}{2(\alpha-\delta)}\textrm{-var}}([0,T]; H^{-2})
        \end{equs}
        for any $\delta>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] Let $z\in\mathbb R^d$, then for all $i\in I$, $x_i\in E_i$ and $T>0$, under assumptions \eqref{hyp:Lip} and \eqref{hyp:ErgoF} and if $F_i(z,\,\cdot\,)\in\mathcal A_i$ we have
\begin{align*}
\mathbf E_{x_i}\big[\varphi(\mathbf Z_{\tau_1^n}^{n,z})\,\mathbf 1_{\{\tau_1^n\leq T\}}\big]\underset{n\to\infty}{\longrightarrow}\mathbf E_{x_i}\big[\varphi(\bar{\mathbf Z}_{\tau_1}^z)\,\mathbf 1_{\{\tau_1\leq T\}}\big],\quad\forall\varphi\in C_b^1.
\end{align*}

[Lemma 7 of arXiv:2512.04544, 'On the diameter of random uniform hypergraphs in dense regime'] Let $c,d,n,p$  be as in Assumption \ref{ass bollobas}, and $G \in \mathscr{G}(n,p)$.  Suppose $I$ is the index set as defined in \eqref{def I}. Then, for $\alpha,\beta \in I$ and $\alpha\neq \beta$,
	\begin{align*}
		\Prob \left( X_ \alpha =1,X_\beta = 1 \right) \approx \frac{c^2}{n^4}, \mbox{ as } n\to \infty,
	\end{align*}	
	where $X_\alpha$ is as defined in \eqref{eqn:xalpha}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:approxIVGFFbyXY of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] For any sidelength $L \in \ensuremath{\mathbb{N}}$, any $x \in \Lambda_L$, any triplet of inverse temperatures $\beta, \beta_1 , \beta_2 \in (0 , \infty)$ and any percolation configuration $r \in \{ 0,1\}^{\Lambda_L}$,
    \begin{equation*}
        \lim_{n \to \infty} \mathrm{Var}_{L, n, \beta, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} \left[ \varphi(x) \right] = \mathrm{Var}_{L, \beta, r}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}} \left[ \varphi(x) \right]
    \end{equation*}
    and
    \begin{equation*}
        \lim_{n \to \infty}  \mathrm{Var}_{L, n, \beta_1 , \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} \left[ \varphi(x) \right] =   \mathrm{Var}_{L, \beta_1 , \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY/GFF}} \left[ \varphi(x) \right].
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2608.21905, '\bf Ruin theory incorporating MIPP-type jumps'] Assume $c>\lambda^nm$. Then the ruin probability $\Pi_n(x)$ satisfies the integral equation
\begin{equation*}
\begin{split}
 c\Pi_n(x)=\lambda\sum_{k=1}^{\infty}P(V_1^{(n-1)}=k)\left(\int_x^{\infty}(1-F^{*k}(y))\,dy+\int_0^x\Pi_n(x-y)(1-F^{*k}(y))\,dy\right).
\end{split}
\end{equation*}

