[Lemma Lemma-F of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $s>\frac{d}{2}+1$.
		Let  $F$ be defined in (equation F-Euler of the paper).  
		\begin{itemize}[leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item If (Constant Sound of the paper) holds, then there exists a constant $c_{1,s}>0$ such that   for all $X=(\varrho,u)^T\in \mathbb H^{s+1}$,
			\begin{equation}
				\Abs{\left\langleF(X), X\right\rangle _{\mathbb H^s}}\leq c_{1,s}  \big(\|\nabla u\|_{L^\infty}+\|\nabla \varrho\|_{L^\infty}\big)\|X\|_{\mathbb H^s}^2.
			\end{equation}





			\item If (General Sound of the paper) holds, then there exists a constant $c_{2,s}>0$ such that  for all $X=(\varrho,u)^T\in \mathbb H^{s+1}$,
			\begin{equation}
				\Abs{\left\langleF(X), X\right\rangle _{\mathbb H^s}}\leq c_{2,s} \big(1+\Phi_\Lambda(\|\varrho\|_{L^\infty})\big)\big(\|\nabla u\|_{L^\infty}+\|\nabla \varrho\|_{L^\infty}\big)\|X\|_{\mathbb H^s}^2.
			\end{equation}
		\end{itemize}

