\begin{align}

 \abs{
 \int_{\Omega\times\mathbb S^1}
 \mathcal U_{\rm sl,0}^\varepsilon(x,w)
 (w\otimes w):D_x^2\phi(x)
 \,\mathrm d x\mathrm d\nu(w)
 }
