body:
[Theorem DCXSZ of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume the same hypotheses as in Theorem (SSS of the paper). Then $\phi_{\mathbf{X}}(\xi)$ is is Fr\'echet differentiable (with respect to $\xi$). In addition, for 
			$D_{\xi}\phi_{\mathbf{X}}:\mathscr{D}_{\mathbf{X}}^{\gamma}([0,r]\rightarrow \mathscr{D}_{\mathbf{X}}^{\gamma}([0,r] $, we can find a polynomial $Q_1$ such that
			\begin{align*}
				&\Vert D_{\xi}\phi_{\mathbf{X}}[\zeta]\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([0,r]}\leq \exp\big(Q_{1}(\Vert\xi\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0])},\Vert\mathbf{X}\Vert_{\gamma,[0,r]})\big),
			\end{align*}
			for every $\xi,\zeta \in\mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0])$.

[Theorem t:scaling_limit_cutoff of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Let $M\geq 1$, $\mu>0$ and $R>0$. Suppose that $p,q\in (2,\infty)$ satisfy  (equation eq:condition_pq_subcritical_scaling_cutoff of the paper).

Then, for all $\varepsilon\in (0,1)$, 
\begin{equation}

\lim_{N \to \infty}\sup_{u_0\in \mathcal{B}_{p,q}(M)}{\mathbf P}\big(\|w_{{\rm cut}}^N - w_{{\rm cut,d}}\|_{L^{2p}({\mathbb R}_+;L^{2q}(\mathbb{T}^3;{\mathbb R}^3))}\geq \varepsilon\big)=0,
\end{equation}
where $w_{{\rm cut}}^N$ is the global $(p,q)$-solution to (equation eq:navier_stokes_cutoff of the paper) with initial data $u_0-\overline{u}_0$, and $w_{{\rm cut,d}}$ is the unique global $(p,q)$-solution to the following deterministic {{\normalfont{3D NSEs}}} with cutoff and \emph{increased viscosity} on $\mathbb{T}^3$:
\begin{equation}

\left\{
\begin{aligned}
\partial_t w_{{\rm cut,d}} 
&+(\overline{u}_0\cdot \nabla) w_{{\rm cut,d}} \\
&+\phi_{p,q}^R (\cdot,w_{{\rm cut,d}}) \,\mathbb{P}\big[ \nabla\cdot (w_{{\rm cut,d}} \otimes w_{{\rm cut,d}})\big] 
= \Big(1 + \frac{3\mu}{5}\Big)\Delta w_{{\rm cut,d}}, \\
w_{{\rm cut,d}}(0)&=u_0-\overline{u}_0.
\end{aligned}
\right.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 68 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] We introduce the following notions:
\begin{enumerate}
\item We call the $\bbr^{d \times d}$-valued process $\bbb = \bbb^{\rm Strat}$ defined by the Stratonovich integrals
\begin{align*}
\bbb_{s,t} := \int_s^t B_{s,r} \otimes \circ dB_r, \quad s,t \in [0,T]
\end{align*}
the \emph{Stratonovich-enhancement} of Brownian motion.

\item We call the process $\bfb = \bfb^{\rm Strat}$ defined as $\bfb := (B,\bbb)$ the \emph{Stratonovich-enhanced Brownian motion}.
\end{enumerate}

[Corollary 10 of arXiv:2609.01402, 'Parabolic Lie algebroid connections on parabolic principal bundles over curves'] Take a compact connected Riemann surface $X$ with a finite set of marked points $S\, \subset\, X$.
Take a connected complex reductive affine algebraic group $G$ and a parabolic subgroup $P\, \subset\, G$.
Let $\mathcal{E}_{G}$ be a parabolic principal $G$--bundle on $(X,\,S)$ which is not semistable. Let
\begin{equation}
\mathcal{E}_{P}\ \subset\ \mathcal{E}_{G}
\end{equation}
be the parabolic 
Harder--Narasimhan reduction of structure group of $\mathcal{E}_{G}$.
Then for any parabolic Lie algebroid $(V_{*},\, \phi_{*})$ on $(X,\,S)$ for which $\phi_{*}$ is not surjective, 
there is a holomorphic parabolic $(V_{*},\, \phi_{*})$--connection on $\mathcal{E}_{P}$.

[Lemma 22 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $0\in Q$. Then
under the assumptions of Theorem \ref{theorem 12.20.2}
for any $\varepsilon\in(0,1]$ we have
\begin{equation}

u(0)\leq N\varepsilon^{-q_{0}d/p }
\|\varepsilon\Delta u\|_{L_{(q,p)}(Q)},
\end{equation}
where $N$ is independent of $\varepsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Macro of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Assume that the edge weights satisfy Assumption~(ass:weight of the paper) and $\ell/n\to \gl\in(0,1/2)$. Let $U_n$ be an independent uniform vertex in $\{1,2,\ldots,n-1\}$, $T_n^{(\ell)}(0,U_n)$ be the first-passage time defined in~(equation eq:unif-target-Tn of the paper), and let $\mathfrak{a}_\ell$ be as in
(equation eq:aell-def of the paper). Then
\begin{align*}
 \mathfrak{a}_\ell\cdot T_n^{(\ell)}(0,U_n)-\log n
 \Rightarrow S_\infty\text{ as } n\to\infty,
\end{align*}
where
\begin{align}
 S_\infty\stackrel{d}{=}
 -\log M_\infty^{(1)}-\log M_\infty^{(2)}-G_3-\log\theta,
\end{align}
$M_\infty^{(1)},M_\infty^{(2)}$ are i.i.d.~copies of $M_\infty$ defined in~(equation eq:Minfty-def of the paper), $G_3$ has the standard Gumbel distribution and is independent of $(M_\infty^{(1)},M_\infty^{(2)})$.
In particular,
\begin{align*}
 \frac{n^{1/\theta}}{\log n}\cdot T_n^{(\ell)}(0,U_n)
 \stackrel{\pr}{\to} \bigl(2\gl\Gamma(\theta+1)\bigr)^{-1/\theta} \text{ as } n\to\infty.
\end{align*}
The same results hold if we replace the random target $U_n$ by a fixed target $\mathsf{u}_n$ as defined in~(equation eq:fixed-target-Tn of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 of arXiv:2604.21162, '2604.21162'] Under {\bf Assumption (H1)}, for every
$f\in C_c^2 (\R^d)$,
there exist a random variable $k_0(\w)\ge1$ and a constant $C_2>0$ such that for all $k\ge k_0(\w)$,
\begin{equation}
\int_{k^{-1}\Z^d} |\widehat \sL^{(k)}f(x)-\bar \sL^{(k)}f(x) |^2\,\mu^{(k)}(dx)\le \frac{C_2}{\log k}.
\end{equation}

