body:
[Theorem thm: MainHaarDisc of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Let $\bM\sim \operatorname{SymHaar}(\widehat{R}^{n\times n})$. 
     Then, for every fixed prime $p$, 
     \begin{align}
        &\lim_{n\to \infty}\bbP\Bigl(\coker(\bM - x\bI ) \textnormal{ satisfies condition }\cD_p^1 \Bigr) = \Bigl( 1 - \frac{1}{p}\Bigr) \prod_{i=1}^\infty\Bigl(1 - \frac{1}{p^{2i}}\Bigr) , \\
        &\lim_{n\to \infty}\bbP\Bigl(\coker(\bM - x\bI ) \textnormal{ satisfies condition } \cD_p^1 \textnormal{ or }\cD_p^2 \Bigr)= \Bigl(1 - \frac{1}{p^2} \frac{3p-1}{p+1}\Bigr)\prod_{i=1}^\infty\Bigl(1 - \frac{1}{p^{2i}}\Bigr).  
     \end{align}
     Moreover, let $\cD^*$ denote the condition that $\cD_p^1$ or $\cD_p^{2}$ is satisfied for every odd prime $p$, and that $\cD_p^1$ is satisfied for $p=2$. 
     Then, 
     \begin{align}
        \lim_{n\to \infty}\bbP\Bigl(\coker(\bM - x\bI ) \textnormal{ satisfies condition }\cD^*    \Bigr) = \frac{6}{7} \prod_{\textnormal{primes }p}\Bigl(1 - \frac{1}{p^2} \frac{3p-1}{p+1}\Bigr)\prod_{i=1}^\infty\Bigl(1 - \frac{1}{p^{2i}}\Bigr). 
     \end{align}

