[Theorem 7 (Asymptotics for $\alpha \to \alpha_0$, $\alpha_0 \in \inter{\mathcal M}$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $z_0 \in \R^2$. Then, if $\alpha_0 \in \inter{\mathcal{M}}\cap (0, \pi)$, we have
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop\alpha\to\alpha_0}{\sim}
C^+(\alpha_0)h_{\alpha_0}(z_0)  \frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha))}}{\sqrt{r}}
\end{equation}
and if $\alpha_0 \in \inter{\mathcal{M}}\cap(\pi, 2\pi)$, the following asymptotics hold
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop\alpha\to\alpha_0}{\sim}
C^-(\alpha_0)h_{\alpha_0}(z_0)  \frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)z(\alpha))}}{\sqrt{r}}
\end{equation}
where $C^\pm(\alpha)$ and $h_{\alpha_0}(z_0)$ are defined as follows. The coefficient $C^\pm(\alpha)$ is given by:
\begin{align}
C^\varepsilon(\alpha) &= \frac{1}
{ \sqrt{2\pi  \left( \Sigma^\varepsilon_{11}\sin^2(\alpha) - 2\Sigma^\varepsilon_{12} \sin(\alpha)\cos(\alpha) + \Sigma^\varepsilon_{22} \cos^2(\alpha) \right)} }
\sqrt{ \frac{ \sin(\alpha) }{ \partial_y \gamma_\varepsilon(x(\alpha), y(\alpha)) } }, \quad \varepsilon \in \{+, -\}.
\end{align}

Furthermore, $h_\alpha(z_0)$ is defined as follows:
\begin{itemize}
    \item If $\alpha \in \mathcal{M}\cap(0, \pi),$ then
    \begin{equation} 
    h_\alpha(z_0) =
    \begin{cases}
    e^{a_0x(\alpha) + b_0y(\alpha)} - \dfrac{\gamma(x(\alpha), y(\alpha), Z^+(x(\alpha)))}{\gamma(x(\alpha), Y^-(x(\alpha)), Z^+(x(\alpha)))} e^{a_0x(\alpha) + b_0Y^-(x(\alpha))} & \text{if } b_0 \geq 0 \\[2ex]
    \left(1 - \dfrac{\gamma(x(\alpha), y(\alpha), Z^+(x(\alpha)))}{\gamma(x(\alpha), Y^-(x(\alpha)), Z^+(x(\alpha)))}\right) e^{a_0x(\alpha) + b_0Z^+(x(\alpha))} & \text{if } b_0 < 0
    \end{cases}
    \end{equation}

    \item If $\alpha \in {\mathcal{M}}\cap(\pi, 2\pi)$, then
    \begin{equation} 
    h_\alpha(z_0) =
    \begin{cases}
    \left(1 - \dfrac{\gamma(x(\alpha), Y^-(x(\alpha)), z(\alpha))}{\gamma(x(\alpha), Y^-(x(\alpha)), Z^+(x(\alpha)))}\right) e^{a_0x(\alpha) + b_0Y^-(x(\alpha))} & \text{if } b_0 \geq 0 \\[2ex]
    e^{a_0x(\alpha) + b_0z(\alpha)} - \dfrac{\gamma(x(\alpha), Y^-(x(\alpha)), z(\alpha))}{\gamma(x(\alpha), Y^-(x(\alpha)), Z^+(x(\alpha)))} e^{a_0x(\alpha) + b_0Z^+(x(\alpha))} & \text{if } b_0 < 0
    \end{cases}
    \end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem serco of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] For every $A>0$, the following series is convergent: 
\begin{equation}
    \sum_{n_1, n_2, n_3=1}^\infty \frac{A^{n_1+n_2+n_3}}{\sqrt{n_1!(n_1\vee n_2 - n_1\wedge n_2)!(n_2\vee n_3 - n_2\wedge n_3)! n_3! }}.   
\end{equation}

