[Proposition Ham3 of arXiv:2411.13788, '\bf Gradient bounds and Liouville property for a class of hypoelliptic diffusion via coupl'] Let $u$ be the positive  bounded solution to the hypoelliptic heat equation $\mathcal{L} u(x,t)=\partial_tu(x,t)$ with the initial value  $0\le f\le C$ ($C$ is a constant), we have for any  $x\in\mathbb{R}^{m_0}\times\cdots \times\mathbb{R}^{m_r}$ and $t>0$, \begin{equation}
\frac12\langle \mathcal{C}(t)\nabla \ln u,\nabla \ln u\rangle\le \ln \frac{C}{u}.
\end{equation}

[Definition 2 (Lipschitz Continuity) of arXiv:2608.24146, 'Robust Data-Collection Policy Learning for Low-Variance Online Policy Evaluation'] The function $f: \mathcal{X}\to \mathbb{R}$ is $L-$Lipschitz if $\forall x_1,x_2\in \mathcal{X},$ 
\begin{align}
\norm{f(x_1)-f(x_2)}\leq L\norm{x_1-x_2}.
\end{align}

[Proposition 25 of arXiv:2609.02294, 'Existence and Blow-Up for Non-linear Fokker-Planck with Controlled Drift Divergence'] For every measurable positive function $f: \R^d \to [0,\infty)$, the following holds. 
\begin{enumerate}
    \item If
    \begin{equation}

    \begin{split}
        \left(\frac{2(k+1)}{dk-\alpha-1}\right)^{\frac{k+1}{(d+2)k-\alpha+1}}  \left( \frac{w_d k}{k - (\alpha + 1)} \right)^{-\frac{k}{(d+2)k + 1 - \alpha}} \cdot \\ \cdot\left( \int f^{k+1} |xb| dx \right)^{- \frac{1} {(d+2)k + 1-\alpha}} E^{\frac{k+1}{(d+2)k + 1 - \alpha}}\le \bar\rho
        \end{split}
    \end{equation}
    then
    \begin{equation*}
    \begin{split}
        \|f\|_1 &\le C(k,d,\alpha)\left( \int f^{k+1} |xb| dx \right)^{\frac{2}{(2+d)k + 1 - \alpha}} E^{\frac{dk - \alpha - 1}{(d+2)k + 1 - \alpha}}
     \end{split}
    \end{equation*}
    \item If
    \begin{equation}

    \begin{split}
        \left(\frac{1}{\beta\bar\rho}\right)^{-\frac{\alpha(k+1)}{((d+2)k+1)k}} \left(\frac{2(k+1)}{dk-1}\right)^{\frac{k+1}{(d+2)k+1}}\left( \frac{w_d k}{k -  1} \right)^{-\frac{k}{(d+2)k + 1 }} \cdot \\ \cdot\left( \int f^{k+1} |xb| dx \right)^{- \frac{1} {(d+2)k + 1}} E^{\frac{k+1}{(d+2)k + 1}} \geq \bar \rho,
        \end{split}
    \end{equation}
    then 
    \begin{equation*}
    \begin{split}
        \|f\|_1 &\le C(k,d,\alpha)\left(\frac{1}{\beta\bar\rho}\right)^{\frac{2\alpha(k+1)}{((d+2)k+1)k}}\left( \int f^{k+1} |xb| dx \right)^{\frac{2}{(2+d)k + 1 }} E^{\frac{dk - 1}{(d+2)k + 1 }}.
     \end{split}
    \end{equation*}
\end{enumerate}

