body:
[Lemma 17 of arXiv:2605.09459, 'Multipoint connectivity in the branching interlacement process'] Let $x_1,\dots,x_k \in \mathbb{Z}^d$. Let $X$ be a random walk indexed by an infinite critical tree $\mathcal{T}$. Then under $\P_{x_1}$,
  \begin{equation}
    \{x_1,\dots,x_k \in \mathrm{Range}(X)\} = \bigcup_{m=0}^{k-1}\bigcup_{z_1,\dots,z_m \in \mathbb{Z}^d} \bigcup_{T \in \mathbb{T}_{k+m}^k(\overline{x}_k,\overline{z}_m)} \left\{\begin{array}{c} X \text{ connects } x_1,\dots,x_k, z_1,\dots,z_m\\ \text{ following } T\end{array}\right\}.
  \end{equation}
  Consequently, if $\mu$ has a finite moment of order $2k-1$,
  \begin{equation}
    \P_{x_1}\big(x_1,\dots,x_k \in \mathrm{Range}(X)\big) \lesssim \sum_{m=0}^{k-1}\sum_{z_1,\dots,z_m \in \mathbb{Z}^d} \sum_{T \in \mathbb{T}_{k+m}^k(\overline{x}_k,\overline{z}_m)} \prod_{\{u,v\}\in E(T)}\frac{1}{1+\|u-v\|^{d-2}}.
  \end{equation}

[Lemma lem:Ball-influence-on-crossing of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Let $\mathcal V_1$ denote the event that there exists a plus crossing connecting  $\partial\Lambda_{M/2}$ and $\partial\Lambda_{M/4+1}$, and
    $\mathcal V_2$ denote the event that there exists a plus circuit in $\Lambda_{M/2}\setminus\Lambda_{M/4}$.  Then there exists a constant $c_{10}>0$ such that for any configurations $\eta_I$ on $\mathrm{Ball}(I)$ and any boundary condition $\xi\in\Sigma_M^c$, we have 
    \begin{equation}
\mu_{\Lambda_M\setminus\mathrm{Ball}(I)}^{\xi,\eta
        _I}(\mathcal V_i)\geq c_{10}^{|I|} \quad \mbox{for } i=1,2.
    \end{equation}

[Lemma lem:local_time_RW of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] Let $S_{n}:=X_{1}+\dots+X_{n}$, $n\ge 0$, $S_{0}=0$ denote a random walk on $\mathbb{Z}$ where the increments $(X_{k})_{k\ge 1}$ are i.i.d., mean zero, finite variance, and integer-valued. Furthermore, assume   $\mathbb{P}(X_{1}\ge -1)=1$ (downward skip-free) and $\mathbb{P}(X_{1}=-1)>0$. Let $M_{n}:=\min_{0 \le k \le n} S_{k}$ 
    denote the running minimum of $S_{n}$ and let $N_{n}$ denote the times that $S_{k}=M_{k}$  for $0\le k \le n$. Then we have 
    \begin{align}
        \mathbb{E}[N_{n}]=(1+o(1))  \, \mathbb{P}(X_{1}=-1) \sqrt{\frac{2\textup{Var}(X_{1}) n}{\pi }} 
    \end{align}

