[Definition 4 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] {\em((Power) spectral density)}
  Let $(\mathbf{x}_t)_{t\geq 0}$  be a stationary process. Then 
  \begin{align}
    S_\mathbf{x}(\omega)=\lim_{T\to\infty} \E\left[\frac{|G_T(\omega)|^2}{2T}\right]
\end{align}
is called (power) spectral density.

[Lem SymAd of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] One has 
\begin{align*}
 & A_{1}\partial_{{\rm e}_{1}}\hat{\otimes}_{{\rm s}}\cdots\hat{\otimes}_{{\rm s}}A_{r}\partial_{{\rm e}_{1}}({\rm ad}_{{\rm e}_{1}}^{l}(v))\\
 & =\sum_{\sigma\in{\cal S}_{r}}\sum_{\substack{\substack{\xi_{1}+\cdots+\xi_{r+1}}
=l-r}
}{\rm ad}_{{\rm e}_{1}}^{\xi_{1}}\circ{\rm ad}_{A_{\sigma(1)}}\circ{\rm ad}_{{\rm e}_{1}}^{\xi_{2}}\circ\cdots\circ{\rm ad}_{{\rm e}_{1}}^{\xi_{r}}\circ{\rm ad}_{A_{\sigma(r)}}\circ{\rm ad}_{{\rm e}_{1}}^{\xi_{r+1}}(v)
\end{align*}
for any $l\geqslant r\geqslant1$.

[Theorem 8 of arXiv:2608.12070, 'Central limit theorems for a heavy-tailed subcritical Galton-Watson process with state-dep'] Let $\{Z_n, n\geq 1\}$ be a sequence of i.i.d. random variables whose tails are regularly varying with index $1<\alpha<2$ (as in \eqref{add}), satisfying $\E Z_1=0$. Assume there exist $p, q \in [0, 1]$ such that 
\begin{align} 
\frac{\P(Z>x)}{\P(|Z|>x)} \to p, \quad \frac{\P(Z<-x)}{\P(|Z|>x)} \to q, \quad x\to \infty.
\end{align}
Let $\{t_n, n\geq1\}$ be a sequence of positive, integer-valued random variables. Suppose there exists a sequence of positive integers $\{b_n\}$ and a positive constant $c$ such that $t_n/b_n \overset{\P}{\to} c$ and $b_n \to \infty$. Define $S_n = \sum_{i=1}^n Z_i$. Then, as $n \to \infty$,
\begin{align*}
\frac{S_{t_n}}{a_{t_n}} \overset{d}{\to} S_\alpha(\rho, 0),
\end{align*}
where $\{a_n\}$ is a sequence satisfying $n a_n^{-\alpha}L(a_n) \to 1$, $\rho = p - q$, and $S_\alpha(\rho, 0)$ is an $\alpha$-stable random variable with characteristic function
\[
\exp\left(-|t|^\alpha \Gamma(1-\alpha)\cos\frac{\pi\alpha}{2} \left(1 + i\rho\, \mathrm{sgn}(t)\tan\frac{\pi\alpha}{2}\right)\right).
\]

