[Proposition 9 of arXiv:2511.11189, 'Sharp asymptotics for the maximal distance from the boundary to the nucleus of a typical P'] The expectation \(C_d\) given in identity (\ref{eq_C_d_as_expectation}) satisfies the recursive relation:
		\begin{equation}
			C_d = \frac{1}{2(d-1)} \left( \frac{B\left(\frac{d}{2},\frac{1}{2}\right)}{B\left(\frac{d-1}{2},\frac{1}{2}\right)} \right)^{d-1} C_{d-1}.
		\end{equation}
		As a consequence,
		\begin{equation}
			C_d = 		\frac{1}{2^{d-1}\sqrt{\pi}(d-1)!}\frac{\Gamma\left(\frac{d}{2}\right)^{d}}{\Gamma\left(\frac{d+1}{2}\right)^{d-1}}.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop pr:key_estimate of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given $i,j\in \mathbb{N}$ and $\alpha \geqslant 0$, then for every $\mathsf{r} \in (\frac{50}{27}, 2)$, and every $N,k \in \mathbb{N}$ satisfying
		\begin{align}
			N \geqslant i+j, \qquad k \geqslant \max\{h, h_*(\alpha,i,j)\} + 12(i+j) + 2,
		\end{align}
		there exists a constant $C(i,j,\alpha,h,N,k,d,\mathsf{r})$ independent of $m \in \mathbb{N}_+$ such that the following statement holds: for every ${\scaleobj{1}{\square}}_m \in \mathcal{G}^{(N)}_{k}$, we have the estimate when the canonical grain (equation def.ConstantExtension_canonical of the paper) is applied to $v_m$ in ${\scaleobj{1}{\square}}_m$ 
		\begin{multline}

			\frac{1}{|{\scaleobj{1}{\square}}_m|}\sum_{\substack{|F|=i\\F\subseteq E_d({\scaleobj{1}{\square}}_m)}}\left(\sum_{\substack{{\scaleobj{1}{\square}} \in \mathcal{P}^{(N,k)}_{h}({\scaleobj{1}{\square}}_m)}} |{\scaleobj{1}{\square}}|^{\alpha}\sum_{e\in E_d({\scaleobj{1}{\square}})} |\nabla V_{m}(F, j)(e)|^2 \right) \\ \leqslant C(i,j,\alpha,h,N,k,d,\mathsf{r}) .
		\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 3 of arXiv:2609.02392, 'Large values of cubic and quartic Dirichlet $L$-functions of prime moduli'] With the notation as above, let $j=3$, $4$ and $\psi$ be any ray class character modulo $9$ (resp. $16$) when $j=3$ (resp. $j=4$) and let $r$ be any primary element in $\mathcal O_K$. Then we have for real $Z>1$ and $\varepsilon>0$, we have
\begin{align*}

\begin{split}
  H_Z(r;\psi) := \sum_{\substack {c \odd \\ (c, r)=1 \\ N(c) \leq Z}} \frac {\Lambda_K(c)\psi(c) g_{K,j}(r, c) }{\sqrt{N(c)}}  \ll &
\begin{cases}
   \min (Z^{1+\varepsilon},  N(r)^{1/10+\varepsilon}Z^{4/5+\varepsilon}), & j=3, \\ \\
   \min (Z^{1+\varepsilon},  N(r)^{1/16+\varepsilon}Z^{7/8+\varepsilon}), & j=4.
\end{cases}
\end{split}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:timeChange of arXiv:2412.04973, 'On the Laplace equation with non-local dynamical boundary conditions'] Let $\Lambda>0$, $l \geq 0$, $k <0$ and $\alpha \in (0,1]$. The solution to (equation ELambda of the paper) has the probabilistic representation
\begin{align*}
u(t,x) 
= & \mathbf{E}_x\left[\mathbf{E}_{X^+_\tau}[u_0(X^\Gamma \circ L_t)]\right]\\
= & \mathbf{E}_x\left[e^{-\Lambda L_t} \mathbf{E}_{X^+_\tau}[u_0(X^{0, \Gamma} \circ L_t)]\right], \quad t\geq 0,\; x \in \overline{\Omega}.
\end{align*}
In particular,
\begin{align*}
u(t,x) 
= & \int_0^\infty e^{-\Lambda s} \mathbf{E}_x\left[\mathbf{E}_{X^+_\tau}[u_0(X^{0, \Gamma}_s)]\right]  \mathbf{P}_0(L_t \in ds)\\
= & \int_0^\infty e^{-\Lambda s} w(s,x) \mathbf{P}_0(L_t \in ds)
\end{align*}
where $w$ is the solution to (equation EsolVVw of the paper).

