[Thm discrete-conv of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $\tau_\delta$ be a critical XOR-Ising model in the setup of Theorem (thm:ES-XOR of the paper). As $\delta\to 0$, 
    \begin{equation}
        \big(\delta^{-1/4}\tau_\delta,\ (\delta^{-1/4}\mu_k^\delta)_{k\geq1},\ (C_k^\delta)_{k\geq1},\ (\xi_k^\delta)_{k\geq1}\big) \overset{(d)}{\longrightarrow} \big(\tau,\ (\mu_k)_{k\geq1},\ (C_k)_{k\geq1},\ (\xi_k)_{k\geq1}\big),
    \end{equation}
    where the limiting law is that of Theorem (thm:cont-XOR of the paper). Under the obvious modifications, the same statement holds for $+/+$ boundary conditions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 5 of arXiv:2609.00719, 'On the Aleksandrov--Bakelman--Pucci estimates for the weighted $1$-Laplacian'] Let $u\in C(\R^n)$ have compact support, and let $\Gamma$ be the quasiconcave envelope of $u^+$.
Then the following properties hold.
\begin{enumerate}
\renewcommand{\labelenumi}{(\roman{enumi})}
\item For every $a>0$,
\begin{equation}
\operatorname{Conv}(\{u^+\geq a\})=\{\Gamma\geq a\}.
\end{equation}
Moreover, for every $a\geq0$,
\begin{equation}
\operatorname{Conv}(\{u^+>a\})=\{\Gamma>a\}.
\end{equation}
\item Every modulus of continuity of $u^+$ is also a modulus of continuity of $\Gamma$.
In particular, if $u$ is $L$-Lipschitz, then $\Gamma$ is $L$-Lipschitz.
\end{enumerate}

[Lemma lem:tildeH-convex of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] The modified Hamiltonian $\tilde H^+$ is concave in $\mathcal{D}_+$, and
    \begin{align*}
        -\nabla^2_{\mathsf{Sp}} \tilde H^+ +\frac1\beta \mathrm{Ric}\succeq \kappa_\textsc{be} I.
    \end{align*}
    for a constant $\kappa_{\textsc{be}} >0$. The same holds for $\tilde H^-$ on $\mathcal D_-$.

