[Definition 1 (Skorokhod modulus) of arXiv:2607.12666, 'Sample-path Large deviations for \\Scheduled Arrival Processes with Unpunctuality'] For $\phi \in D([0,T])$ and $\delta>0$, define
\begin{equation}
w'(\phi,\delta,T)
:=
\inf_{\Pi}
\max_{1\le i\le m}
\sup_{s,t \in [t_{i-1}, t_i]} |\phi(t)-\phi(s)|,
\end{equation}
where the infimum is taken over all partitions
$
\Pi=\{0=t_0<t_1<\cdots<t_m=T\}
$
such that
$
t_i - t_{i-1} \ge \delta$, with $i=1,\dots,m.$

[Corollary cor:wMRWbercanc of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] For any sequence $\eta_\ell\le \ell$, let $\varepsilon_\ell=\varepsilon(\phi_{[\ell-\eta_\ell,\ell]}^M)$. Then, we have
    \begin{equation} 
{\mathbb{V}\mathrm{ar}}\left( Y_M([\ell-\eta_\ell,\ell])[2]\right)
\le
\frac{1}{\ell^{n-1}\eta_\ell}\left( \mathrm{O}\left( \frac{\eta_\ell}{\ell}\right)^2 +\mathrm{O}\left( \varepsilon_\ell \right)\right)
    \end{equation}
    and if $1-\alpha=\liminf \frac{\eta_\ell}{\ell} >0$, then
    \begin{equation} 
{\mathbb{V}\mathrm{ar}}\left( Y_M([\ell-\eta_\ell,\ell])[2]\right)
=\Theta\left( \ell^{-n}\right),
    \end{equation}
    as $\ell \to +\infty$.

[Corollary cor.conv.nb.zeros of arXiv:2609.01007, 'Global universality of the expected number \\of zeros of non-analytic random signals'] Suppose that the base function $f$ is of class $\mathcal{C}^2([0,2\pi])$ and satisfies the condition $\mathbf{(H1)}$, then we have
\begin{enumerate}
\item $\mathbb{P}-$almost surely, as $n$ goes to infinity and under $\mathbb P_X$, the number of zeros $\mathcal{N}(g_n,[0,2\pi])$ of the localized process $(g_n(t))_{t\in[0,2\pi]}$ converges in distribution towards $\mathcal{N}(g_{\infty},[0,2\pi])$. 
\item As $n$ goes to infinity, $\mathcal{N}(g_n,[0,2\pi])$ converges in distribution under $\mathbb{P} \otimes \mathbb{P}_X$ towards $\mathcal{N}(g_{\infty},[0,2\pi])$. 
\end{enumerate}

[Theorem thm:main of arXiv:2604.04922, 'Elephant random walk on the infinite dihedral group $\mathbb{Z}_2 * \mathbb{Z}_2$'] There exists a zero-mean martingale $(\Xi_n)_{n \ge 0}$ adapted to $(\mathcal{F}_{n})_{n \ge 0}$, with bounded increments and its predictable quadratic variation $\langle \Xi \rangle_n$ satisfying $\frac{\langle \Xi \rangle_n}{n} \xrightarrow{\text{a.s.}} 1$, such that
\begin{equation}
    \Delta_{n}^{(s)} = \Xi_n + q \sum_{k = 1}^{n - 1} (-1)^k \frac{W_k}{k},
\end{equation}
where $q = 2p - 1 \in [-1, 1)$. The predictable process $(Z_n)_{n \ge 0}$, where $Z_n := \Delta_{n}^{(s)} - \Xi_n$, converges almost surely and in $L^2$ to the zero-mean random variable
\[
    Z_{\infty} := q \sum_{k = 1}^{\infty} (-1)^k \frac{W_k}{k},
\]
with variance
\begin{equation}
    \mathbb{E}[Z_{\infty}^2] = \begin{cases} \frac{q^2}{2q-1}
    \int_0^1\frac{u^{-2q + 1} - 1}{1 - u} \cdot \frac{(1 - \frac{u}{2})^{q - 1} - 1}{u} \, du & \text{if } q \ne \frac{1}{2}, \\[5pt]
    \frac{1}{4} \int_0^1 \frac{-\ln u}{1-u}\cdot\frac{\left(1-\frac{u}{2}\right)^{-1/2}-1}{u}\,du & \text{if } q = \frac{1}{2}.
    \end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

