[Corollary 40 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(k\) be a perfect field and let
  \begin{equation*}
    S \defeq \bracketlr{\setA^1_k/\setG_{m,k}}^n.
  \end{equation*}
  This admits a \(\delta\)-lifting
  \begin{equation*}
    S_{W(k)} \defeq \bracketlr{\setA^1_{W(k)}/\setG_{m,W(k)}}^n
  \end{equation*}
  over \(W(k)\) with Frobenius lift given on the standard coordinates by
  \begin{equation*}
    t_i  \mapsto  t_i^p, \qquad u_i  \mapsto  u_i^p.
  \end{equation*}
  Then, for every integer \(r \geq 1\), there exists a morphism
  \begin{equation*}
    s'_r \colon W_rS_{\setF_p} \to S
  \end{equation*}
  and a commutative diagram
  \begin{equation*}
    \begin{tikzcd}
    W_rS_{\setF_p} \arrow[d, "s'_r"'] \arrow[rd, "\sigma_{S,r}"] &         \\
    S \arrow[r, "\pi_S"']                                  & S^{\dR}
    \end{tikzcd}
  \end{equation*}
  of \(\setF_p\)-stacks, where \(\pi_S \colon S \to S^{\dR}\) is the natural morphism given in \Cref{DefdeRhamStack} and \(\sigma_{S,r} \colon W_rS_{\setF_p} \to S^{\dR}\) is the morphism obtained by \cite{petrov2025Decomposition}*{Corollary~4.4} (\Cref{ConstPetrov}).

[Lem 51 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For any $f,\psi,\varphi\in\BL^{\kappa},x,y,x_n,y_n\in M$ and a non-empty subset $A\subseteq M$,
the following hold.
  \begin{align}
     |G_x\psi(y)-G_{x_n}^n\varphi(y_n)|
  \leq&\|\varphi\|_{L^1(F_n,\mu_n)}(d(x,x_n)+d(y,y_n))\notag\\
    &+(2d(x,y)^{1-\kappa}+d(x,y))\|\varphi\|_{\BL^{\kappa}(K_n)}d_{\BL^{\kappa}}(\mu,\mu_n)\\
    &+d(x,y)\|\varphi-\psi\|_{L^1(F,\mu)}\notag
  \end{align}
  \begin{equation}
    \begin{aligned}
    \|G_xf-G^n_{x_n}f\|_F
    \leq&\|f\|_{L^1(F_n,\mu_n)} d(x,x_n)\\
    &+3(1+\diam(F))\|f\|_{\BL^{\kappa}(K_n)}d_{\BL^{\kappa}}(\mu,\mu_n)  
    \end{aligned}
  \end{equation}
  \begin{equation}
   \|G_xf\|_{A} \leq\sup_{a\in A}d(x,a)\|f\|_{L^1(F,\mu)}
  \end{equation}
  \begin{equation}
    \|G_xf\|_{\Lip^{\kappa}(A)}\leq\diam(A)^{1-\kappa}\|f\|_{L^1(F,\mu)}
  \end{equation}

