[Defn tr-tree-gen of arXiv:2508.13827, 'Surface sums in two-dimensional large-$N$ lattice Yang--Mills: Cancellations and explicit '] Let $(\ell, K)$ be a balanced loop plaquette assignment and let $e$ be an edge contained in $\ell$ that is connected to infinity by a path of plaquettes $\mathfrak{p}$. We define the \textbf{trajectory tree $\mathcal{T}_{e,\mathfrak{p}}(\ell, K)$ generated from $(\ell, K, e, \mathfrak{p})$} to be the trajectory tree constructed from $(\ell, K)$ by (cf.\ (fig: traj tree of the paper)) :
\begin{itemize}
    \item Declaring a leaf $l$ to be a final leaf only if the string plaquette assignment $\{(\ell_1, K_1), \dots, (\ell_n, K_n)\}$ corresponding to $l$ satisfies the following property:  
    \begin{equation}
        \text{$\ell_i\cap \mathcal{I}(\mathfrak{p})=\emptyset,$ for all $i \in [n]$.}
    \end{equation}
    Note the root cannot be a final leaf as $e$ is contained in $\ell$.

    \item For any non-final leaf, $l= \{(\ell_1,K_1),\dots,(\ell_n,K_n)\}$, arbitrarily select one of the loop plaquette assignments in $l$ such that the corresponding loop contains an edge in $\mathcal{I}(\mathfrak{p})$ (note such a loop plaquette assingment must exist for any non-final leaf by the construction of final leaves above). Then apply the the ML-operator to any copy of the outermost edge of $\ell_i$ in $\mathcal{I}(\mathfrak{p})$.

    \item Finally, for all final leaves, remove all backtracks as required by the definition of trajectory trees generated from a loop plaquette assignment ((defn:tr-tree-gen of the paper)).
\end{itemize}

[Prop LT-1 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Given $\eta \in (0,\frac{1}{2}-\gamma)$, for each $\theta \geq 0$ there exists a constant $C=C(\theta,\gamma) > 0$ such~that, if $k$ is sufficiently large, given any integer $j > 1$, $n \geq k$ and $\widetilde{x} \in {\rm D}_n$ with $\overline{{\rm B}^+[\widetilde{x};j]}\subseteq {\rm D}_n$, we have that 
	\begin{equation}

 {\rm e}^{-2\sqrt{2}\widehat{v}-\frac{\widehat{v}^2}{k+jk^\gamma}-Ck^\gamma} \leq \mathbb{P} \bigg( \min_{x \in {\rm B}^-[\widetilde{x};j-1]}L_t(x) \leq \theta \,\Big|\, \sqrt{\widehat{N}_t[\widetilde{x};j]} \geq v \,; 
\mathcal F[\widetilde{x};j]\bigg) \leq  {\rm e}^{- 2\sqrt{2}\widehat{v}+Ck^\gamma}
\end{equation} uniformly over all $t >0$ and $v \in \mathcal R^\eta_k(j)$, where above we abbreviate $\widehat{v}:=v-\sqrt{2}(k+(j-1)k^\gamma)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: probability to be at the fruit at a given time of arXiv:2509.23069, 'Every cutoff profile is possible'] Let $(k, \boldsymbol{\ell},\boldsymbol{\rho}) \in {\ensuremath{\mathcal P}} $. There exist $C_2>0$ and $\varepsilon_2>0$ such that the following holds. Let $\varepsilon\in (0,\varepsilon_2)$. Let $(X_t)_{t\geq 0} = (X_t^{(\varepsilon)})_{t\geq 0} $ be the FIT Markov chain with parameters $(k, \boldsymbol{\ell},\boldsymbol{\rho}, \varepsilon)$. Denote its stationary distribution by $\pi_\varepsilon$.
    \begin{enumerate}
        \item Let $1\leq i\leq k$ and $\ell_0+1 \leq j \leq \ell_0 + \ell_i-1$. Let $t\geq \ell_0$. We have
\begin{equation}
    {\ensuremath{\mathbb P}} _{y_j^i} (X_t = z) \geq 1- C_2\varepsilon.
\end{equation}
\item Let $0\leq j \leq \ell_0$. Let $t\geq 0$. We have
\begin{equation}
    \left| {\ensuremath{\mathbb P}} _{x_j} (X_t = z) - {\ensuremath{\mathbb P}} _{x_0} (X_{t+j} = z) \right| \leq C_2 \varepsilon.
\end{equation}
\item Let $t\geq \ell_0 + 1$. We have
\begin{equation}
    \left| {\ensuremath{\mathbb P}} _{x_0} (X_t = z) - G(t) \right| \leq C_2\varepsilon.
\end{equation}
    \end{enumerate}

