[Proposition prop:var-computation of arXiv:2604.04922, 'Elephant random walk on the infinite dihedral group $\mathbb{Z}_2 * \mathbb{Z}_2$'] We have
    \begin{equation}
        \mathbb{E}[\tilde{Z}_{\infty}^2] = \begin{cases}
        \frac{1}{2q-1}\int_0^1\frac{u^{-2q + 1} - 1}{1 - u} \cdot \frac{(1 - \frac{u}{2})^{q - 1} - 1}{u} du & \text{if } q \ne \frac{1}{2}, \\[5pt]
        \int_0^1 \frac{-\ln u}{1-u}\cdot\frac{\left(1-\frac{u}{2}\right)^{-1/2}-1}{u}\,du & \text{if } q = \frac{1}{2}.
        \end{cases}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:iidmax of arXiv:2601.20502, 'Optimal matching under size priority'] Let $G$ be a finite graph. Consider $M_{\mathrm{opt}}$ to be the maximum weight maximum size matching on $G$ when we pick a family $w(e)_{e \in E(G)}$ of weights. Formally, define $W^{\mathrm{bad}}\subseteq \mathbb{R}_+^{E(G)}$ to be the set of weights such that there are ties, and $\mathcal{M}_{\mathrm{max}}$ to be the set of maximal matchings on $G$. Then $M_{\mathrm{opt}}$ is the map defined as
    \begin{align*}
        \mathbb{R}_+^{E(G)} \setminus W^{\mathrm{bad}} &\to \mathcal{M}_{\max} \\
        w(e)_{e \in E(G)} &\mapsto M_{\mathrm{opt}}(w(e)_{e \in E(G)}).
    \end{align*}
     The range of $M_{\mathrm{opt}}$ is precisely $\mathcal{M}_{\max}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 22 of arXiv:2608.19832, 'Sharp Convex Concentration for Symmetric Random Tensors with Subgaussian Coordinates'] Let $G\sim N(0,I_n)$ and put $f(T)=\norm T$. If
$1\le p\le cn/d^2$, then, for every $m\in\R$,
\[
 \Pp\left\{
 \abs{f(G^{\otimes d})-m}
 \ge cd n^{(d-1)/2}\sqrt p
 \right\}
 \ge e^{-Cp}.
\]

