[Lemma 36 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Under the assumptions of Theorem \ref{distribution of outliers}, set $z=\theta_i^a+\ii n^{-2}$ for some $1\le i \le r$. Then, for $\mathcal{P}_i^a\equiv \mathcal{P}_i^a(z)$ and any fixed $\ell\geq 2$, we have 
\begin{equation}
\begin{aligned}
\expect[(\mathcal{P}_i^a)^\ell]=&~(\ell-1)\pbb{\frac{d_i^a+1}{d_i^a}}^4(\sigma_i^a)^2\pB{2m_{2a}(\theta_i^a)+k_4b(\theta_i^a)s_4(\vv_i^a)}\expect[(\mathcal{P}_i^a)^{\ell-2}] +\OO_\prec(n^{-1/6}).
\end{aligned}
\end{equation} 
Moreover, for $\ell=1$, we have $\expect[\mathcal{P}_i^a]=\OO_\prec(n^{-\e})$ for some constant $\e>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:OU-estimate of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Let $Y_t$ solve~(equation eq:Y_t-OU of the paper)
    with $Y_0=0$. Fix a threshold value $R>0$, and let 
    \begin{align*}
        \tau_{R}=\inf\{t>0 \ : \ Y_t^2>R^2\}\,,
    \end{align*}
    then for any $r>0$ we have:
    \begin{align*} 
    \mathbb{P} ( \tau_{R} > T_R +r ) < 2e^{-r}\,,\,\, \mathbb{P}(\tau_R < T_R-r)<\frac12 e^{-2r}\,,\,\,\text{where} \  T_R= \log (R\sqrt{N})\,.
    \end{align*}

[Theorem thm-GG1 of arXiv:2505.00198, '\ttl'] For any $q\in (0,1)$, the equation (equation eqGG1:mainequation of the paper) has a unique bounded solution. Since both $F_{W^{\texttt{R}}}$ and the CDF defined by the series (equation eqGG1:solutionseries of the paper) satisfy (equation eqGG1:mainequation of the paper), they must coincide. That is, 
\begin{align} 
F_{W^{\texttt{R}}} =& \sum_{j = 0}^{\infty} q (1-q)^j{\tt K}^j  \left({\bf 1}_{{\mathbb R}_+}\right)  \nonumber  \\
 =& q{\bf 1}_{{\mathbb R}_+}+ q(1-q)F_X{\bf 1}_{{\mathbb R}_+}+q(1-q)^2(F_X*(F_X{\bf 1}_{{\mathbb R}_+})){\bf 1}_{{\mathbb R}_+}  \nonumber  \\
& \  +q(1-q)^3(F_X*((F_X*(F_X{\bf 1}_{{\mathbb R}_+})){\bf 1}_{{\mathbb R}_+})){\bf 1}_{{\mathbb R}_+}+\cdots. 
\end{align}

[Proposition of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $P \in \mathcal{S}(\pi)$ be the nearest-neighbour simple random walk on $\llbracket n \rrbracket$ described at the beginning of this subsection, and $Q$ be a permutation matrix drawn uniformly at random from $\mathcal{Q}$. For all $\varepsilon \in (0,1)$, there exists $C(\varepsilon)$ such that with high probability
	\begin{align*}
		t_{mix}(\overline{P}(Q),\varepsilon) \leq \dfrac{\ln n}{\ln 2} + C(\varepsilon) \sqrt{\ln n}.
	\end{align*}

[Proposition prop:alphaSDE of arXiv:2509.15446, 'On the pair correlation function of the $\Sineb$ process'] Fix $\beta>0$ and $\Re \delta>-1/2$. 

\begin{enumerate}
    \item For any $\nu\in {\mathbb R}$ the system (equation eq:alphaSDE of the paper) has a unique strong solution $\alpha_{\lambda,\nu}(u)$ on $[\nu,\infty)$ with initial condition $\alpha_{\lambda,\nu}(\nu)=0$. For any given $\nu< u$, with probability one the function $\lambda\mapsto \alpha_{\lambda,\nu}(u)$ is analytic and strictly increasing with $\alpha_{0,\nu}(u)=0$ 

    \item There is a unique strong solution $\alpha_\lambda(u)$ of (equation eq:alphaSDE of the paper) on $(-\infty,\infty)$ satisfying the initial condition (equation eq:SDE_initial of the paper), which  can be obtained as the a.s.~limit $\alpha_\lambda(u)=\lim\limits_{\nu\to -\infty} \alpha_{\lambda,\nu}(u)$. The limit is monotone increasing for $\lambda>0$ and monotone decreasing for $\lambda<0$. 

    For any $u\in {\mathbb R}$ with probability one the function $\lambda\mapsto \alpha_\lambda(u)$ is analytic and strictly increasing in $\lambda$ with $\alpha_0(u)=0$. 

    Moreover, $\alpha_\lambda(u)$ satisfies the following scale-invariance property: for any fixed $s\in {\mathbb R}$ 
\begin{align}
    \left(\alpha_\lambda(t), t\in (-\infty,\infty)\right) \stackrel{d}{=}  \left(\alpha_{e^{\beta s/4}\lambda}(t-s), t\in (-\infty,\infty)\right). 
\end{align}  
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conj maps pairs of arXiv:2609.02409, 'Membranes and Maps'] The stable pair series lifts to a rational function in $q$ satisfying
    \begin{equation}
        \ch[\mathsf{T}] \, \PTargs{X}{Z}{\mathsf{T}'}{\beta}
        =
        \GWdiscargs{Z}{\mathsf{T}}{\beta} 
    \end{equation}
    under the change of variables induced by the Chern character $\ch[\mathsf{T}] \colon \mathrm{Rep}(\mathsf{T}) \to \widehat{\mathsf{R}}$. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Corollary cor:kpz-shift-vacuum-kp of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] In the vacuum background $C=0$ and $\Lambda=0$, the dressed
observable satisfies
\begin{equation}

\mathcal A_{at}
+\tfrac14\mathcal A_{xx}
+\tfrac1{12}\mathcal A_{aaaa}
+\tfrac12(\mathcal A_a^2)_a
+\tfrac12[\mathcal A_a,\mathcal A_x] = 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem theorem 1 of arXiv:2411.14350, 'Randomized Geodesic Flow on Hyperbolic Groups'] There exists a measure $\Theta$ on $\partial^2 G$ satisfying 
\begin{equation}
\frac{{\rm{d}}\Theta}{{\rm{d}} (\nu_o\otimes\nu_o)} (\xi,\eta)\asymp {\rm e} ^{2(\xi,\eta)_o^{{\mathcal G}}} \qquad\forall (\xi,\eta)\in \partial^2 G, 
\end{equation}
which can be constructed explicitly in the following three measure-equivalent ways:
\begin{enumerate}
\item As the measure $\Theta_1$ given by
\begin{equation}
\Theta_1(A) = \int_{A} \lim_{n\to\infty} \sum_{z=-n}^n\bigg[\frac{1}{2n+1} \, \frac{{\rm{d}}(\nu_{p_z}\otimes \nu_{p_z})}{{\rm{d}}(\nu_{o}\otimes \nu_{o})}(\xi,\eta)\bigg]\;{\rm{d}}(\nu_{o}\otimes \nu_{o})(\xi,\eta)
\end{equation}
for $A\subset \partial^2 G$, where $(p_z)_{z\in\mathbb{Z}}=(p_z(\xi,\eta))_{z\in\mathbb{Z}}$ is a fixed quasi-geodesic between $\xi$ and $\eta$. 
\vspace{2mm}
\item As a disintegrated version $\Theta_2$ of $\Theta_1$, defined by
\begin{equation}
\Theta_2(A) = \int_{A} \lim_{n\to\infty} \sum_{z=-n}^n \bigg[\frac{1}{2n+1} \,\frac{{\rm{d}}(\nu_{x_z}\otimes \nu_{x_z})}{{\rm{d}}(\nu_{o}\otimes \nu_{o})}(\xi,\eta)\bigg]\;{\rm{d}}\bar\mathbb{P}_o\big((x_n)_{n\in\mathbb{N}}\big),
\end{equation}
for all $A\subset\partial^2 G$, where $\xi={\rm bd} (x_n)_{n\in\mathbb{N}}$ and $\eta={\rm bd} (x_{-n})_{n\in\mathbb{N}}$.
\vspace{2mm}
\item  As the push forward $\Theta_3(\cdot)= \widehat\mathbb{Q}({\rm bd} ^{-1}(\cdot))$ of the measure $\widehat\mathbb{Q}$ (defined in (equation def QZ int of the paper)) under the boundary map ${\rm bd} : G^{\mathbb{Z}}\to \partial^2 G$. The measure $\Theta_3$ is invariant under the action of $G$ on $\partial^2G$. 
\end{enumerate}
Finally, the measure $\Theta$ on $\partial^2 G$ is 
\begin{itemize}
    \item quasi-invariant under the $G$-action with uniformly bounded Radon-Nikodym derivatives $\frac{{\rm{d}} g_{\ast}\Theta}{d\Theta}$, and
    \item ergodic under the action of $G$ on $\partial^2 G$. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 100 (Geometric $L^{\infty}$ norms) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] For scalar functions or $\ell_{t,u}$-tangent tensorfields $\upxi$, we define 
	the following $L^{\infty}$ norm on the double-null tori $\doublenulltoritwoarg{\ubar}{u}$:
	\begin{align} 
		\| \upxi \|_{L^{\infty}\left(\doublenulltoritwoarg{\ubar}{u}\right)}
		& 
		\eqdef 
		\mbox{ess sup}_{(x^2,x^3) \in \mathbb{T}^2}
		|\upxi|_{\gtorus}(\ubar,u,x^2,x^3),
	\end{align}
	where on RHS\,\eqref{E:GEOLINFINITYDOUBLENULLTORUS}, we are viewing
	$\upxi$ as a function of the rough adapted coordinates
	$(\ubar,u,x^2,x^3)$.

