[Definition def: Hotspot of arXiv:2609.04054, 'An obstruction to the maximal singularity of the Hilbert scheme of points on threefolds'] For a zero-dimensional Borel-fixed ideal $I$ in three variables, we define the \emph{hotspot} ${\mathfrak{C}}(I)$ to be the set of the cubes in ${\mathbb{N}}^3\setminus \tilde I$ which are immediately below a generator of $I$ (recall that, by our convention,  a generator is an element of the minimal set of generators). In other words,  ${\mathfrak{C}}(I)$ is the set of the top cubes of the columns of ${\mathbb{N}}^3\setminus \tilde I$. See Figure (Fig: Caravansarai of the paper).


\begin{figure}[h]

  \subcaptionbox*{}[.94\linewidth]{
    \includegraphics[width=\linewidth]{Hotspot.png}
  }
  \caption{${\mathbb{N}}^3\setminus \tilde I$ and the associated hotspot ${\mathfrak{C}}(I)$.}



\end{figure}

[Lemma lemma9 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $\varphi$ be a characteristic satisfying (C1 of the paper)-(C2 of the paper). For $u \in \mathcal{I}$ and $n \geq -1$, let $\mathcal{J}_{u} \subseteq \mathcal{I}$ such that $\mathcal{P}_{u} \subseteq \mathcal{J}_{u}$ and  $\mathcal{J}_{u} \cap u\mathcal{I} = \emptyset$. Define the sub-$\sigma$-algebra of $\mathcal{F}$
\begin{align} 
\mathcal{C}_{u}^{(n)} \coloneqq \sigma(\pi_{v}: v\in \mathcal{J}_{u} \cup \mathcal{I}_{u}^{(n)}).
\end{align}
\noindent If $u =\varnothing$ and $n=-1$, we define $\mathcal{C}_{\varnothing}^{(-1)}$ as the trivial $\sigma$-algebra. Then, for $t \in \mathbb{R}$, $u \in \mathcal{I}$ and $k \in \mathbb{N}_{0}$, 
\begin{align}  
\varphi_{u}^{(k)}(t-S(u)) \stackrel{a.s.}{=} \mathbb{E}[\varphi_{u}(t-S(u)) \mid \mathcal{C}_{u}^{(k-1)}] \stackrel{a.s.}{=}  \mathbb{E}[\varphi_{u}(t-S(u)) \mid \mathcal{D}_{u}^{(k-1)}]. 
\end{align}

