body:
[Proposition 8 of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] The optimal value \(\rho_*\) satisfies
\begin{align*}
    \rho_*
    =\min_{\substack{\beta>0,\ \mu>0\\0\neq a\in\Pcal_m}}
      \mathcal J_{\beta,\mu}(a).
\end{align*}
Moreover, the triple \((1,\mu_*,a_*)\) is a global minimizer of the right-hand side.

[Coro 8 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $\{K_n : n \ge 1\} \subseteq \cK(\cX)$ and $p \in [1, \infty)$. Let $\{u_n, v_n : n \ge 1\} \subseteq \bZ\cup\{\pm \infty\}$ with $u_n < v_n$ for all $n\ge 1$ and let $\{a_{n, k} : k \in [u_n, v_n]\cap \bZ, n \ge 1\} \subset \bR$ satisfy 
	$$\sup_{n \ge 1} \sum_{k \in [u_n, v_n] \cap \bZ} |a_{n, k}| <\infty.$$
Assume that $\{X^n_k : k\in S_n, n \ge 1\}$ is $(\nu_n)$-$\CUI(p)$ w.r.t. $\{K_n\}$, where $S_n: = [u_n, v_n] \cap \bZ$, $\cS_n : = \cP(S_n)$, and $\nu_n : = \sum_{k \in S_n} |a_{n, k}| \delta_{k}$. If 
	\begin{align}
		\lim_{n \to \infty} \lt\|K_n\rt\| \sum_{k \in S_n} |a_{n, k}| = 0,
	\end{align}
then
\begin{align*}
	\lim_{n \to \infty} \mathbb{E} \, \BB\| \sum_{k \in S_n} a_{n, k} X^n_k \BB\|^p  = 0.
\end{align*}

