body:
[Theorem thm:optimalliftgns of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $\mathcal{M}$ be a finite-dimensional von Neumann algebra. For a symmetric QMS generator $\mathcal{L}_O$ satisfying the $\kappa$-intertwining condition for $\kappa \in \mathbb{R}$, there exists a second-order lift $\mathcal{L}$ with convergence rate:
    \begin{align*}
         \Omega\left(\frac{\sqrt{\lambda_O}}{  1 +  \sqrt{\max\{0,-\kappa\}\lambda_O^{-1}}}\right) \le \nu(\mathcal{L}) \le \mathcal{O}\left(\sqrt{\lambda_O}\right)\,.
    \end{align*}
    Such lift is optimal if $\max\{0,-\kappa\}\lambda_O^{-1} = \mathcal{O}(1)$, which always holds if $\kappa \ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem T2.3 of arXiv:2512.18990, '\bf Hybrid Stochastic Functional Differential Equations with Infinite Delay: Approximation'] Under Assumptions (A2.1 of the paper) and (A2.2 of the paper), the SFDE ((sfde of the paper)) with the initial data ((id of the paper))  has a unique solution $x(t)$ on $t\in (-\8,\8)$, which has the property
  that
  \begin{align}
    \sup_{0\le t\le T} \mathbb{E} W_1(x(t),t) \le C_T, \ \ \forall T >0,
  \end{align}
  where $C_T$ is a positive constant dependent on $T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma1 of arXiv:2605.28204, 'Estimates of $mm$-entropy of a stable L\'evy process\footnote{Work supported by grant no. '] For every $n \ge 0$ and every $x\in \mathbb D$ it is true that
\begin{equation*}
    \mathcal P(B_{x}(\ep) \cap \{z: N_\ep(z) = n\}) 
    \le \mathcal P(\{z:N_\ep(z) = n\})   \cdot n^k \cdot (2\ep)^k,
\end{equation*}
where $k = K_\ep(x)$, $B_x(\ep)$ is the closed ball of radius $\ep$ centered at $x$.

[Lemma lem:many-PDEs_new of arXiv:2604.25851, '{Non-uniqueness of nonlinear Markov processes in the sense of McKean associated with parab'] Let $(u(t,\cdot))_{t>0} \subseteq  \mathcal P_* $ be a distributional solution to the FPE (equation eq:Main_FPE_our_paper of the paper) with coefficients $(a, b): \mathbb{R}^d \times \mathcal P_* \to \mathbb{R} \times \mathbb{R}^d$ for some $\mathcal P_* \subseteq \mathcal P_{\textup{ac}} $. Let $f: \mathbb{R}^d \times \mathcal D(f) \to \mathbb{R} $ with $\mathcal D(f) \subseteq \mathcal P_{\textup{ac}}$ such that $(u(t,\cdot))_{t >0} \subseteq\mathcal D(f)$,
        \begin{equation}
            f(x,u(t,\cdot)) + a(x,u(t,\cdot))u(t,x) \geq 0 \quad u(t,x)dxdt\text{-a.e.,}
        \end{equation}
        and \begin{equation}
            \big[(t,x)\mapsto f(x,u(t,\cdot))\big] \in L^1_{\textup{loc}}(\mathbb{R}_+;W^{1,1}_{\textup{loc}}(\mathbb{R}^d)).
        \end{equation}
        Then $(u(t,\cdot))_{t> 0}$ is a distributional solution to the FPE with new coefficients $(\hat{a},\hat{b}): \mathbb{R}^d \times \hat{\mathcal P}_*   \to \mathbb{R} \times \mathbb{R}^d$ given by 
        \begin{equation}
             \hat{a} (x,u) \coloneqq  a (x,u) + \frac{f(x,u)}{u(x)},\quad \text{and}\quad \hat{b} (x,u) \coloneqq  b (x,u) + \frac{\nabla f(x,u)}{u(x)},
        \end{equation}    
        on $\{u > 0\}$, and 
        $\frac {f(\cdot,u)} {u} := 0, \,\frac{\nabla f(\cdot, u)}{u} := 0$ on $\{u = 0\}$, defined on
        \begin{equation}
            \hat{\mathcal P}_* \coloneqq \mathcal P_* \cap \{ u \in \mathcal D(f): \, f(\cdot,u) \in W^{1,1}_{\textup{loc}}(\mathbb{R}^d)\}.
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 4 of arXiv:2506.08775, 'Markovian multivariate Hawkes population processes: Efficient evaluation of moments'] Fix $t\in\rr_+$, and let $\bm{Q}(0) = \bm{0}$, $\bm{\lambda}(0) = \bm{\overline{\lambda}}$.
Then, for any $\bm{z}\in[-1,1]^d$, $\bm{s}\in\rr_+^d$,
\begin{align}

    \zeta(t,\bm{s},\bm{z}) = \prod_{j=1}^d \exp\Big( - \overline{\lambda}_j \tilde{s}_j(t)- \overline{\lambda}_j\alpha_j \int_0^t \tilde{s}_j(v)\mathrm{d} v \Big).
\end{align}
Here, for $j\in[d]$ and $v\in[0,t]$, the functions $\tilde{s}_j(\cdot)$ satisfy, with boundary condition $\tilde{s}_j(0) = s_j$,
\begin{align}

    \frac{\mathrm{d} \tilde{s}_j(v)}{\mathrm{d} v} + \alpha_j\tilde{s}_j(v) + (1 + (z_j - 1)e^{-\mu_j v})\beta_j(\tilde{\bm{s}}(v)) - 1 = 0.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] There is some $\gamma > 0$ such that for $p > \fr{1}{2} - \gamma$ the following holds.
There are random variables $\Psi^\cE, \Psi^\cO$, which can be expressed explicitly as functions of
the percolation configuration, such that
\begin{equation}
    \fr{\Cnt}{2^{2^{d-1}}} \psim e^{\Psi^\cE} + e^{\Psi^\cO}.
\end{equation}
Moreover, there are explicit deterministic quantities $\mu = \mu_{d,p}$ and $\sigma = \sigma_{d,p}$ (defined below)
such that
\begin{equation}
    \Rnd{ \fr{\Psi^\cE - \mu}{\sigma}, \fr{\Psi^\cO - \mu}{\sigma} }
    \dto \Nor{0}{1} \otimes \Nor{0}{1}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 68 of arXiv:2601.16377, '2601.16377'] Under Assumption~\ref{Assumptions_Theta}, there exists $C > 0$ depending only on the constants in the assumptions, such that for any $\boldsymbol{\ell} \in \amsmathbb{W}_\N$, there exists an absolutely continuous nonnegative measure $\tilde{\mu}_{\N}$ with the following properties:
\begin{itemize}
\item $\widetilde{\mu}_{\N} \in \mathscr{P}_{\star}$.
\item $|\widetilde{\mu}_{\N} - \mu_{\N}^*|(\amsmathbb{R}) \leq \frac{C}{\N}$.
\item $\widetilde{\mu}_{\N}$ and $\mu_{\N}^*$ coincide outside $[-C,C]$.
\end{itemize}

[Definition of arXiv:2606.19313, 'Stability of Khintchine-type inequalities via log-monotonicity'] Fix $p\geq 1$, and let $a,b\in \mathbb{R}^n$. Let $X$ be a random variable and $X_1, X_2, \ldots, X_n$ iid copies of $X$. We say $X$ has the \emph{Schur-concave property for $p$} if 

\begin{align*}
(a_1^2, a_2^2,\ldots, a_n^2)\prec (b_1^2, b_2^2, \ldots, b_n^2)\Longrightarrow \|  \sum_i a_i X_i \|_p\geq \|  \sum_i b_i X_i \|_p,
\end{align*}in which $\| \cdot \|_p=(\mathbb{E}|\cdot |^p)^{\frac{1}{p}}$. We say $X$ has the \emph{Schur-convex property for $p$}\footnote{The implication $a\prec b\Longrightarrow \|  \sum_i a_i X_i \|_p\leq \|  \sum_i b_i X_i \|_p$ always holds for $p\geq 1$; see [Chavez1], for example.} if 

\begin{align*}
(a_1^2, a_2^2,\ldots, a_n^2)\prec (b_1^2, b_2^2, \ldots, b_n^2)\Longrightarrow \|  \sum_i a_i X_i \|_p\leq \|  \sum_i b_i X_i \|_p.
\end{align*}

[Prop 13 (Variational identity) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $a > 0$ and $c > 0$. Then $X \lecx c\Lap$ holds for every $X \in \SE(1,a)$ if and only if
\begin{align*}
    p(1-p)\,\nu_{\max}(p,a) \le c\,\Lambda(p)
    \qquad \text{for all } p \in (0, 1/2],
\end{align*}
with $\Lambda$ as in \eqref{eqn:Lambda}. Consequently,
\begin{align}
    c^{\SE}(1, a) = \sup_{p \in (0,1/2]} R(p,a),
    \qquad
    R(p,a) \coloneqq \frac{(1-p)\,\nu_{\max}(p,a)}{1 + \log\frac{1}{2p}},

\end{align}
and the infimum in \eqref{eqn:defc} is a minimum: $c^{\SE}(1,a)$ is itself admissible.

