[Proposition 4 (Posterior expectations of the complete-data sufficient statistics) of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] At iteration $t$, define
\begin{align*}
  \widetilde{\Sigmab}^{(t)}
  =
  \tilde{\Lambdab}^{(t)}
  \Gammab^{(t)}
  \tilde{\Lambdab}^{(t)\star}
  +
  \Psib^{(t)},\quad
  \widetilde{\Ab}^{(t)}
  =
  \Gammab^{(t)}
  \tilde{\Lambdab}^{(t)\star}
  \left(\widetilde{\Sigmab}^{(t)}\right)^{-1},\quad
  \widetilde{\Cb}^{(t)}
  =
  \Gammab^{(t)}
  -
  \widetilde{\Ab}^{(t)}
  \tilde{\Lambdab}^{(t)}
  \Gammab^{(t)}.
\end{align*}
Then, the conditional distribution of the latent factor matrix is
\begin{align*}
  \tilde{\Zb}\mid\Xb,\tilde{\thetab}^{(t)}
  \sim
  \mathbb{C}\Ncal_{k\times n}
  \left(
    \widetilde{\Ab}^{(t)}\Xb,
    \widetilde{\Cb}^{(t)},
    \Ib_n
  \right),
\end{align*}
and the posterior expectations of the complete-data sufficient statistics in \eqref{eq:sufficient_stat_defs} are
\begin{align}

  \tilde{\Zb}^{(t)}
  =
  \widetilde{\Ab}^{(t)}\Xb, \qquad
  \widetilde{\Sbb}_{zz}^{(t)}
  =
  n\widetilde{\Cb}^{(t)}
  +
  \tilde{\Zb}^{(t)}
  \tilde{\Zb}^{(t)\star}.
\end{align}

[Definition 2 of arXiv:2605.04684, 'Ergodicity of stochastic functional differential equation with jumps and finite delay'] A distance-like function $d$ bounded by $1$ is called contracting for $P_{t}$ if there exists $\alpha<1$ such that for any $\xi,\eta \in \mathscr{D}$ with $ d(\xi,\eta)<1$, we have
\begin{equation*}
    W_{d}\left(P_{t}(\xi, \cdot), P_{t}(\eta, \cdot)\right) \leq \alpha d(\xi, \eta),
\end{equation*}
where $P_t(\xi,\cdot)$ and $P_t(\eta,\cdot)$ are the transition functions of the process $(X_{t}^{\xi})_{t \geq 0}$ and $(X_{t}^{\eta})_{t \geq 0}$, respectively.

[Lemma Hlfsn of arXiv:2609.01990, 'Jacquet-Zagier treatment of the beyond endoscopy trace formula for \(\GL_2\)'] We can write \[
    H_{l,f}^s(0,n) = J_{l,f}(0,n) + \left(\frac{\sqrt{\pi} lf^2}{2 \sqrt{n}}\right)^{2s-1} I_{l,f}(0,n) 
    \] as 
    \begin{equation}
        H_{l,f}^s(0,n) = \frac{1}{2\pi i } \int_{(2)} \frac{(2w - \frac{3}{2})}{(w+\frac{s}{2}-1)(w-\frac{s+1}{2}) } \Gamma(w) \mathcal{F}(w,s) \left(\frac{\sqrt{\pi}lf^2}{2\sqrt{n}} \right)^{-2w+s+1} dw 
    \end{equation}
    with 
    \begin{equation}
        \mathcal{F}(w,s) = \int_{-1}^{1} F_s(y) (1-y^2)^{w - \frac{s+1}{2}} dy 
    \end{equation}

