[Proposition PROP:OUN of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $L_\varepsilon=\varepsilon^{-\frac 12+\eta}$ and let $g$ be a real-valued, smooth, compactly supported function. Under the conditions   
\begin{align}
\textup{dist}(\supp g, \xi_j) \ge \varepsilon^{-\frac 12 +2\eta} 

\end{align}

\noindent
for every  $1 \le j \le k$,  we have 
\begin{align}
&\mathbb{E}_{\nu^\perp_{\xi_1,\dots,\xi_k } } \Big[ e^{i \langle v,g \rangle } e^{\frac 1\varepsilon \mathcal{E}_{\xi_1,\dots,\xi_k}( \sqrt{\varepsilon}v ) } \textup{Det}_{\xi_1,\dots,\xi_k}(\sqrt{\varepsilon}v)  , \; A_\varepsilon, \;  \| \sqrt{\varepsilon}v\|_{L^2}<\delta_\varepsilon  \Big] \notag \\ 
&=\exp\Big\{-\frac 12 \jb{g, (-\partial_x^2+1)^{-1} g }_{L^2(\mathbb{R})} \Big \} \cdot(1+O(\varepsilon^{0+})), 

\end{align}

\noindent
uniformly in $\xi_1,\dots,\xi_k \in [-\overline L_\varepsilon, \overline L_\varepsilon]$ and $\overline L_\varepsilon$. Here  $A_\varepsilon=\big\{ \|v \|_{L^\infty} \le K \sqrt{|\log L_\varepsilon|} \big\}$, defined in Lemmas (LEM:T1 of the paper), and $\delta_\varepsilon=\sqrt{\varepsilon \log \frac 1\varepsilon}$ in (equation LDPIN2 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Prop_UniversalZeroLocus_Harmonic of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] The \defined{universal zero locus} of non-degenerate $\mathbb{Z}/2\mathbb{Z}$ harmonic spinors
  \begin{equation*}
    {\mathbf{Z}}_{{\mathbf{P}}\mathbf{Harm}^*}
    \coloneq
    \set[\big]{
      ({\mathbf{p}},[{\mathfrak l}];[\Phi],x) \in {\mathbf{P}}\mathbf{Harm}^* \times X
      :
      x \notin \mathrm{Br}({\mathfrak l}),
      \Phi(x) = 0      
    }
  \end{equation*}
  is a tame Fréchet submanifold of ${\mathbf{P}}\mathbf{Harm}^* \times X$ and $\mathrm{pr}_{{\mathbf{P}}\mathbf{Harm}^*} \mskip0.5mu\colon\thinspace {\mathbf{Z}}_{{\mathbf{P}}\mathbf{Harm}^*} \to {\mathbf{P}}\mathbf{Harm}^*$ has index $-1$.

[Theorem 13 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $\sigma=\frac{3}{4}+\gamma$ with $\gamma\in(0,\frac{1}{4})$. For any $v_0\in L_\sigma^2(\IR^2)\cap H^\sigma(\IR^2)$ and
\begin{equation}
\beta>1-2\gamma,
\end{equation} 
there exists a time $T>0$ until which there exists a unique solution
\begin{equation}
v\in\CC([0,T],L_\sigma^2(\IR^2)\cap H^\sigma(\IR^2))\cap L^2([0,T],W^{\gamma,6}(\IR^2))
\end{equation}
to the mild formulation
\begin{equation}
v_t=S_tv_0-i\int_0^tS_{t-s}v_s\cdot V_\beta*|e^Xv_s|^2\drm s
\end{equation}
where $V_\beta\in W^{\beta,1}$. Moreover, the solution depends continuously on the initial data $v_0\in L_\sigma^2(\IR^2)\cap H^\sigma(\IR^2)$. In particular, there exists a unique mild solution for $\sigma_\beta<\sigma<1$ with
\begin{equation}
\sigma_\beta=\frac{5}{4}-\frac{\beta}{2}
\end{equation}
for any $\beta>\frac{1}{2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 (Process-level punctured intertwining) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] One has the following intertwining:
\begin{equation}
  \wh K_D\Lambda=\Lambda P_D.
\end{equation}
Consequently, there exists a Markovian coupling
$(\wh S_n^D,\wh X_n^D)_{n\geq0}$ such that, when
$\wh S_0^D=\{x\}$ and $\wh X_0^D=x$,
\begin{enumerate}[label=\textup{(\roman*)}]
  \item $(\wh S_n^D)$ has transition kernel $\wh K_D$;
  \item conditionally on $\wh S_n^D=A\neq\dagger$,
  \[
    \Pp(\wh X_n^D=y\mid\wh S_n^D=A)=\Lambda(A,y);
  \]
  \item $(\wh X_n^D)$ has the law of the $P$-chain up to its first exit from $D$.
\end{enumerate}
After rate-one Poissonization, the same assertions hold in continuous time. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] We have
    \begin{align*}
        \Cov\left(\sum_{i,j=1}^m \left(\vert i-j \vert +1\right)I_j,\sum_{k=1}^m I_k(I_k-1)\right)=0.
    \end{align*}

[Proposition 20 (Integration, Step 4.a) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let $[\beta]\geq0$ and assume that \eqref{est_Pi-} holds for $\Pi^-_{x\beta}$. Then

\begin{equation}
\Pi_{x\beta} \coloneqq \int_0^\infty ds\, (\mathrm{id}-T_x^{<|\beta|}) ( -\partial_{x_{0}}- \Delta) \Pi^-_{x\beta s}
\end{equation}

is the unique solution of $(\partial_{x_{0}}-\Delta)\Pi_{x\beta}=\Pi^-_{x\beta}$ satisfying 

\begin{equation}
\EE^\frac1p\left| \Pi_{x\beta t}(y) \right|^p
\lesssim 
\ve^{|\beta|-\langle\beta\rangle}
(\sqrt[4]{t})^\alpha (\sqrt[4]{t}+|x-y|)^{\langle\beta\rangle-\alpha} \,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 78 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $k\geq 0$ and $j\geq 1$. Let $\eta >0$.
Then
\begin{displaymath}
\lim_{m\to +\infty}
\E\Big[
\Big\Vert
V_{A^{\rm gen, +}_{m}}^{k}
\,
:\Phi_{D\setminus A^{\rm gen, +}_{m}}^{j}:
\Big\Vert^{2}_{H^{-\eta}(\C)}
\Big] = 0.
\end{displaymath}

