body:
[Thma 2 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\pi_0$ be a fixed cuspidal representation for $\PGL_n(F)$ that is unramified at every finite place and tempered at all archimedean places.

		Let $\q=\prod_v \p_v^{r_v}$ be an integral ideal coprime to the different ideal of $F$ such that $N(\q)\to \infty$ and let $(C_v)_{v\mid \infty}$ be a collection of fixed real numbers satisfying $C_v\geq 1$. Then there exists a spectral weight function $\H=\H_\q$ implicitly depending on $\pi_0$ and $(C_v)_v$ defined on the generic automorphic representations for $\PGL_n(F)$, factorizing as
		\begin{equation*}
			\H(\pi)=\prod_{v<\infty}H_v(\pi_v)\prod_{v\mid\infty}h_v(\pi_v),\quad \pi=\otimes'_v\pi_v,
		\end{equation*}
		satisfying the following properties:
		\begin{itemize}
			\item if $v<\infty$ and $c(\pi_v)>r_v$ then $H_v(\pi_v)=0$;
			\item if $v<\infty$ and $c(\pi_v)\le r_v$ then $H_v(\pi_v)\geq 1$ with equality when $r_v=0$; 
			\item if $v\mid\infty$ and $C(\pi_v)\leq C_v$ then $h_v(\pi_v) \gg_{C_v} 1$;
			\item if $v\mid\q$ then $\int_{\gen}H_v(\pi_v)\, d\mu_{\loc}\pi_v\asymp \mathrm{vol}^{-1}\left(K_0\left(\p_v^{r_v}\right)\right)$;
		\end{itemize}
		such that we have








		\begin{multline*}
			\int_{\mathrm{gen}} \frac{|L(1/2,\pi_0\otimes \tilde{\pi})|^2}{\ell(\pi)}\H(\pi)\,d\mu_{\mathrm{aut}}(\pi)\\
			=\Delta^{\mu}\vol(K_0(\q))^{-1}\left(L(1,\pi_0,\mathrm{Ad})\frac{n\zeta^\ast(1)\zeta(\frac{n}{2})^2}{\zeta(n)}\log N(\q)+B_\q\right.\\
			\left.+N(\q)^{-\frac{n-2}2}\frac{\zeta_\q(\frac{n}{2})}{\zeta_\q(1)}\left(C\log N(\q)+D_\q\right)+O_{F,\pi_0,\epsilon}\left(N(\q)^{-\frac{n-1}{2}+\vartheta+\epsilon}\right)\right),
		\end{multline*}
		where $0\le\vartheta<\frac{7}{64}$ is a bound towards the generalized Ramanujan conjecture and $\mu$ is a constant depending only on $n$. Here $B_\q$ and $D_\q$ are explicit $\q$-dependent constants, given by \eqref{eq:def-Bq} and \eqref{eq:def-Dq}, respectively, and are $O_{F,\pi_0}(1)$; and $C$ is a $\q$-independent constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor Corollary: Trivialisation of finite-to-one factors of arXiv:2605.16921, '${\ASL_n}(\mathbb Z)$ invariant random subsets of $\mathbb Z^n$'] Let $\pi_Y: X \to Y$ be a nilfactor over $Z^0(X)$ commensurated by $\SL_d(\mathbb{Z})$, identified via Lemma (Lemma: Def common nilpotent group of the paper) with
    $$ Y \simeq \bigsqcup_{n \geq 0} \Omega_n \rtimes_{\rho_n} N / \Gamma_n.$$
    Let $\pi_Z: X \to Z$ be a nilfactor over $Z^0(X)$ and $p: Z \to Y$ a finite-to-one factor map over $Z^0(X)$ with $\pi_Y = p \circ \pi_Z$. Then there exists an isomorphism
    $$ Z \simeq \bigsqcup_{n, m \geq 0} \Omega_{n, m} \rtimes_{\rho_{n, m}} N / \Gamma_{n, m}$$
    of bundles of nilsystems, where for every $n \geq 0$:
    \begin{enumerate}
        \item $(\Omega_{n, m})_{m \geq 0}$ is a Borel partition of $\Omega_n$;
        \item $\Gamma_{n, m}$ is a finite-index sublattice of $\Gamma_n$;
        \item under this isomorphism, $p(\omega, u \Gamma_{n, m}) = (\omega, u \Gamma_n)$ for $\omega \in \Omega_{n, m}$ and $u \in N$.
    \end{enumerate}

[Theo thm:main of arXiv:2512.06984, 'Infinite Dimensional Multifractal Analysis of the Wiener measure'] Let $ \alpha \in (0,1/2)$. Under the $ C^0$-norm, the local order of the Wiener measure $W$ satisfies 
    \begin{equation*}
    \forall \bar{\omega} \in C_\alpha^\mathrm{crit}, \ \ \ 
    \mathsf{ord}_{\mathrm{loc}}  W ( \bar{\omega } ) = 2 ( \alpha^{-1} - 1) \; , 
    \end{equation*}
    while
    \begin{equation*}
    \mathsf{ord}_H C_\alpha^\mathrm{crit} = \alpha^{-1} \; . 
    \end{equation*}
    Moreover the minimum of $ \underline{\mathsf{ord}}_{\mathrm{loc}}  W(\cdot) $ on the space of continuous function $\Omega$ is equal to $2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 28 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] Let $u$ be a continuous function defined on $[0,T]\times \mathbb{R}$. It is called a viscosity:\\
	\noindent (i) subsolution  of \eqref{PDE} if $u(T,x)\leq \phi(x)$, $x\in\mathbb{R}$, and at any point $(t,x)\in(0,T)\times\mathbb{R}$, for any $(p,q,X)\in\mathcal{P}^{2,+}u(t,x)$,
	\begin{equation}
		\max\bigg(u(t,x)-h'(t,x), \min\big(u(t,x)-h(t,x), -p-F(X,q,u(t,x),x,t)\big)\bigg)\leq 0;
	\end{equation}
	(ii) supersolution of \eqref{PDE} if $u(T,x)\geq\phi(x)$, $x\in\mathbb{R}$, and at any point $(t,x)\in(0,T)\times\mathbb{R}$, for any $(p,q,X)\in\mathcal{P}^{2,-}u(t,x)$,
	\begin{equation}
		\max\bigg(u(t,x)-h'(t,x),\min\big(u(t,x)-h(t,x), -p-F(X,q,u(t,x),x,t)\big)\bigg)\geq 0;
	\end{equation}
	(iii) solution of \eqref{PDE} if it is both a viscosity subsolution and supersolution.

[Lemma lem: lower bound for threshold of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] Suppose that $\boldsymbol{\mu} \in \mathcal{S}^+$ and define $y_*$ as in (equation eq: equilibrium threshold of the paper). Then
	\begin{equation*}
		\bar y_*\left(\boldsymbol{\mu}_t\right) \geq t \wedge y_* \quad \text{for all} \quad t \geq 0.
	\end{equation*}

