[Theorem thm:funnel-ER of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Consider the Bass/{\rm SI} model~(equation eqs:Bass-SI-models-ME of the paper)
	on an undirected network~$\cal N$, in which all the nodes have weight~$p$ and initial condition~$I^0$, 
	and all the edges have weight~$q$. 
	Let $j \in \cal M$, 
	such that $d_j:=\text{degree}(j) \ge 2$, 
	and denote by $\{k_{i}\}_{i=1}^{d_j}$ the nodes that are connected to~$j$.
	For $i=1, \dots, d_j$, 
	define the network~${\cal N}^{k_i,p_j}$  by deleting in~${\cal N}$ all the edges of~$j$,
	except for the edge $j \leftrightarrow k_i$,
	and denote $[S^{k_i,p_j}_j]:=[S_j](t;{\cal N}^{k_i,p_j})$.
	Define also the network~${\cal N}^{p_j}$ 
	by deleting in~${\cal N}$ all the edges of~$j$,
	and denote $[S^{p_j}_j]:=[S_j](t;{\cal N}^{p_j})$. 
	\begin{itemize}
		\item If $j$ does not belong to any cycle in $\cal N$, then
		\begin{equation}

			[S_j] =
			\frac{\prod_{i=1}^{d_j} [S^{k_i,p_j}_j]}
			{([S^{p_j}_j])^{d_j-1}},   \qquad \text{\rm \bf (funnel equality)}
		\end{equation} 
		where
		\begin{equation}

			[S^{p_j}_j]  =  (1-I^0)e^{-pt}.
		\end{equation} 
		\item  If $j$ belongs to the $N_j$~cycles $\{C_n\}_{n=1}^{N_j}$, then 	
		\begin{equation}

			0 < 	[S_{{j}}]  -\frac{\prod_{i=1}^{d_j} [S^{k_i, p_j}_j]}{([S^{p_j}_j])^{d_j-1}}
			< 
			[S_j^{p_j}]	
			\sum_{n=1}^{N_j}
			E(t;L_n), \qquad t > 0  ,	 \qquad \text{\rm \bf (funnel inequality)}


		\end{equation}
		where $L_n$~is the number of nodes of~$C_n$, and~$E(t;L_n)$ satisfies the bounds
		\begin{subequations}

			\begin{equation}

				E(t;L) \le 2(1-I^0)e^{-\left(p+ q \right)t} \bigg(\frac{e q t}{\left \lfloor{\frac{L+1}{2}}\right \rfloor}\bigg)^{\left \lfloor{\frac{L+1}{2}}\right \rfloor}, 
				\qquad    0 \le t  < \frac1q  \bigg \lfloor{\frac{L+1}{2}} \bigg \rfloor, 



		\end{equation}
		and
		\begin{equation}

			E(t;L) \le 2(1-I^0) \left(\frac{q}{p+q} \right)^{\left \lfloor{\frac{L+1}{2}}\right \rfloor},
			\qquad  t \ge 0 . 
		\end{equation}
	\end{subequations}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 of arXiv:2604.10266, 'A singular SDE driven by additive fractional Brownian motion with Hurst parameter $H<\frac'] Let $(\alpha_i,\beta_i)$, $i\geq 1$, be an interval in the presentation of \eqref{interval}. Then,
\begin{itemize}
\item[(a)] $\lim\limits_{t\downarrow \alpha_i}X_t=0=X_{\alpha_i}$ and $\lim\limits_{t\uparrow \beta_i}X_t=0=X_{\beta_i}$;
\item[(b)] for any $t\in [\alpha_i,\beta_i]$, we have
\[
X_t=a\int_{\alpha_i}^t\frac{s^{2H-1}}{X_s}ds-b\int_{\alpha_i}^t X_sds+B^H_t-B^H_{\alpha_i}.
\]
\end{itemize}

[Definition 2 of arXiv:2607.04193, 'Onsager--Machlup Functionals for Generalized Newtonian Equations of Motion with Time-Varyi'] Let $f \in I_{a^+}^\alpha(L^p)$ and $g \in I_{b^-}^\alpha(L^p)$ with $p \ge 1$. The left-sided and right-sided Riemann--Liouville fractional derivatives of order $\alpha > 0$ are defined respectively by
    \begin{align*}
        (D_{a^+}^\alpha f)(x) &:= \left( \frac{d}{dx} \right)^{[\alpha] + 1} I_{a^+}^{1 + [\alpha] - \alpha} f(x), \\
        (D_{b^-}^\alpha g)(x) &:= \left( -\frac{d}{dx} \right)^{[\alpha] + 1} I_{b^-}^{1 + [\alpha] - \alpha} g(x),
    \end{align*}
    where $[\alpha]$ denotes the integer part of $\alpha$.

