[Lemma 20 of arXiv:2512.04544, 'On the diameter of random uniform hypergraphs in dense regime'] Let $t,c,d,n,p$ and  $N$ be as in Assumption \ref{ass main} and $\delta_1$  be as in \Cref{lemma 14}. Let $1 \leq k \leq d -1$ and $ v \in  \Gamma_{k-1} (x) $ be a fixed vertex. 
Suppose 
\[
c_k={ n- \vert N_{k-1}(x) \vert\choose t- 1}p.
\]
Then, for large $n$, we have 
\begin{align}
&\Prob(|H_k^1(x,v)-c_k|>\delta_1c_k\given \Omega_{k,x})\le 2 n^ { - 12 } \mbox{ and }
\\& \Prob(\vert H_k^{1,0} (x,v) \vert\ge  (1- \delta_1 )c_k-10\given \Omega_{k,x})\ge 1-  \frac{ 4(t-1)^{11} }{n^{11} } .
\end{align}

[Corollary cor:free-energy-typical-truncation of arXiv:2411.09075, 'Weak Poincar{\'e} Inequalities, Simulated Annealing, and Sampling from Spherical Spin Glas'] There is a $H_{N,2}$-measurable event with probability $1-e^{-cN^{1/5}}$ on which the following holds.
    For
    \begin{equation}

        {\widetilde T} = {\widetilde T}(H_{N,\sim2}) \coloneqq \lt\{
            \sigma \in S_N :
            \la
                \Ind[|R(\sigma,\tau)| \ge N^{-2/5}]
                e^{H_{N,\sim2}(\tau)}
            \ra_2
            \le e^{N\xi_{\sim2}(1)/2 - cN^{1/5}}
        \rt\},
    \end{equation}
    where the Gibbs average is with respect to $\tau \sim \la \cdot \ra_2$, we have
    \begin{align*}
        \E_{\sim2} \lt\la
            \Ind[\sigma \not\in {\widetilde T}] e^{H_{N,\sim2}(\sigma)}
        \rt\ra_2
        &\le e^{N\xi_{\sim2}(1)/2 - cN^{1/5}}, \\
        \E_{\sim2} \lt\la
            \Ind[\sigma \not\in {\widetilde T}]
        \rt\ra_2
        &\le e^{-cN^{1/5}}, \\
        \E_{\sim2} \lt\la
            \Ind[\sigma^1 \not\in {\widetilde T}, |R(\sigma^1,\sigma^2)| \le 3N^{-2/5}]
            e^{H_{N,\sim2}(\sigma^1) + H_{N,\sim2}(\sigma^2)}
        \rt\ra_2
        &\le e^{N\xi_{\sim2}(1) - cN^{1/5}}, \\
        \E_{\sim2} \lt\la
            \Ind[\sigma^1 \not\in {\widetilde T}, |R(\sigma^1,\sigma^2)| \le 3N^{-2/5}]
            e^{H_{N,\sim2}(\sigma^2)}
        \rt\ra_2
        &\le e^{N\xi_{\sim2}(1)/2 - cN^{1/5}}.
    \end{align*}

