[Lemma 22 of arXiv:2609.00245, 'Higher-order Gaussian bounds for maximally subelliptic boundary value problems'] There exists \(C_1\geq 0\) such that, for every \((\xi,\delta)\in \CompactZero\times (0,\delta_0]\) and every \((-\opL, \xi,\delta)\)-heat function \(u:(-1/2,1/2)\rightarrow \DomainLinfty\), the following statements hold.
    \begin{enumerate}[(i)]
        \item  
        If \((\xi,\delta)\in \SSetOne\), set \(U(t,x):=u(t,\Phi_{\xi,\delta}(x))\). Then,



            \begin{equation*}
                \LtNorm*{\partial_t U}[(-3/8,3/8)\times \Cuben{3/8}]
                \leq C_1 \LtNorm{U}[(-7/16,7/16)\times \Cuben{7/16}].
            \end{equation*}
        \item 
        If \((\xi,\delta)\in \SSetTwo\), set \(U(t,x):=u(t,\Psi_{\xi,\delta}(x))\). Then,


            \begin{equation*}
                \LtNorm*{\partial_t U}[(-3/8,3/8)\times \Cubengeq{3/8}]
                \leq C_1 \LtNorm{U}[(-7/16,7/16)\times \Cubengeq{7/16}].                
            \end{equation*}
    \end{enumerate}

