body:
[Definition def:solution of arXiv:2412.01381, 'Ergodicity and mixing for locally monotone stochastic evolution equations'] An $H$-valued continuous $({\mathcal F}_t)_{t\in [0,T]}$-adapted process $(X_t)_{t\in [0,T]}$ is called a \emph{solution} to~(equation eq:model of the paper) if for its $\mathrm{d} t\otimes\mathbb{P}$-equivalence class $\widehat{X}$, we have
\begin{enumerate}
\item For some $\tilde{\alpha}>1$, $\widehat{X}\in L^{\tilde{\alpha}}([0,T];V)\cap L^2([0,T];H)$, $\mathbb{P}$-a.s.
\item For any $V$-valued $({\mathcal F}_t)_{t\in [0,T]}$-progressively measurable $\mathrm{d} t\otimes \mathbb{P}$-version $\overline{X}$ of $\widehat{X}$ it holds that
\begin{equation*}
X_t=x+\int_0^t A(\overline{X}_s)\,\mathrm{d} s+B \,W_t,\quad t\in [0,T],\quad\mathbb{P}\text{-a.s.}
\end{equation*}
\end{enumerate}

[Proposition 2 (Compressibility plus Malliavin regularity) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Let $S>\tfrac{1}{2}$ and $s>0$. Assume that $X \in \mathcal{H}_T^2(\mathbb{R}^{d})$ is compressible with compressibility constant $C_{X}$; see Definition \ref{defn:compressibility}. Suppose, in addition, that $X \in \mathbb{D}_T^{s,2:d}$. Then, for every $N \in \mathbb{N}_{+}$ and every $P \in \mathbb{N}$, we have
\begin{equation}

    \inf_{
        \underset{
            \mathfrak{m}^{(1)},\dots,\mathfrak{m}^{(N)}\in \bigcup_{m=0}^{P} \mathfrak{C}_m
        }{
            \beta_1,\ldots,\beta_N\in \mathbb{R}^d
        }
    }
    \Big\|
        X
        -
        \sum_{n=1}^N
            \beta_n
            \mathfrak{m}^{(n)}
    \Big\|_{\mathcal{H}_T^2(\mathbb{R}^{d})}
    \lesssim_X
    N^{-(S-\frac12)}
    +
    (1+P)^{-s/2},
\end{equation}
where the symbol $``\lesssim_X"$ indicates that the bounding constant depends on $X$, but not on the approximation parameters $N$ and $P$.

[Definition def:GU of arXiv:2607.08914, 'Linear spreading speed in non-monotone population models'] Let $G^U \subseteq [0,1]^{\mathtt{Block}(0,0)}$ be the set of all $U$'s which satisfy
  \begin{enumerate}[(i)]
    \item For every $\zeta \in G_{\mathrm{loc}}^\eta(0)$,
      $n=1,\dots,T_\mathrm{bl}$, and $y \in \Supp(\xi_n^-)$
    \begin{equation}

      \delta_R( y ,F_n(\zeta,U))\in[\xi_n^-(y),\xi^+_n(y)].
    \end{equation}

    \item For every $\zeta, \zeta' \in G_{\mathrm{loc}}^\eta(0)$
    \begin{equation}

      F_{T_\mathrm{bl}}(\zeta,U)(x)
      =F_{T_\mathrm{bl}}(\zeta',U)(x)
      \quad \text{for every }
      x \in B_{2L_\mathrm{bl}}(z'),\ z' \in \{-L_\mathrm{bl}, 0, L_\mathrm{bl}\}.
    \end{equation}

    \item  If $\zeta(x)=\zeta'(x)$ for every $x \in B_{2L_\mathrm{bl}}(0)$, then
    \begin{equation}
      F_{n}(\zeta,U)(x)
      = F_{n}(\zeta',U)(x) \quad\text{for every } x \in B_{L_\mathrm{bl}/2}(0),
      \ n=1,\dots,T_\mathrm{bl}.
    \end{equation}
  \end{enumerate}

[Lemma 4 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] Let $\g\in\R$ then there exists $c>0$ such that 
\begin{equation*}
    \|\nabla g\|_{\shc^\g}\leq c\|g\|_{\shc^{\g+1}},
\end{equation*}
