[Lemma 19 of arXiv:2606.24599, '\bf Perron--Frobenius theorem for a general tree-valued growth-fragmentation-isolation pro'] \begin{enumerate}
        \item For every $1\leq q\leq 2, s\geq 0, \tt\in\TT$, we have
        $$M_s(|\cdot|^q)(\tt)\leq e^{2^{q-1}\beta q \mathbf{m}_{q}s}|\tt|^q. $$
        \item For all
        $s\ge 0,\ $ $M_s$ is a well-defined bounded operator from $\B(|\cdot|^2)$ to $\B(|\cdot|^2)$.
