body:
[Proposition prop: bdry unif of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] There exists $p_0\in[1,\infty)$ such that for every $\delta > 0$, there exists $C_\delta > 0$  such that for every $T\in(0,\infty]$ and $(\Xi^{0},u) \in \boldsymbol{\mathfrak B}^0\times \mathcal L^0$,\begin{equation} 
|\Phi^0_T(\Xi^0,u)| \leq C_\delta \|\Xi^0\|_{\boldsymbol{\mathfrak B}^0}^{p_0} + \delta \left(  \|\overline H Z_T^0(u)\|_{L^4([-1,1]\times \mathbb T^2)}^4 +\|\ell^0_T(\Xi^0,u)\|_{\mathcal H^0}^2 \right). 	
\end{equation}
Furthermore, assume that $\Xi_T^0 \rightarrow \Xi_\infty^0$ in $\boldsymbol{\mathfrak B}^0$, $u^T \rightharpoonup u^\infty$ in $\mathcal L_w^0$, and $\ell^0_T(\Xi_T^0,u^T) \rightharpoonup \ell^0_\infty(\Xi_\infty^0, u^\infty)$ in $\mathcal H^0_w$. Then
\begin{equation} 
\lim_{T\rightarrow \infty} \Phi^0_T(\Xi_T^0, u^T) = \Phi^0_\infty(\Xi_\infty^0, u^\infty). 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=(V,E)$ be a locally finite weighted graph and let $\psi\in C^{1}(0,+\infty)$ be a concave function with $\psi^\prime \left(1\right)>0$ and $H_{\psi}<\infty$.  Assume that $u:V\times[T_{1},T_{2}]\rightarrow(0,+\infty)$ satisfies
    \begin{equation*}
        \left(1-\alpha\right)\Gamma^{\psi}\left(u\right)-\psi^{\prime}\left(1\right)\frac{\partial_t u}{u}\leq\frac{c_1}{t}+c_2,
    \end{equation*}
    where $\alpha\in[0,1), c_{1}>0$ and $c_{2}\ge0$. Then for any $x,y\in V$, 
    \begin{equation*}
        u\left(x,T_1\right)\leq u\left(y,T_2\right)\left(\frac{T_2}{T_1}\right)^{\frac{c_1}{\psi^{\prime}\left(1\right)}}\exp\left(\frac{c_2}{\psi^{\prime}\left(1\right)}\left(T_2-T_1\right)+\frac{\psi^{\prime}\left(1\right)H_{\psi}\mu_{\max}d^2\left(x,y\right)}{\left(1-\alpha\right)w_{\min}\left(T_2-T_1\right)} \right).
    \end{equation*}

