[Thm coupling of arXiv:2607.28817, 'Limiting spectral distribution for the adjacency matrix of the Watts--Strogatz random grap'] With the same notation as in Theorem~(thm:mainresult of the paper), define the distributions on $Z_n$ and $U_n$ as follows:
\begin{enumerate}
    \item $Z_n$ is an $n\times n$ symmetric random matrix whose upper-triangular entries are independent, and for every $i \le j$,
    \[
        (Z_n)_{ij} =
        \begin{cases}
            \bernoulli(1 - p_n) & \mbox{if }\quad 0 < \min\big(|i-j|,\, n - |i-j|\big) \le \frac{K_n}{2}, \\
            0 & \mbox{otherwise.}
        \end{cases}
    \]

    \item $U_n$ is the adjacency matrix of an Erd\H{o}s--R\'enyi random graph of size $n$ with parameter $\frac{p_n K_n}{n}$, independent of $Z_n$. In other words, $U_n$ is an $n\times n$ symmetric random matrix independent of $Z_n$ and whose upper-triangular entries are independent and satisfy, for every $i \le j$,
    \[
        (U_n)_{ij} =
        \begin{cases}
            \bernoulli\left(\frac{p_nK_n}{n}\right) & \mbox{if }\quad i < j, \\
            0 & \mbox{if } i = j.
        \end{cases}
    \]
\end{enumerate}
Let $A_n$ denote the adjacency matrix of $WS_n(K_n, p_n)$. 
Then, under the same assumptions as in Theorem~(thm:mainresult of the paper), namely~(equation eq:assumption1 of the paper) and~(equation eq:assumption2 of the paper), there is a coupling of $A_n$ and $(Z_n, U_n)$ so that $Z_n$ and $U_n$ are independent and
\begin{equation} 
    \mu_{\frac{A_n}{\sqrt{p_nK_n}}} - \mu_{\frac{Z_n}{\sqrt{p_nK_n}} + \frac{U_n}{\sqrt{p_nK_n}}}\;\xrightarrow[n\to\infty]{}\; 0\qquad\mbox{ weakly in probability}. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] For $\mathfrak{s}>-1/2$ and $\nu>-1$ define the Hua-Pickrell $\mathbb{HP}_\mathfrak{s}$ and Bessel $\mathbb{B}_\nu$ stochastic zeta functions by:
\begin{align*}
    \mathbb{HP}_\mathfrak{s}(z)=\lim_{k\to \infty}\prod_{\substack{\mathrm{x}\in \mathcal{HP}_\mathfrak{s}\\|\mathrm{x}|>k^{-2}}}\left(1-z\mathrm{x}\right), \ \  \
    \mathbb{B}_{\nu}(z)=\prod_{\mathrm{x}\in \mathcal{IB}_{\nu}}(1-z\mathrm{x}), \ \ \forall z \in \mathbb{C}.
\end{align*}

[Thm GenLineInt of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Under the assumptions of Theorem (thm:LineInt of the paper),
suppose further that $y_{1}=0$. Then one has
\begin{equation}
\int_{0}^{1}\Phi(d\gamma_{t})=0
\end{equation}
for all smooth one-forms $\Phi(x,y)=f(x,y)dx+g(x,y)dy$ on $\mathbb{R}^{2}$
which satisfy the following two conditions:

\vspace{2mm}\noindent (i)
$\Phi(x+1,y)=\Phi(x,y)$ for all $x,y\in\mathbb{R}$;

\vspace{2mm}\noindent (ii) $\int_{0}^{1}f(x,y)dx=0$ for all $y\in\mathbb{R}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:simplex of arXiv:2606.21391, 'Extreme points and faces in the moment problem'] The convex set $K$ is a \emph{simplex}

\footnote{Simplices are called \emph{Choquet simplices} in [winkler85].}

if the convex cone 
\[
\{\lambda(x,1): \lambda\geq 0, x\in K\}\subset V\times\mathbb{R}
\] 
is a lattice in its own order [phelps01]. A \emph{$k$-simplex}, $k\in\mathbb{N}_0$,
is defined as the convex hull of any $k+1$ affinely independent points.

