[Lemma lower_bound_tail_vertex_degrees of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Let $n\in\mathbb{N}$, recall $\theta$ from~(equation eq:theta of the paper), and suppose the choice sequence $\mathbf x$ satisfies Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:geq1 of the paper) and $A_i\geq m+1$ for $i\in\{I,\ldots,n\}$ with $I\in[n]$. For any $d_{a_1},\ldots,d_{a_k},d_{f_1},\ldots,d_{f_\ell} \in [n-1]$,
\begin{equation}\begin{aligned}
&\P{\deg_n(a_v)\geq d_{a_v}\text{ for all }v\in[k],\, \deg_n(f_w)\geq d_{f_w}\text{ for all }w\in[\ell]} \\
&\geq \theta^{-\sum_{v=1}^k d_{a_v}-\sum_{w=1}^\ell d_{f_w}}\mathbb P(|\mathcal{S}_n(v)\cap [I,n]|\geq d_{v}\text{ for all }v\in\{a_1,\ldots, a_k,f_1,\ldots, f_\ell\},\tau_{k,\ell}<I).
\end{aligned}\end{equation}

