    \begin{align*}
        \exp\left(-\frac{(m-\mu_n)^2}{2\sigma_n^2}\right)&\leq\int_{m-1}^m\exp\left(-\frac{(u-\mu_n)^2}{2\sigma_n^2}\right)du\leq\exp\left(-\frac{(m-\mu_n-1)^2}{2\sigma_n^2}\right)\,.
