body:
[Lem error-steady-states of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] Let $N^\varepsilon$ and $L^\mathrm{av}$ be given as in (equation eq:eff of the paper) and (equation eq:aver-gen of the paper), respectively, and let $\hat{\rho}^\varepsilon$ and $\pi^\mathrm{av}$ be the corresponding steady states. Then, there exists $C > 0$ and $\varepsilon_0 > 0$ such that
    \begin{equation*} 
        \|\hat{\rho}^\varepsilon - \pi^\mathrm{av}\|_{\mathrm{TV}} \leq C\varepsilon
    \end{equation*}
    for all $\varepsilon \in (0,\varepsilon_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 9 (Le Gall \cite{LeGallLocTime,LeGallStFlour}) of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $N\geq 1$. 
Fix $f$ a smooth function with compact support in $\C$.
Then
\begin{equation}

\int_{S_\varepsilon(\zeta_M)} f(z) d^2 z\,
=
\sum_{n=1}^{N} (-1)^{n-1} \dfrac{1}{n!}\dfrac{(:\Theta_{\zeta_M}^{n}:,f)}{h_M(\varepsilon)^{n}}
\, + R_{N,\varepsilon}(f),
\end{equation}
where the error term $R_{N,\varepsilon}(f)$ satisfies, as $\varepsilon\to 0$,
\begin{displaymath}
\E[R_{N,\varepsilon}(f)^{2}]^{1/2} = o(\vert \log\varepsilon\vert^{-N}).
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Inverse3 of arXiv:2609.01350, 'New classes of trace-form permutation polynomials and their compositional inverses'] Let $q=2^m$, $f_2(x)=x+\gamma {\rm Tr}_{q}^{q^2} (c_1 x+ c_2 x^2+ c_3x^3+c_3x^{q+2}+x^{2q-1}),$ where $c_1 \in \mathbb F_{q^2}$, $c_2, c_3  \in \mathbb F_{q}$ and $\gamma \in \mathbb F_{q}^*$ such that $1+\gamma{\rm Tr}_q^{q^2}(c_1)=\gamma$. Then the compositional inverse of $f_2(x)$ is
\begin{equation}
  f_2^{-1}(x)=
  \begin{cases}
    \gamma^{-1}x
      & \text{if } x\in\mathbb F_q,\\[0.8em]
    x+h_2(x)+\dfrac{x^3+x^{3q}}{x^{q+1}}
      & \text{if } x\notin\mathbb F_q,\ \beta=0,\\[0.8em]
    x+h_2(x)+\dfrac{x^3+x^{3q}}{x^{q+1}}+R+\dfrac{\beta}{R}
      & \text{if } x\notin\mathbb F_q,\ \beta\neq0,\ m \text{ odd},\\[0.8em]
    x+h_2(x)+\dfrac{x^3+x^{3q}}{x^{q+1}}
      +\dfrac{\theta^{(q+2)/3}+\theta^{(2q+1)/3}}{\beta}
      & \text{if } x\notin\mathbb F_q,\ m \text{ even},
  \end{cases}
\end{equation}
where
\[
  \beta=h_2(x)^2+(x+x^q)\,h_2(x)
        +\frac{(x+x^q)^6}{x^{2q+2}}
        +\frac{(x+x^q)^4}{x^{q+1}}
        +(x+x^q)^2+x^{q+1},
\]
\[
  R=\bigg(\beta\,(x+x^q)\sum_{i=0}^{(m-1)/2}
      \Big(\frac{\beta}{(x+x^q)^2}\Big)^{4^i}\bigg)^{1/3},
\]
and, in the last case, $\theta\in\mathbb F_{q^2}\setminus\mathbb F_q$ is either
root of $\theta^2+\beta(x+x^q)\theta+\beta^3=0$ (both roots give
the same value). For $m$ even one always has $\beta\neq0$, so the
four cases are exhaustive.

[Lemma 3 ({\cite[Eq.~(3.7, 3.8)) of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] {PeltolaWuGlobalMultipleSLEs}}]

Fix $\kappa\in (0,4]$ and $2N$-polygon $(\Omega; x_1, \ldots, x_{2N})$. 
For $1\le j\le N$, let $\gamma^j$ be chordal $\SLE_{\kappa}$ in $(\Omega; x_j, x_{2N+1-j})$. Let $\PP_N^{(\kappa)}$ be the probability measure on $\bs{\gamma}=(\gamma^1, \ldots, \gamma^N)$ under which the curves are independent. Then the law of rainbow $\SLE_{\kappa}$ in $(\Omega; x_1, \ldots, x_{2N})$ has the same law as $\PP_N^{(\kappa)}$ weighted by the Radon-Nikodym derivative 
\begin{align}
\frac{\prod_{j=1}^{N}\LZtwo(\Omega;x_j,x_{2N+1-j})}{\LZ_{\rainbow}^{(\kappa)}(\Omega;x_1,\ldots,x_{2N})}\one_{\LE_{\emptyset}(\bs{\gamma})}
		\exp\left(\frac{\mathfrak{c}}{2}\blm(\Omega;\gamma^1,\ldots,\gamma^N)\right), 
\end{align}
where $\LE_{\emptyset}(\bs{\gamma}) = \{ \gamma^{j} \cap \gamma^{i}=\emptyset, \, \forall i\neq j\}$ is the event that different curves are disjoint, and $\blm$ is the Brownian loop measure defined in~\eqref{eqn::blm_def}.
In particular, we have 
\begin{align}
	\begin{split}
		\LZ_{\rainbow}^{(\kappa)}(\Omega;x_1,\ldots,x_{2N})
		= \prod_{j=1}^{N}\LZtwo(\Omega;x_j,x_{2N+1-j}) \times
		\E_N^{(\kappa)} \left[
		\one_{\LE_{\emptyset}(\bs{\gamma})}
		\exp\left(\frac{\mathfrak{c}}{2}\blm(\Omega;\gamma^1,\ldots,\gamma^N)\right)
		\right].
	\end{split}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 30 of arXiv:2607.02777, 'Hypocoercivity for Hamiltonian Diffusions \\ with Singular Drift'] Let $f\in \ccinfty(\Omega_1)$ and $\theta\in (0,1)$, then
		\begin{equation}

			\bigl\Vert \vert Q^*\nabla f\vert \,\vert\nabla\phi_1\vert \bigl\Vert^2
			\leq \frac{4(1-\theta)^{-2}}{\lmin}\Vert Q^* \nabla^2 f Q \Vert^2 + \frac{2\Ctheta}{1-\theta} \Vert Q^*\nabla f \Vert^2.
		\end{equation}

