[Lemma 21 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] Assume the conditions of Theorem~\ref{thm:clt-additive} and that $m\stackrel{\lambda}{\to}\infty$
as in \eqref{eq:lambda-scaling}.
Fix $r\in\mathbb{N}$ and distinct points $x^1,\ldots,x^r\in\mathbb{N}^d$.
Set 

\begin{equation*}
\widetilde{f}_r(m):=(\widetilde{f}(x^1;m),\ldots,\widetilde{f}(x^r;m))^\top \ \text{and} \ \
f_r:=(f(x^1),\ldots,f(x^r))^\top.
\end{equation*}

Then

\begin{equation}
\sqrt{|m|_1}\,\big(\widetilde{f}_r(m)-f_r\big)
\xrightarrow[m\stackrel{\lambda}{\to}\infty]{d}
\mathcal{N}_r(0,\Sigma_{f,r}),
\end{equation}

where, for $1\le i,j\le r$,

\begin{equation}
\Sigma_{f,r}(i,j)
=
\frac{f(x^i)\big(\mathbbm{1}_{\{x^i=x^j\}}-f(x^j)\big)}{\mu_\lambda}.
\end{equation}

