[Theorem 21 of arXiv:2606.26496, 'Homeomorphism of the Revuz correspondence under Dynkin class assumptions'] Let ${\sf A}^n,{\sf A}\in\mathbf{A}_c^+$. Denote by $\mu_n$, $\mu$ their Revuz measures in ${\sf S}_0$ for each $n$. Assume that $\mu \in {\sf S}_{D}$ and $\{\mu_n\}$ is of uniformly Dynkin. If
		\begin{equation}
		\mathbb{P}_x\left(   \lim_{n \to \infty}  {\sf A}^{n}_t= {\sf A}_t  \text{ locally uniformly in }t \text{ on }[0,+\infty) \right)=1\quad \text{q.e.}\quad x\in E,
		\end{equation}
		then $\lim_{n \to \infty} R_1 \mu_n(x)= R_1 \mu(x)$ for q.e. $x \in E$

[Proposition prop:random_apprx_noisy of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Suppose that Assumption~(assumption:main_1Lip of the paper) holds.  For every $\varepsilon>0$, 
and each $f\in \operatorname{Lip}((X,\rho);1)$ and every
$\delta_{\operatorname{net}},\delta_{\operatorname{noise}}\in(0,1)$, if
\begin{equation}

    N
    \ge
    \frac{1}{a}
    \left(\frac{4}{\varepsilon}\right)^s
    \log\left(\frac{N_{\varepsilon/4}(X,\rho)}{\delta_{\operatorname{net}}}\right)
,
\end{equation}
then the following holds with probability at-least $-\delta_{\mathrm{net}}-\delta_{\mathrm{noise}}$

\[
\begin{aligned}

\sup_{x\in\mathcal X}
 \bigl|f(x)-\mathcal E(f\mid\mathbb D_N)(x)\bigr|
 < \varepsilon
 + \sqrt{C\log\!\left(\frac{2N}{\delta_{\mathrm{noise}}}\right)}

\,\mbox{ and }\,
 \{X_n\}_{n=1}^{N}
 \text{ is an $\varepsilon$-net of }(\mathcal X,\rho)

\end{aligned}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm stochconv-(sub)crit of arXiv:2509.15790, 'Covariance matrices of volume power functionals of random simplicial complexes -- an asymp'] Let $t\delta_t^d \rightarrow 0$ and $(k,\alpha_1), (k,\alpha_2)$ be an admissible sequence with $4\alpha_i >-d+k-1$ for $i\in \{1,2\}$. Then 
\begin{equation*}
\tilde{ \mathcal{V}}_k^{(\alpha_2)} = \frac{\mu_k^{(\alpha_1+\alpha_2)}}{\mu_k^{(2\alpha_1)}}\tilde{ \mathcal{V}}_k^{(\alpha_1)}
+ \frac{\sqrt{\mu_k^{(2\alpha_1)}\mu_k^{(2\alpha_2)}-(\mu_k^{(\alpha_1+\alpha_2)})^2}}{\sqrt{(k+1)!\mu_k^{(2\alpha_1)}}} Z 
+ D_t^{(\alpha_1, \alpha_2)} 
\end{equation*}
as $t \to \infty$, with $Z\sim \mathcal N(0,1)$ independent of $\tilde{\mathcal{V}}_k^{(\alpha_1)}$ and 
$D_t^{(\alpha_1, \alpha_2)}$ satisfies ((eq:order-Dt of the paper)).

[Lemma lem:local_cluster_healing of arXiv:2607.22908, 'Epidemic Phase Transitions in the Zero-Range Process'] Consider a zero-range process on $\mathbb{Z}$ starting from an initial configuration $\eta_0$ with $k \le m$ particles. Assume all particles are infected at time 0. Then there exists a constant $c_{\textnormal{\tiny (c:single_cluster of the paper)}}>0$, depending only on $m$, $\Gamma_\pm$, and the healing rate $\delta > 0$, such that, for all $T \geq 1$,
  \begin{equation}
    \mathbb{P}^{\eta_0}\big( \text{infection survives up to time $T$} \big) \le e^{-c_{\textnormal{\tiny (c:single_cluster of the paper)}} T}.
  \end{equation}

[Theorem 28 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] A function $\phi : (0,{+\infty}) \to [0,+\infty)$ is a Bernstein function if and only if it holds that
		\begin{align}
			\phi(\lambda) = a + b \lambda + \int_{(0,{+\infty})} (1 - e^{-\lambda t}) \,\nu(dt),

		\end{align}
		where $a,b \ge 0$ and $\nu$ is a Borel measure on $(0,{+\infty})$ that satisfies $\int_{(0,{+\infty})} (1 \wedge t)\,\nu(dt) < {+\infty}$.

		Moreover, the triplet $(a,b,\nu)$ uniquely determines $ \phi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:calculus of arXiv:2609.02234, 'An $n(\log n)^{o(1)}$ bound for nested cycles without geometric crossings'] For $x\ge1$, let $\chi(x)=x\omega'(x)/\omega(x)$. Then
\[\chi(x)=\frac{2-\Gamma(x)^{-1}}{\mathcal L(x)\Lambda(x)},
\qquad0<\chi(x)<\frac{2}{\mathcal L(x)\Lambda(x)}\le\mathrm e^{-2}.\]
Consequently,
\begin{equation}
\omega(x)\le\Phi'(x)\le(1+\mathrm e^{-2})\omega(x)<2\omega(x).
\end{equation}
Moreover, for every integer $n\ge2$,
\begin{equation}
\Phi(n)-\Phi(n-1)\ge2^{-\mathrm e^{-2}}\omega(n)>\frac12\omega(n).
\end{equation}

[Lemma quadratictermlocal of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Assume that the linear measurement operator $\mathcal{A}: \mathbb{R}^{d_1 \times d_2} \rightarrow \mathbb{R}^m$ satisfies the NSP of order $r$ with constant $ \eta_r \le  3/5 $, and that for some $\mathbf{X}_\star$ of rank $r$, it holds that
 $ \mathcal{A}(\mathbf{X}) = \mathcal{A} (\mathbf{X}_\star) $ for some $ \mathbf{X} \in \mathbb{R}^{d_1 \times d_2}$. Assume that the weight operator $\W{\mathbf{X}}{\varepsilon}$ is a $q$-power mean weight operator (eq:power:mean:core:matrix of the paper) with $q \in [-1,0)$\footnote{This includes the harmonic-mean weight operator as special case with $q = -1$.}, that
\begin{equation}
	\nucnorm{\mathbf{X} - \mathbf{X}_\star} 
	\le 
	\frac{ \sigma_r \left( \mathbf{X}_\star \right) }{ \max \left( \eta_1 \sqrt{ d}, 2 \right)  },  
\end{equation}
where $0 < \eta_1 \leq \eta_r$ denotes again the order-one NSP constant of $\mathcal{A}$, and that
\begin{equation*}
\varepsilon \ge \vartheta \frac{\besterrNuc{\mathbf{X}}{r} }{d}
\end{equation*}
for some $\vartheta>0$.
Then for the constant $D_{\eta_r} = \frac{3+\eta_r}{1-\eta_r}$, it holds that 
\begin{equation*}
	\innerproduct{ \mathbf{X}_\star-  \mathbf{X} , \W{\mathbf{X}}{\varepsilon} (\mathbf{X}_\star-  \mathbf{X} ) }
	\le 
	\left(2 + 2^{-1/q}+\frac{D_{\eta_r}^2}{\vartheta}\right)  \nucnorm{\mathbf{X}-\mathbf{X}_\star}.
\end{equation*}
If $\vartheta = \frac{1-\eta_r}{(1+\eta_r)\left(\frac{3}{2}+\eta_r\right)}$, the bound reduces to
\begin{equation} 
	\innerproduct{ \mathbf{X}_\star-  \mathbf{X} , \W{\mathbf{X}}{\varepsilon} ( \mathbf{X}_\star-  \mathbf{X} ) }
	\le 
	\left(2 + 2^{-1/q}+E_{\eta_r}\right)  \nucnorm{\mathbf{X}-\mathbf{X}_\star}.
\end{equation}
with $E_{\eta_r} := \frac{(3+\eta_r)^2 (1+\eta_r)\left(\frac{3}{2}+\eta_r\right)}{(1-\eta_r)^3}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 21 (Scaling law, mixed-damping regime) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Under Assumptions~\ref{ass:diagonal-covariance} and~\ref{ass:power-law}, and the stability condition $\eta \lesssim \min\{1,B(1-\rho)\}$, for the mixed-damping regime $\eta\gtrsim(1-\rho)^2$ with $k \gtrsim \max\left\{\frac{1}{1-\rho}, \frac{1-\rho}{\eta}\right\}$, the expected excess risk satisfies:
\begin{equation}

    \EE[\cE(\btheta_k)] \eqsim \cS_{\mathrm{under}}(k) + \left(\frac{1-\rho}{\eta k}\right)^s + \frac{\sigma^2\eta}{B(1-\rho)},
\end{equation}
where the properties of the underdamped transient $\cS_{\mathrm{under}}(k)$ are established in Lemma~\ref{lem:pol_underdamped_transient_properties}.

