[Lemma lem:TV-llr of arXiv:2601.07045, 'From Continuous to Discrete: \\ a No-U-Turn Sampler for Permutations'] Let $p$ and $q$ be probability mass functions on a finite set $\mathcal{I}$ such that
\[
  e^{-\varepsilon}
  \;\le\;
  \frac{q(t)}{p(t)}
  \;\le\;
  e^{\varepsilon}
  \qquad
  \text{for all }t\in\mathcal{I}
\]
for some $\varepsilon\ge0$.
Then
\[
  \TV(p,q) \;\le\; \tanh\!\bigl(\varepsilon/2\bigr).
\]

[Lemma 26 of arXiv:2608.06523, 'On the Gardner Transition in the Ising Pure $p$-Spin Glass II'] Let $p=3$ and suppose that \eqref{mt:eq:mass}, \eqref{mt:eq:fixed}, and
$\Gamma_\mu'(q)=1$ hold.  Then
\begin{equation}
 m^2\xi'(q)>\frac52.

\end{equation}

[Proposition PROP:con of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Let $D>0$. Then, we have the free energy limit
\begin{align*}
\lim_{L\to\infty } \frac{\log Z_L}{L^3}=-\inf_{\substack{ \|\phi \|_{L^2(\mathbb{R})}^2 \le D  } } H(\phi),
\end{align*}

\noindent
where  $Z_L$ is the partition function in (equation Gibbs22 of the paper), the Hamiltonian $H$ is as in (equation Ham1 of the paper), and the infimum is taken over all $\phi \in H^1(\mathbb{R})$ satisfying  $\|\phi \|_{L^2(\mathbb{R})}^2\le D$. Moreover, for any $\delta>0$, there exists $c=c(\delta)>0$ such that 
\begin{align*}
 \rho_L\Bigg(\bigg\{  \inf_{x_0 \in \mathbb{T}_{L}, \theta \in [0,2\pi] } \| \phi-e^{i\theta}\eta(x-x_0)LQ(L(\cdot-x_0)) \|_{L^2(\mathbb{T}_L)} \ge  \delta L^{\frac 12}    \bigg\}\Bigg)\lesssim e^{-cL^3},
\end{align*}

\noindent
where $\rho_L$ is the Gibbs measure in (equation Gibbs2 of the paper), $\eta$ is the 
cutoff function in (equation cutoffeta of the paper), and $Q=Q_D$ is the minimizer arising from the variational problem with the parameter $D$ in Proposition (PROP:Min of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2506.18063, 'Reduced critical branching processes in non-favorable random environment \thanks{ This wor'] Assume that Condition $B1$ is valid and, in addition,
there exists a constant $C\in (0,\infty )$ such that
\begin{equation*}
\mathbf{P}\left( \eta \leq C\right) =1.
\end{equation*}
If the parameters $k$ and $r$ varies in such a way that
\begin{equation}
\log (n-r)\ll a_{k\wedge r}  
\end{equation}
as $n\rightarrow \infty ,$ then, for any $t>0$ and any $y\geq 0$ the
following relations are valid

1) if $n\gg k\gg r\rightarrow \infty $ then, for any $y\geq 0,$
\begin{equation*}
\lim_{r\rightarrow \infty }\mathbf{P}\left( \log Z_{r,n}\leq ya_{r}|\mathcal{
R}\left( ta_{k},n\right) \right) =C^{\ast \ast }\mathcal{H}(y),
\end{equation*}
where
\begin{equation*}
\mathcal{H}(y)=\int_{0}^{\infty }g^{+}\left( z\right) \left( z^{\alpha
(1-\rho )}-(z-y\wedge z)^{\alpha (1-\rho )}\right) dz;
\end{equation*}
2) if $n\gg k\sim \theta r\rightarrow \infty $ for some $\theta >0$ then,
for any $y\geq 0,$
\begin{equation*}
\lim_{k\rightarrow \infty }\mathbf{P}\left( \log Z_{r,n}\leq ya_{k}|\mathcal{
R}\left( ta_{k},n\right) \right) =W(\theta ^{1/\alpha }t,\theta ^{1/\alpha
}t\wedge y),
\end{equation*}
where (Proof in the paper; no proof environment follows the statement in the TeX.)

