[Proposition 12 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] For all sufficiently small $\eps$, the operator
\[
  \widetilde{\mathcal P}_\eps:
  C^{4,\alpha}_\delta(\widetilde X)\longrightarrow
  C^{0,\alpha}_{\delta-4}(\widetilde X)
\]
is an isomorphism in the following cases:
\begin{enumerate}[label=\textup{(\roman*)}]
\item if $k>2$ and $4-2k<\delta<0$, then
\begin{equation}
  \norm{\phi}_{C^{4,\alpha}_\delta}
  \le C\norm{\widetilde{\mathcal P}_\eps\phi}_{C^{0,\alpha}_{\delta-4}};
\end{equation}
\item if $k=2$ and $-1<\delta<0$, then
\begin{equation}
  \norm{\phi}_{C^{4,\alpha}_\delta}
  \le C\eps^\delta
  \norm{\widetilde{\mathcal P}_\eps\phi}_{C^{0,\alpha}_{\delta-4}}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:SmoothnessRegularityFBM of arXiv:2504.04860, 'Stochastic differential equations driven by fractional Brownian motion: dependence on the '] Let $k \in \mathbb{N}$ and $T >0$. Then, there exists a process $B^{H,k} = (B_t^{H,k})_{t \in [0,T]}$  such that:
	\begin{itemize}
		\item[(i)] For all $\omega \in \Omega$ the sample paths $(0,1) \times [0,T] \ni (H,t) \mapsto B_t^{H,k}(\omega) \in \mathbb{R}$ are continuous.
		\item[(ii)] For all $\omega \in \Omega$ and for any fixed $H \in (0,1)$ and $\lambda \in (0,H)$ the sample paths  $ [0,T] \ni t \mapsto B_t^{H,k}(\omega) \in \mathbb{R}$ are $ \lambda$-H\"older continuous. We even have, for all $0<a< b<1$ and $0<\gamma <a$, that there exists a non-negative random variable $K_{\gamma, a,b,k,T}>0$  such that
		\begin{align*}
			\sup_{H \in [a,b]} \big|B^{H,k}_t(\omega) - B^{H,k}_s(\omega)\big| \leq K_{\gamma, a,b,k,T}(\omega) |t-s|^\gamma, \qquad s,t \in [0,T].
		\end{align*}
		\item[(iii)]  For all $0<a< b <1$, $t \in [0,T]$ there exists $\Omega_{a,b,k,t} \in \mathcal{A}$ such that $\mathbf{P}(\Omega_{a,b,k,t})=1$ and
		\begin{align*}
			\frac{\partial^k}{\partial H^k} B_t^H(\omega) = B^{H,k}_t(\omega), \qquad H \in [a,b], \,\, \omega \in \Omega_{a,b,k,t}.
		\end{align*}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 (Sobolev estimates) of arXiv:2609.03558, 'Local well-posedness of the higher-order nonlinear Schr\"{o}dinger equation on the half-li'] Let $s\in\mathbb R$, $b\in \{0,1\}$. The unique solution of the Cauchy problem \eqref{cauchy1}, denoted by $y=S[y_0;0]$, belongs to $C(\mathbb{R}_t;H_x^s(\mathbb{R}))$ and satisfies the conservation law
	\begin{equation}
		\left\| y(\cdot ,t) \right\|_{H_x^s(\mathbb{R})}= \left\| y_0 \right\|_{H_x^s(\mathbb{R})},\quad t\in\mathbb{R}.
	\end{equation}
	Moreover, if  $\alpha^2+3\beta\delta\ge 0$, then $\partial_x^by\in C(\mathbb{R}_x;H_t^{\frac{s+1-b}{3}}(-T,T))$ for any $T>0$ and there exists a constant $c=c(s,T\alpha,\beta,\delta)\geq 0$ 

    such that
\begin{equation}
		\sup_{x\in\mathbb{R}}\left\|\partial_x^by(x,\cdot)\right\|_{H_t^{\frac{s+1-b}{3}}(-T,T)}\leq 
        c \left\|y_0\right\|_{H_x^s(\mathbb{R})},
	\end{equation}
	while if $\alpha^2+3\beta\delta<0,$ then $\partial_x^by\in C(\mathbb{R}_x;H_t^{\frac{s+1-b}{3}}(\mathbb{R}))$ and there is a constant $c=c(s,\alpha,\beta,\delta)\geq 0$ such that
	\begin{equation}
		\sup_{x\in\mathbb{R}}\left\|\partial_x^by(x,\cdot)\right\|_{H_t^{\frac{s+1-b}{3}}(\mathbb{R})}\leq c \left\|y_0\right\|_{H_x^s(\mathbb{R})}.
	\end{equation}

[Mylem l2 of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] For any random variable $\xi \in \operatorname{Sub}_{\varphi}(\Omega)$, 
		\begin{equation}
			\textsf{E} \exp \{\lambda \xi\} \leq \exp \left\{\varphi\left(\lambda \tau_{\varphi}(\xi)\right)\right\}, \quad \lambda \in \mathbb{R}
		\end{equation}
		holds, where $$
		\tau_{\varphi}(\xi):=\sup _{\lambda \neq 0} \frac{\varphi^{(-1)}(\log \textsf{E} \exp \{\lambda \xi\})}{|\lambda|},
		$$
		and  $\varphi^{(-1)}(\cdot)$ denotes the inverse function of $\varphi(\cdot)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn def-accessible of arXiv:2412.03067, 'Geodesic Trees and Exceptional Directions in FPP on Hyperbolic Groups'] We say that a finitely generated group $G$ is \emph{accessible} if there exists a simplicial tree ${\mathcal T}$ and a $G-$action on ${\mathcal T}$ such that
 \begin{enumerate}
 \item $G_e$ is finite for each edge $e \in {\mathcal E}({\mathcal T})$,
 \item $G_v$ has at most one end for each vertex $v \in {\mathcal V}({\mathcal T})$.
 \end{enumerate}

[Lemma 9 of arXiv:2606.30080, 'Ergodicity of reflected stochastic reaction-diffusion equations driven by space-time white'] Assume that (S1)--(S3) and (H3) hold. Let $p>2$. Define
  \begin{align*}
    h_{-}(u):=
  \begin{cases}
        -\gamma u + \inf_{0\leq v\leq u}\big(b(v) - b(0) - C_{b,\theta}\big), & u\geq 0, \\
        - C_{b,\theta}, & u\leq 0,\\
  \end{cases}
  \end{align*}
where $\gamma$ satisfies \eqref{260621.1621} with $p$ replaced by $p\nu$. Let $v_{-}$ be the unique solution to (\ref{260603.1828}) with $\tilde{b}=h_{-}$. If 
$m$ satisfies \eqref{260621.1647}, 
then
\begin{align*}
  \sup_{t\geq 0}\mathbb{E}\Big[ \sup_{x\in [0,1]}|v_{-}(t,x)|^p \Big] <\infty.
\end{align*}

[Lemma 21 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] Let $W_t$ be a Brownian motion in $\mathbb{R}^d$. Given $t_0 = 0$ and $t_1 , t_2 , \dots , t_m > 0$, let $\sigma \in S_m$ be a permutation such that $t_{\sigma(1)} \le t_{\sigma(2)} \le \dots \le t_{\sigma(m)}$ and set $\sigma(0) = 0$. For any $k < d$,
    \begin{equation}
        \mathbb{E} \left[ \prod_{i=1}^m |W(t_i) - W(t_{i-1})|^{-k} \right] \le C^m \prod_{i=1}^m |t_{\sigma(i)} - t_{\sigma(i-1)}|^{-k/2}.
    \end{equation}

