[Lem 32 of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] There exists a constant $c\in (0,1)$ such that the following three properties hold:
\begin{enumerate}
\item  
For any $\ell\in\mathrm{GoodScales}$ and $m>7\ell$,
\[
\Ppsq{B_m\in \intervalleentier{6\ell}{7\ell} 
}{B_m\leq 7\ell} \geq c.
\]

\item   For any  $\ell\in\mathrm{GoodScales}$ and $k\in \intervalleentier{6\ell}{7\ell}$,
\begin{align*}
	\Ppp{k}{\DMC(\stt_{4\ell}-1) \in \intervalleentier{5\ell}{7\ell}\,,\, \DMC(\stt_{4\ell}) \in \intervalleentier{\ell}{4\ell} }\geq c.
\end{align*}

\item  For any $\ell\in \mathrm{GoodScales}$, we can couple the golden instructions $(G_m)_{5\ell \leq m \leq 7\ell}$, with law given by \eqref{eq:red-law}, in such a way that 
	\begin{align*}
		\Pp{\forall a,a' \in \intervalleentier{5\ell}{7\ell}, \ G_a = G_{a'} }\geq c.
	\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem mainsharpness of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Let $\vec{G} = (V, \vec{E})$ be a directed vertex-transitive graph. The following statements hold:
    \begin{itemize}[nosep,left=5pt]
        \item[1.] For every $t > 0$, there exists a constant $K_{1}(\lambda_{\mathrm{c}}(t))$ such that for any $\lambda$ in $[\lambda_{\mathrm{c}}(t),2\lambda_{\mathrm{c}}(t)],$ we have
        \begin{align}
            \mathbb P_{\lambda, t}(\mathbf{0} \rightarrow \infty) \geq K _{1}(\lambda - \lambda_{\mathrm{c}}).
        \end{align} 
        \item[2.] For every $\lambda > 0$, there exists a constant $K_{2}(t_{\mathrm{c}}(\lambda)) $ such that for any $t$ in $[t_{\mathrm{c}}(\lambda),2t_{\mathrm{c}}(\lambda)],$ we have
        \begin{align}
            \mathbb P_{\lambda, t}(\mathbf{0} \rightarrow \infty) \geq K_{2} (t - t_{\mathrm{c}}).
        \end{align} 
        \item[3.] For fixed $t>0,$ and $\lambda < \lambda_{\mathrm{c}}(t),$ there exist constants $C,c>0,$ such that
        \begin{equation}
            \mathbb P_{\lambda,t}\left(|\mathcal{C}_{\mathbf{0}}| \geq n\right) \leq Ce^{-cn}, \text{ for every $n\geq0$}. 
        \end{equation}
        \item[4.] For fixed $\lambda > 0,$ and $t < t_{\mathrm{c}}(\lambda),$ there exist constants $C,c>0,$ such that
        \begin{equation}
            \mathbb P_{\lambda,t}\left(|\mathcal{C}_{\mathbf{0}}| \geq n\right) \leq Ce^{-cn}, \text{ for every $n\geq0$}. 
        \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Let $f \in \mathcal{B}^n$. For $U \subset \mathbb{R}^n$ measurable, 
   \begin{equation}
   \sup_{m \in \mathcal{T}^d(f)} m(U)  = \sup_{m \in \mathcal{T}^d(f)} m(Q(U)),
   \end{equation}
where $Q$ is defined by \eqref{Qdef}.

[Cor exampleone of arXiv:2411.00629, '\Large Transformation of Stochastic Recursions and Critical Phenomena in the Analysis of t'] {}
Under the same assumptions of (prop11112 of the paper) and with $\gamma_a$ given by (equation 1190-1 of the paper), for any $\delta>0$ such that $\gamma_a\delta<1$, the function
\begin{equation}\eta_\delta(t)=\mathbb{E}(\tilde\mathscr{X}_*(t;a,\alpha)^\delta)\end{equation}
satisfies
\begin{equation}\eta'_{\delta}=-\eta_{\delta}+a^\delta\eta_{\delta}(\alpha t),\quad \eta_\delta(0)=0,\end{equation} 
and
\begin{equation}\lim_{t\to\infty}\frac{\eta_\delta(t)}{t^{-\gamma\delta}}=1.\end{equation}

[Proposition prop:cross-area-affine of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] For a multivariate exponential Hawkes process with common decay, $\mathbb{E}[A_T^{12}]$ is a coordinate of the affine expected-signature closure in (prop:affine-sig of the paper). Equivalently,
\begin{equation}
\mathbb{E}[A_T^{12}]
=\frac12\int_0^T\left(\mathbb{E}[N^1_s\lambda^2_s]-\mathbb{E}[N^2_s\lambda^1_s]\right)\,\mathrm{d} s,

\end{equation}
and the vector of moments $\mathbb{E}[N^i_s\lambda^j_s]$ closes linearly after adjoining the Hawkes memory variables.

[Definition eqNullset of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] The measure space $ (\Omega, \mathcal{F}, \mu) $ is called complete (and $ \mu $ is said to be complete on $ \mathcal{F} $), if $ \mathcal{F} $ includes all subsets of null sets, i.e., 
    \begin{align}

        \mathcal{N} = \{ G \subset \Omega \mid  G \subset E \text{ for some $ \mu $-null set } G \} \subset \mathcal{F}.
    \end{align}

[Lemma 12 of arXiv:2608.26803, 'On bubbling of Fueter maps'] The incidence locus 
  \begin{equation*}
    \cI_n \coloneq \{ (f, \bx) \in \cB \times \cC_n \, | \, f(x_j) \in Z \text{ and } T_{x_j}f(v) \in T_{f(x_j)}Z \text{ for all } j\}
  \end{equation*}
  is a $C^1$ Banach submanifold of $\cB \times \cC_n$ of codimension $4n$.

