[Lemma lem_drift_como_conv of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] \noindent\normalfont{(a)} Let $\alpha \in (1,2)$, and $p,\delta>0$ where $p\ne\alpha-1$ and $\delta\ne(\alpha-1)/\alpha$. Then, under Assumptions~(\nameref{asm:S}) \& (\nameref{asm:C}), we have, as $t \downarrow 0$,
    \begin{align*}
        |\bm{\varpi}_{\bm{S}^t}-\bm{\varpi}_{\bm{Z}}|&=\mathcal{O}\big(G_2(t)+t^{1-1/\alpha}G(t)^{-1} 
    +(1+G_1(t))t^{\min\{1-1/\alpha,\delta\}}
    \\
    &\qquad + G(t)^{p}(1+G_1(t))^{1+p}t^{\min\{1-1/\alpha,p/\alpha\}}\big).
    \end{align*}
\noindent\normalfont{(b)} Let $\alpha \in (0,1)$. Then, under Assumptions~(\nameref{asm:S}) \& (\nameref{asm:C}) we have, as $t \downarrow 0$, 
\begin{equation*}
|\bm{\varpi}_{\bm{S}^t}-\bm{\varpi}_{\bm{Z}}|
=\mathcal{O}\big(G_2(t)+t^{p/\alpha}G(t)^{p} +t^{\delta}\big).
\end{equation*}

