body:
[Corollary cor:level-two of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Let $c=\beta-\alpha>0$ and
\begin{equation}
\lambda_\infty=\frac{\beta\mu}{c}.
\end{equation}
Then
\begin{align}
\mathbb{E}[N_T]
&=\lambda_\infty T+(\ell-\lambda_\infty)\frac{1-e^{-cT}}{c},
\\
\mathbb{E}\left[\int_0^T t\,\mathrm{d} N_t\right]
&=\frac{\lambda_\infty T^2}{2}
+(\ell-\lambda_\infty)
\frac{1-(1+cT)e^{-cT}}{c^2}
\end{align}
Moreover,
\begin{equation}
\mathbb{E}\left[S_{01}(T)\right]=\mathbb{E}\left[\int_0^T t\,\mathrm{d} N_t\right],
\qquad
\mathbb{E}\left[S_{10}(T)\right]=T\mathbb{E}[N_T]-\mathbb{E}\left[S_{01}(T)\right],
\end{equation}
and
\begin{equation}
\mathbb{E}[S^{M}_{11}(T)]-\mathbb{E}[S^{I}_{11}(T)]=\frac12\mathbb{E}[N_T].
\end{equation}

