body:
[Lemma 9 (Cai--Lu strong-convergence criterion) of arXiv:2609.01436, '2609.01436'] Suppose $N_c>0$, and let
$F\in\mathcal B_1^+([0,\infty))$ have the same mass and energy as
$F_{\mathrm{be}}$.  Then
\begin{equation}
 \abs{F(\{0\})-N_c}
 \leq\norm{F-F_{\mathrm{be}}}_1
 \leq
 2\abs{F(\{0\})-N_c}
 +C\bigl(\norm{F-F_{\mathrm{be}}}_1^\circ\bigr)^{1/3},
\end{equation}
where $C$ depends only on the common mass and energy.

[Lemma LEM:chan of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Let $L\ge 1$ and $F$ be a bounded, continuous function on $H^s(\mathbb{T}_{L^2})$ with $s<\frac 12$. Then, we have
\begin{align}
\int_{U_\varepsilon^L}F(\phi) \mu_{L^2}(d\phi)&=\iiint_{\widetilde U_\varepsilon^L} F\big(e^{i\theta}(Q^{\eta_L}_{x_0}+h) \big)e^{-\frac 12 \jb{A^{-1} Q^{\eta_L}_{x_0}, Q^{\eta_L}_{x_0} }_{L^2(\mathbb{T}_{L^2})} -\jb{ A^{-1 }Q^{\eta_L}_{x_0}, \Re h }_{L^2(\mathbb{T}_{L^2})} } \notag  \\
&\hphantom{XXXX} \cdot \det\big( \Id-W_{x_0,\theta,h}\big)  \mu^\perp_{x_0, L^2,m}(dh)d\sigma_L(x_0,\theta),

\end{align}

\noindent
where $A=(-\partial_x^2+m)^{-1}$ and 
\begin{align*}
\widetilde U^L_\varepsilon=\Big\{ (x_0,\theta,h)\in \mathbb{T}_{L^2}\times [0,2\pi]\times V^{L^2}_{x_0,0}: \|h \|_{L^2(\mathbb{T}_{L^2})}< \varepsilon  \Big\}
\end{align*}

\noindent
and $W_{x_0, \theta, h}$ is the Weingarten map on the tangent space of $\bar \mathcal{M}^L$ at $e^{i\theta}Q^{\eta_L}_{x_0}$. See (equation eqn: WM of the paper) for an explicit expression in our case. 
Here, the measure $\mu_{x_0,L^2,m }^{\perp}$ is a Gaussian measure defined on the normal space $V^{L^2}_{x_0,0}$, with $V_{x_0,0}^{L^2} \cap   H^1(\mathbb{T}_{L^2} ) \subset  H^1(\mathbb{T}_{L^2} )$ as its Cameron-Martin space, and admits the formal expression
\begin{align}
\mu_{x_0,L^2,m}^{\perp}(dh)=Z_{L^2}^{-1} e^{-\frac {1}2  \int_{\mathbb{T}_{L^2} } |\partial_x h|^2 dx -\frac m2 \int_{\mathbb{T}_{L^2}} |h|^2 dx  }  \prod_{x \in \mathbb{T}_{L^2}} dh(x).

\end{align} 

\noindent
In addition,  $d\sigma_L $ is a surface measure on the soliton manifold $\bar \mathcal{M}^L$ in (equation solm0 of the paper), parametrized by $x_0 \in \mathbb{T}_{L^2}$ and $\theta \in [0, 2\pi]$ as in (equation surff of the paper).

[Proposition 24 (Exact active and aggregation constants) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For $Q\ge2$,
\begin{align}
 \max_{p,q\le Q}
 \sum_{\substack{1\le s\le p\wedge q\\\neg(p=q=s)}}
 b_{p,q,s}
 &=a_Q,\\
 \max_{\ell\ge0}\#\{(p,q,s):p,q\le Q,\ s\le p\wedge q,
 \ p+q-2s=\ell,\ \neg(p=q=s)\}
 &=\mu_Q.
\end{align}
In particular $a_2=2,a_3=14,a_4=92,a_5=638$.
Moreover,
\begin{equation}
 a_Q\sim\frac{3\sqrt3}{4\pi}\frac{9^{Q-1}}{Q-1}.

\end{equation}

[Lem CAF of arXiv:2411.06571, 'Moment-based approach for two erratic KPZ scaling limits'] Let $\mathbf E_{\mathrm{BM}}^x$ denote expectation with respect to a standard Brownian motion on $\Bbb R$, started from $x\in\Bbb R$. There exists some universal constant $C>0$, such that uniformly over all smooth functions $\phi\ge 0$ with $\int_{\Bbb R} \phi =1,$ and all $s,t ,q\ge 0$, one has 
    \begin{align*}
        \sup_{x\in\Bbb R} \mathbf E^x_{\mathrm{BM}}\bigg[\bigg|\int_s^t \phi(B_s)ds\bigg|^q\bigg]^{1/q} &\leq Cq^{1/2} |t-s|^{1/2}\\
        \sup_{x\in\Bbb R} \mathbf E^x_{\mathrm{BM}}[e^{q \int_0^t \phi(B_s)ds}] &\leq Ce^{Cq^2 t}.
    \end{align*}

