{"artifact_digest":"sha256:7d8beb7db7a8d78420e32ff217925a5da2af7e004fa48d8a01b6fba04880430e","artifact_path":"objects/sha256/7d/7d8beb7db7a8d78420e32ff217925a5da2af7e004fa48d8a01b6fba04880430e.md","bundle_digest":"sha256:f4da3b76f8e6e24a66874318e2016e1984e8926c4c741a08ba7f953237cbb3b3","bundle_entry_key":"2602-05477-lemma-17-whitneyproperties","bundle_id":"population.tex-extract-s0_046","claim_kind":"lemma","conditions":[],"domain":"probability theory","draft":"tex-extract-v2-20260907/bundle_s0_046.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2602-05477-lemma-17-whitneyproperties","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: Estimate 
    \begin{align*}
        \rad(B)&\leq 2\Lambda^{-3}d(x_B,X\setminus \Omega) \\
        &\leq 2\Lambda^{-3}(d(x_{B'},X\setminus \Omega)+3\rad(B')+\rad(B)) \\
         &\leq 2\Lambda^{-3}(\Lambda^3\rad(B')+3\rad(B')+\rad(B)).
    \end{align*}
    Then $\rad(B)\leq (2+3/\Lambda^3)(1-2\Lambda^{3})^{-1} \leq 3\rad(B')$.    Thus, $B\subset 9B'$ and
    \begin{align*}
        \rad(B')&\leq 2\Lambda^{-3}d(x_{B'},X\setminus \Omega) \\
        &\leq 2\Lambda^{-3}(d(x_{B},X\setminus \Omega)+2\rad(B')+\rad(B)) \\
