[Definition def:gluing_of_fat of arXiv:2505.07145, 'Nonamenable Poisson zoo'] Let $A \subset \subset V(G)$ connected, $x \in \partial_{\mathrm{ext}} A$, and $\mathcal{X} = \sum_{i \in I} \delta_{(x,H)_i}$ a point measure. Then, for $i = 1,2$,
\begin{equation}

	\Phi_i(x, A, \mathcal{X}) := 
	\begin{cases}
		\Psi_i(x,A), & \text{if} \quad \forall \, y \in \{ x, \Psi_i(x,A) \}, \, \exists \, H \in \mathcal{H}_y: \, \mathcal{X}((y,H)) > 0; \\
		\emptyset, & \text{otherwise}.
	\end{cases}
\end{equation}
Again, this can be extended to any $B \subseteq \partial_{\mathrm{ext}} A$ as
\begin{equation}

	\Phi_i(B,A,\mathcal{X}) := \big\{ \Phi_i(x,A,\mathcal{X}) : {x \in B} \big\}.
\end{equation}

[Theorem 1 (Central limit theorems for partial sums) of arXiv:2506.20789, 'Central limit theory for Peaks-over-Threshold partial sums of long memory linear time seri'] Let Assumptions~\ref{asu:coef} and~\ref{asu:f} hold. Then
   \begin{align*}
     n^{-d-1/\alpha}
    \sum_{t=1}^n
    X_t
    \stackrel{\mathrm{d}}{\longrightarrow}
    Z_\alpha
    \qquad\text{as}\ n\to\infty\,,
  \end{align*}
  where
  \begin{align*}
      Z_\alpha
    &
    \ \
    \text{has distribution}
    \ \
    \begin{cases}
      \mathcal{N}(0,\sigma^2)
      &\ \ \text{if}\ \ \alpha = 2 \ \text{with $\EE[\varepsilon^2]<\infty$,}
      \\
      S\alpha S(\eta)
      &\ \ \text{if}\ \
      \alpha\in(1,2)\,,
    \end{cases}
  \end{align*}
  with
  variance
\begin{align*}
    \sigma^2
    &:=
      c_a^2\EE[\varepsilon^2]
      \frac
      {
      B(1-2d,d)}
      {d(2d+1)} \ \mbox{ when } \EE[\varepsilon^2]<\infty,
  \intertext{or scale}
  \eta
  &:=
\frac{c_a}{d}
    \cdot
    \left(
    A
    \cdot
      \frac
      {\Gamma(2-\alpha)\cos(\pi\alpha/2)}
      {1-\alpha}
      \right)^{1/\alpha}
    \left(
    \int_{-\infty}^{1}
    \left(
    (1-v)^{d}_+
    -
    (-v)^d_+
    \right)^{\alpha}
    \,\mathrm{d}v
    \right)^{1/\alpha}
      \,.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition Qtrans of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] The transition probabilities of the queuing process $Q_n$ (equation queue of the paper) can be expressed by orthogonal polynomials. Specifically, We have 
    \begin{equation}
        \mathbb{P}\left(Q_{n+1} = j| Q_1 = i\right) = \frac{1}{\left(q;q\right)_j}\int_{1 - 4c}^{1}x^n P_i\left(x\right) P_{j}\left(x\right)\psi\left(x\right) dx,
    \end{equation}
    where $P_n\left(x\right) = H_n\left(\frac{x}{2c}-\frac{1}{2c}+1\right)$, $H_n\left(x\right)$ is the $a = 1 $ continuous big q-Hermite polynomials, $\psi\left(x\right) = \frac{1}{2c} w\left(\frac{x}{2c}-\frac{1}{2c}+1\right)$, $w\left(x\right)$ is the reference measure of $H_n\left(x\right)$. 
    Equivalently, 
    \begin{equation}
        \mathbb{P}\left(Q_{n+1} = j| Q_1 = i\right) = \frac{1}{\left(q;q\right)_j}\int_{-1}^{1}\left(1-2c+2cz\right)^n H_i\left(x\right) H_{j}\left(x\right)w\left(x\right) dx.
    \end{equation}

