	\begin{equation}
		{n \choose k }_s =(-1)^k \sum\limits_{j_1+j_2+\cdots+j_s=k} {n \choose j_1} {n \choose j_2}\cdots {n \choose j_s} a^{j_1+2j_2+\cdots+sj_s},
	\end{equation}
	with $ a=\exp\left( -2\pi i/(s+1)\right)  $, where $ i^2=-1. $ 
	Since the sum is finite, we may interchange limit and summation:
	\begin{equation*}
		\begin{split}
			\lim\limits_{n\rightarrow +\infty} \frac{{ n \choose k}_s}{n^k}&= (-1)^k \sum\limits_{j_1+\cdots+j_s=k} \lim\limits_{n\rightarrow +\infty}\frac{{n \choose j_1}}{n^{j_1}} \frac{{n \choose j_2}}{n^{j_2}}\cdots \frac{{n \choose j_s}}{n^{j_s}} a^{j_1+2j_2+\cdots+sj_s}
			\\&=(-1)^k ...","release_manifest_digest":"sha256:f360a9201c9ee45a5bd608a275b39ed8a1ea14590b9ee5da0fe02bff417484a2","revision_digest":"sha256:fa6a96d2ba1213e401efa4f87cdd7bd65b994395385be84967511a8dc31ba2ee","source_id":"arxiv:2606.15178","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

