[Theorem 14 (Two-time Pfaffian kernel) of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] Let
\[
        S=\{(x_1,t_1),\ldots,(x_n,t_n)\}
        \subset\ZZ_{>0}\times\{1,2\}.
\]
Set $x_i'=x_{2n-i+1}$ and $t_i'=t_{2n-i+1}$ when an index is reflected
across the middle.  Define a $2n\times2n$ skew-symmetric matrix $M_S$ by
specifying the entries above the diagonal:
\begin{equation}
        (M_S)_{ij}=
        \begin{cases}
        K_{x_i,x_j}(t_i,t_j), & 1\leq i<j\leq n,\\
        (-1)^{x_{2n-j+1}}K_{x_i,-x_{2n-j+1}}(t_i,t_{2n-j+1}),
        & 1\leq i\leq n<j\leq2n,\\
        (-1)^{x_{2n-i+1}+x_{2n-j+1}}
        K_{-x_{2n-i+1},-x_{2n-j+1}}(t_{2n-i+1},t_{2n-j+1}),
        & n<i<j\leq2n.
        \end{cases}
\end{equation}
Then
\begin{equation}
        \rho(S)=\Pf(M_S).
\end{equation}

