[Theorem 2 of arXiv:2506.18063, 'Reduced critical branching processes in non-favorable random environment \thanks{ This wor'] Assume that Conditions $B1$ and $B2$ are valid. If $
k\sim \theta m=\theta m(n)\rightarrow \infty $ as $n\rightarrow \infty $ in
such a way that $m=o(n)$, then, for any $y\geq 0$ and $t>0$
\begin{equation}
\lim_{n\gg k\rightarrow \infty }\mathbf{P}\left( \log Z_{r,n}\leq ya_{m}|
\mathcal{R}\left( ta_{k},n\right) \right) =A(\theta ^{1/\alpha }t,\theta
^{1/\alpha }\left( t\wedge y\right) ),  
\end{equation}
where
\begin{equation*}
A(T,y)=\frac{\alpha \rho +1}{T^{1+\alpha \rho }}\int_{0}^{\infty }w^{\alpha
\rho }\mathbf{P}\left( -w\leq \min_{0\leq s\leq 1}Y_{s}\leq y-w;Y_{1}\leq
T-w\right) dw
\end{equation*}
for $y\in \lbrack 0,T].$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Them Markov_stationnaire_bis of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] Consider an interval $T$ and a stationary  positive semi-definite kernel $K :(s,t) \in T^2 \mapsto \tilde{K}(t-s) \in \mathbb{R}$ that is continuous and satisfies $\tilde{K}(0) = 1.$ We denote by $P$ a centered Gaussian measure with covariance function $K$ and set $L^K : h \in \mathbb{R}_+^* \mapsto h^{-1}(1-\tilde{K}(h)).$
		\begin{enumerate}
			\item If $\lim_{h \to 0^+} L^K(h) = \alpha \in [0, +\infty],$ then $P_\alpha$ is the strong local Markov transform of $P$.
			\item Assume $\alpha \in [0,+\infty]$ is a cluster point of $L^K$ at $0^+$ and consider a sequence of positive numbers $(s_n)_{n \geq 1}$ converging to zero that satisfies $\lim_{n \to + \infty} L^K(s_n) = \alpha$. For every $s<t \in T^2$, writing $R_n^{s,t} := \left((s_n \mathbb{Z}) \cap ]s,t[\right) \cup \{s,t\}$, we obtain $\lim_{n \to + \infty} P_{\{R_n^{s,t}\}}^{s,t} = P_{\alpha}^{s,t}$. In particular, $P_\alpha$ is a  weak local Markov transform of $P.$
		\end{enumerate}

[Proposition 5 ({\cite{LR10},\cite[Theorem 3.1) of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] {DV21+}}]

  Fix $k\in \NN$. Then for some constants $C_1,C_2,c_1,c_2$ depending on $k$, for all $x>0$ and for all $0 < \alpha < 5n^{2/3}$, we have
  \begin{align}

    \PP(P_{k,n}(x)\geq 2\sqrt{nx}+ \alpha\sqrt{x}n^{-1/6}) &\leq C_1e^{-c_1\alpha^{3/2}},\nonumber\\
    \PP(P_{k,n}(x)\leq 2\sqrt{nx}- \alpha\sqrt{x}n^{-1/6}) &\leq C_2e^{-c_2\alpha^{3}}.
  \end{align}
  Further, for some $k$-dependent constants $C_3,c_3$, all $\alpha \geq 5n^{2/3}$ and all $n$, we have
  \begin{equation}

    \PP(|P_{k,n}(x)-2\sqrt{nx}|\geq \alpha \sqrt{x} n^{-1/6})\leq C_3e^{-c_3\alpha^2 n^{-1/3}}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop thin-chaos of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $\alpha\in(0,1)$. For any $a<a_c(\alpha)$, let $\mathds A_{-a,a}$ be a subcritical two-valued set in a valid domain $D$. For any continuous, bounded  function $f:\mathbb C\to\mathbb R$, 
    \begin{align}
    \lim_{n\to \infty} (\field{e^{i\alpha \phi}}, f\1_{[\mathds A_{-a, a}]_n}) =0, 
    \end{align}
    where the limit is in probability.

