[Proposition prop:shadow1 of arXiv:2608.30973, 'Pseudo-Anosov flow and dynamics on guts'] Assume that \(\varphi\) is a almost pseudo-Anosov flow on a closed manifold \(M\) and \(S\) is an embedded surface transverse to \(\varphi\) minimally.
We fix a universal lift \(\widetilde{S}\) of \(S\) in \(\widetilde{M}\). Then,
\begin{enumerate}
\item \(\Theta(\widetilde{S})\) is an open subset of \(P_{\varphi}\),
\item \(\Theta(\widetilde{S})\) is convex, in the sense that, for any leaf \(L\) of \(\mathcal{F}^{s/u}\), the intersection \(L\cap \Theta(\widetilde{S})\) is connected.
\end{enumerate}

[Proposition eq:AKK-recovered of arXiv:2604.12136, 'Integrability of Multispecies Long-Range Swap Models with Species-Dependent Interpolation'] The rate of the transition in (equation 3452 of the paper) is
\begin{equation}
r_{n-1}^{(i)}
=
p\,\frac{\mu_i^{\,n-1}}{\mu_i^{\,n-1}+\mu_i^{\,n-2}\lambda_i+\cdots+\lambda_i^{\,n-1}}=
\frac{p}{1+\lambda_i/\mu_i+\cdots+(\lambda_i/\mu_i)^{n-1}}.
\end{equation}

[Lemma lem:dissipative of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $P_t$ be a $C_0$-semigroup with generator $(\mathsf{L},\dom(\mathsf{L}))$. It holds that:
\begin{itemize}
    \item $x_t := P_t x_0$ for $x_0 \in \dom(\mathsf{L})$ is continuous differentiable on $[0, \infty)$ and satisfies $\dot{x}_t = \mathsf{L} x_t$ with initial condition $x_t|_{t = 0} = x_0$, and $x_t \in \dom(\mathsf{L})$ for all $t \ge 0$, that is, $$P_t (\dom (\mathsf{L})) \subset \dom(\mathsf{L})\,.$$  
    \item If $P_t$ is contractive,  we have  $ \sigma(\mathsf{L}) \subset \{\lambda \in \mathbb{C}\,;\ \mathfrak{Re} \lambda \le 0\}$ and $\norm{(\lambda - \mathsf{L})^{-1}}_{\mathcal{H}} \le (\mathfrak{Re} \lambda)^{-1}$ for $\lambda \in \mathbb{C}$ with $\mathfrak{Re} \lambda > 0$. Moreover, $\mathsf{L}$ is dissipative: 
    \begin{align*}
    \mathfrak{Re} \langle x, \mathsf{L} x \rangle_{\mathcal{H}} \le 0\,,\quad \forall x \in \dom(\mathsf{L})\,.
    \end{align*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2510.24244, 'Statistical properties of Markov shifts: part II-LLT'] Define $\Delta_{j,\ell}=H_{j,\ell+1}\circ T_{j+\ell}-H_{j,\ell}-(H_{j+\ell+1}\circ T_{j+\ell}-H_{j+\ell})$. Then
\begin{equation}
 \lim_{\ell\to\infty}\sup_{j}\|\Delta_{j,\ell}\|_{j+\ell,\omega}=0.   
\end{equation}

[Lemma lem:PCneighbors of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] Let $P$ be either $P_{\lambda,\zeta}$ or $P_{\lambda, \zeta, H}$, and let $S \subseteq \Omega$ be closed under taking vertex subsets or edge subsets, respectively. Furthermore, suppose there is a $\rho > 0$ such that every $y,z \in S$ with $\mathrm{dist}(y,z) = 1$ admits a coupling of $(Py,Pz)$ such that
\begin{equation}
\mathbb{E}[\mathrm{dist}(Py,Pz)] \leq 1 - \rho.
\end{equation}
Then $P$ is $\rho$-contractive on $S$.

[Theorem 13 of arXiv:2608.21905, '\bf Ruin theory incorporating MIPP-type jumps'] Assume that $\hat{R}_n>0$ is the solution to
\begin{equation}
\begin{split}
 \lambda\bigl(g_{n-1}^{\circ}(E[e^{R\xi}]) - 1\bigr) = cR,
\end{split}
\end{equation}
then the ruin probability admits the asymptotic representation
\begin{equation*}
\begin{split}
 \Pi_n(x)\sim C_ne^{-\hat{R}_nx}\quad\text{as} \quad x\to+\infty,
\end{split}
\end{equation*}
where
\begin{equation}
\begin{split}
 C_n=\frac{c-\lambda^nm}{\lambda^nE[\xi e^{\hat{R}_n\xi}]\prod_{i=1}^{n-1}g_i^{\circ}(E[e^{\hat{R}_n\xi}])-c}.
\end{split}
\end{equation}

