[Corollary Thm: 1224 of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $\{X_k\}_{k\geq 1}$ be a d-dimensional $\alpha$-mixing and stationary sequence on a sublinear expectation space $(\Omega,\mathcal{H},\hat{\mathbb{E}})$ such that $\hat{\mathbb{E}}[|X_1|^{1+\beta}]<\infty$ for some $\beta\in (0,1]$. For any $0<\gamma_1,\gamma_2<1$, let $v^{n,\gamma}\in C_b^{1,1+\beta}(\mathbb{R}_+\times\mathbb{R}^d)$ be a solution to equation (equation PDE of the paper) with $p_{n,\gamma}(a)=\hat{\mathbb{E}}[\langle a, Y_{n,1}^{\gamma}\rangle]$ where
		\begin{equation*}
			Y_{n,1}^\gamma=\frac{1}{n_{\gamma_1}}\sum_{i=1}^{n_{\gamma_1}-n_{\gamma_1,\gamma_2}}X_i.
		\end{equation*}
		Then there exist $C(\gamma_1)>0$ and $C(\gamma_1,\gamma_2)>0$ such that 
		\begin{equation}
			\begin{split}
				v^{n,\gamma}(1,0)-\hat{\mathbb{E}}[\phi(S_n)]&\geq -C(\gamma_1)n^{-(1-\gamma_1)\beta}\int_0^1|\nabla_xv^{n,\gamma}(s,\cdot)|_{\beta}ds\times \hat{\mathbb{E}}[|X_1|^{1+\beta}]\\
				&\ \ \ \ -C(\gamma_1,\gamma_2)l_{\phi}\bigl(n^{-(1-\gamma_1)}+n^{-\gamma_1(1-\gamma_2)}\bigr)\hat{\mathbb{E}}[|X_1|]\\
				&\ \ \ \ -c_X|\nabla_xv^{n,\gamma}|_{\infty}n^{1-\gamma_1}e^{-\alpha(n^{\gamma_1\gamma_2}-1)}+\underline{f},
			\end{split}
		\end{equation}
       where $c_X$ is from (equation equ: alpha-mixing of the paper),
		$
			\underline{f}=\inf_{\{0\leq t\leq 1,x\in \mathbb{R}^d\}}f(t,x)
	$ with $f$ defined as in (equation PDE of the paper).

